PROMO_RESERVED_PREFIXES = ("/", "!", "+")


def _normalize_promo_code(raw_code: str) -> str:
    return str(raw_code or "").strip().lower()


def _promo_delete_candidates(raw_code: str) -> list[str]:
    code = _normalize_promo_code(raw_code)
    if not code:
        return []

    stripped = code.lstrip("".join(PROMO_RESERVED_PREFIXES)).strip()
    candidates = [code]
    if stripped:
        candidates.append(stripped)
        for prefix in PROMO_RESERVED_PREFIXES:
            candidates.append(f"{prefix}{stripped}")
    return list(dict.fromkeys(candidates))


