GLOBAL_WIPE_START_AT = MSK_TZ.localize(datetime(2026, 8, 1, 0, 0, 0))


def _global_wipe_months_since_start(moment: datetime) -> int:
    return (moment.year - GLOBAL_WIPE_START_AT.year) * 12 + (moment.month - GLOBAL_WIPE_START_AT.month)


def _wipe_quarter_key(moment: Optional[datetime] = None) -> str:
    now = moment or msk_now()
    return f"{now.year:04d}-{now.month:02d}"


def _is_global_wipe_period(moment: Optional[datetime] = None) -> bool:
    now = moment or msk_now()
    if now < GLOBAL_WIPE_START_AT:
        return False
    return _global_wipe_months_since_start(now) % 3 == 0


def _next_global_wipe_at(moment: Optional[datetime] = None) -> datetime:
    now = moment or msk_now()
    for add_months in range(0, 36):
        month_index = (now.month - 1) + add_months
        year = now.year + month_index // 12
        month = month_index % 12 + 1
        candidate = MSK_TZ.localize(datetime(year, month, 1, 0, 0, 0))
        if candidate < GLOBAL_WIPE_START_AT:
            continue
        if _global_wipe_months_since_start(candidate) % 3 != 0:
            continue
        if candidate > now:
            return candidate
    return GLOBAL_WIPE_START_AT


def _format_wipe_dt(moment: datetime) -> str:
    return moment.astimezone(MSK_TZ).strftime("%d.%m.%Y %H:%M МСК")


