def _list_wipe_backups() -> list[str]:
    if not os.path.isdir(WIPE_BACKUPS_DIR):
        return []
    backups = []
    for name in os.listdir(WIPE_BACKUPS_DIR):
        path = os.path.join(WIPE_BACKUPS_DIR, name)
        if os.path.isdir(path) and os.path.exists(os.path.join(path, "meta.json")):
            backups.append(path)
    return sorted(backups, key=lambda path: os.path.basename(path), reverse=True)


async def create_wipe_backup(global_wipe: bool, reason: str) -> str:
    backup_id = msk_now().strftime("%Y%m%d_%H%M%S")
    backup_path = os.path.join(WIPE_BACKUPS_DIR, backup_id)
    os.makedirs(backup_path, exist_ok=True)

    for filename in _wipe_backup_files():
        if os.path.exists(filename):
            shutil.copy2(filename, os.path.join(backup_path, filename))

    async with db_lock:
        async with DB_WRITE_LOCK:
            source = sqlite3.connect("database.db", timeout=30)
            target = sqlite3.connect(os.path.join(backup_path, "database.db"), timeout=30)
            try:
                source.backup(target)
            finally:
                target.close()
                source.close()

    meta = {
        "id": backup_id,
        "created_at": msk_now_str(),
        "type": "global",
        "reason": reason,
    }
    with open(os.path.join(backup_path, "meta.json"), "w", encoding="utf-8") as file:
        json.dump(meta, file, ensure_ascii=False, indent=4)

    backups = _list_wipe_backups()
    for old_backup in backups[10:]:
        shutil.rmtree(old_backup, ignore_errors=True)

    return backup_path


async def restore_latest_wipe_backup() -> Optional[dict]:
    global database, sql, balances, prizes, subs, banana_offers, duels, donates
    backups = _list_wipe_backups()
    if not backups:
        return None

    backup_path = backups[0]
    meta_path = os.path.join(backup_path, "meta.json")
    try:
        with open(meta_path, "r", encoding="utf-8") as file:
            meta = json.load(file)
    except Exception:
        meta = {"id": os.path.basename(backup_path)}

    async with db_lock:
        async with DB_WRITE_LOCK:
            try:
                database.rollback()
            except Exception:
                pass
            try:
                sql.close()
            except Exception:
                pass
            try:
                database.close()
            except Exception:
                pass

            backup_db = os.path.join(backup_path, "database.db")
            if os.path.exists(backup_db):
                for suffix in ("-wal", "-shm"):
                    try:
                        os.remove("database.db" + suffix)
                    except FileNotFoundError:
                        pass
                temp_db = "database.db.restore_tmp"
                shutil.copy2(backup_db, temp_db)
                os.replace(temp_db, "database.db")
                for suffix in ("-wal", "-shm"):
                    try:
                        os.remove("database.db" + suffix)
                    except FileNotFoundError:
                        pass

            for filename in _wipe_backup_files():
                source_path = os.path.join(backup_path, filename)
                if os.path.exists(source_path):
                    shutil.copy2(source_path, filename)

            database, sql = _open_main_sqlite_connection()

    balances = load_data(BALANCES_FILE)
    prizes = load_data(PRIZES_FILE)
    subs = load_json_file(SUBS_FILE)
    banana_offers = load_data(BANANA_OFFERS_FILE)
    duels = load_data(DUELS_FILE)
    donates = load_data(DONATES_FILE)
    _clear_balance_cache()
    refresh_dynamic_economy_prices()
    return meta


async def _clear_economy_storage(global_wipe: bool = False) -> None:
    async with DB_WRITE_LOCK:
        db = await connect_sqlite()
        try:
            # При любом вайпе удаляем все активированные бонусы предметов.
            # Предметы из /магазин раньше записывались в permanent_* и поэтому
            # продолжали разгонять экономику после глобального вайпа.
            for table_name in (
                "auction_items",
                "user_effects",
                "permanent_prize_effects",
                "permanent_business_effects",
            ):
                await db.execute(f"DELETE FROM {table_name}")

            # Все бизнесы должны обнуляться полностью, включая филиалы, на
            # которые были применены постоянные талисманы из /магазин.
            await db.execute("DELETE FROM businesses")
            limited_case_placeholders = ",".join("?" for _ in LIMITED_CASE_TYPES)
            await db.execute(
                f"DELETE FROM user_cases WHERE case_type NOT IN ({limited_case_placeholders})",
                list(LIMITED_CASE_TYPES),
            )

        finally:
            pass
