async def perform_economy_wipe(global_wipe: bool = True, reason: str = "schedule") -> dict:
    global balances, prizes, subs, banana_offers, duels, donates
    global_wipe = True
    backup_path = await create_wipe_backup(global_wipe=global_wipe, reason=reason)
    old_balances = load_data(BALANCES_FILE)
    top_users = _top_economy_users(old_balances)

    balances = {str(uid): _empty_economy_balance(bal) for uid, bal in old_balances.items() if isinstance(bal, dict)}
    save_data(BALANCES_FILE, balances)
    _clear_balance_cache()

    prizes = {}
    subs = {}
    banana_offers = {}
    duels = {}
    donates = {}
    save_data(PRIZES_FILE, prizes)
    save_json_file(SUBS_FILE, subs)
    save_data(BANANA_OFFERS_FILE, banana_offers)
    save_data(DUELS_FILE, duels)
    save_data(DONATES_FILE, donates)

    await _clear_economy_storage(global_wipe=global_wipe)
    for rank, (top_user_id, _total) in enumerate(top_users, start=1):
        # rebirth_amount = 0  # Отключено
        pass  # Отключено
        # await add_banana_rebirth(top_user_id, rebirth_amount)  # Отключено
    refresh_dynamic_economy_prices()
    notified_chats = await send_economy_wipe_notification()
    return {
        "type": "global",
        "reason": reason,
        "rebirth_users": top_users,
        "users_reset": len(balances),
        "notified_chats": notified_chats,
        "backup_path": backup_path,
    }


async def run_due_economy_wipes() -> Optional[dict]:
    await initialize_wipe_state()
    now = msk_now()
    quarter_key = _wipe_quarter_key(now)
    last_global = await _get_wipe_state("last_global_wipe")
    is_global_month = _is_global_wipe_period(now)

    completed_key = await _get_wipe_state("last_global_wipe_completed")
    # Совместимость со старой ошибочной версией: last_global_wipe мог быть
    # записан без реального вайпа. Отдельный completed-маркер подтверждает,
    # что очистка экономики действительно завершилась.
    wipe_required = is_global_month and (
        not last_global
        or last_global < quarter_key
        or completed_key != quarter_key
    )
    if wipe_required:
        result = await perform_economy_wipe(global_wipe=True, reason="schedule")
        await _set_wipe_state("last_global_wipe", quarter_key)
        await _set_wipe_state("last_global_wipe_completed", quarter_key)
        return result
    return None



