CASE_BULK_BUY_LIMIT = 10
CASE_BULK_OPEN_LIMIT = 10
REGULAR_CASE_SHOP_EXCLUDED_TYPES = {"admin"}


def _case_bulk_buy_quantity(payload: dict, case_def: dict, bal: dict) -> int:
    raw_quantity = str(payload.get("quantity", 1)).strip().lower()
    money_cost = int(case_def.get("money_cost", 0) or 0)
    banana_cost = int(case_def.get("banana_cost", 0) or 0)
    if raw_quantity in {"max", "макс"}:
        max_by_money = int(bal.get("wallet", 0)) // money_cost if money_cost > 0 else CASE_BULK_BUY_LIMIT
        max_by_bananas = int(bal.get("bananas", 0)) // banana_cost if banana_cost > 0 else CASE_BULK_BUY_LIMIT
        return max(1, min(CASE_BULK_BUY_LIMIT, max_by_money, max_by_bananas))
    try:
        return max(1, min(CASE_BULK_BUY_LIMIT, int(raw_quantity)))
    except Exception:
        return 1


def _case_bulk_open_quantity(payload: dict) -> int:
    raw_quantity = str(payload.get("quantity", 1)).strip().lower()
    if raw_quantity in {"max", "макс"}:
        return CASE_BULK_OPEN_LIMIT
    try:
        return max(1, min(CASE_BULK_OPEN_LIMIT, int(raw_quantity)))
    except Exception:
        return 1


def _parse_ep_quantity_text(raw_text: str) -> Optional[int]:
    cleaned = re.sub(r"[\s._,]", "", str(raw_text or ""))
    if not cleaned.isdigit():
        return None
    value = int(cleaned)
    return value if value > 0 else None


def _ep_payload_quantity(payload: dict, unit_cost: int, total_ep: int) -> int:
    raw_quantity = str(payload.get("quantity", 1)).strip().lower()
    if raw_quantity in {"max", "макс"}:
        return max(1, min(CASE_BULK_BUY_LIMIT, total_ep // max(1, int(unit_cost))))
    try:
        return max(1, min(CASE_BULK_BUY_LIMIT, int(raw_quantity)))
    except Exception:
        return 1


def _parse_case_ids_payload(payload: dict) -> list[int]:
    raw_ids = payload.get("case_ids")
    if isinstance(raw_ids, list):
        result = raw_ids
    elif isinstance(raw_ids, str):
        result = [part for part in raw_ids.split(",") if part.strip()]
    else:
        result = []
    case_ids = []
    for raw_id in result:
        try:
            case_id = int(raw_id)
        except Exception:
            continue
        if case_id > 0:
            case_ids.append(case_id)
    return case_ids


def _format_case_reward_summary(reward_texts: list[str]) -> str:
    grouped: dict[str, int] = {}
    for reward_text in reward_texts:
        grouped[reward_text] = grouped.get(reward_text, 0) + 1
    lines = []
    for reward_text, count in grouped.items():
        prefix = f"{count}x " if count > 1 else ""
        lines.append(f"• {prefix}{reward_text}")
    return "\n".join(lines)


def _add_case_reward_stat(stats: dict, reward: dict, reward_text: str) -> None:
    reward_type = str(reward.get("type", "")).lower()
    if reward_type == "money":
        stats["money"] = int(stats.get("money", 0)) + int(reward.get("amount", 0) or 0)
        stats["money_count"] = int(stats.get("money_count", 0)) + 1
        return
    if reward_type == "bananas":
        stats["bananas"] = int(stats.get("bananas", 0)) + int(reward.get("amount", 0) or 0)
        stats["bananas_count"] = int(stats.get("bananas_count", 0)) + 1
        return
    if reward_type == "vip_days":
        stats["vip_days"] = int(stats.get("vip_days", 0)) + int(reward.get("days", 0) or 0)
        stats["vip_count"] = int(stats.get("vip_count", 0)) + 1
        return
    bucket_name = "businesses" if reward_type == "business" else "items" if reward_type == "item" else "other"
    bucket = stats.setdefault(bucket_name, {})
    bucket[reward_text] = int(bucket.get(reward_text, 0)) + 1


def _format_case_reward_stats(stats: dict) -> str:
    lines = []
    if int(stats.get("money", 0)) > 0:
        lines.append(f"• Деньги: {format_number(int(stats['money']))}₽ ({int(stats.get('money_count', 0))} выпад.)")
    if int(stats.get("bananas", 0)) > 0:
        lines.append(f"• Коины: {format_number(int(stats['bananas']))} ({int(stats.get('bananas_count', 0))} выпад.)")
    if int(stats.get("vip_days", 0)) > 0:
        lines.append(f"• VIP: {format_number(int(stats['vip_days']))} дн. ({int(stats.get('vip_count', 0))} выпад.)")
    for title, bucket_name in (("Бизнесы", "businesses"), ("Предметы", "items"), ("Прочее", "other")):
        bucket = stats.get(bucket_name, {})
        if not bucket:
            continue
        lines.append(f"• {title}:")
        for reward_text, count in sorted(bucket.items(), key=lambda item: (-item[1], item[0]))[:20]:
            prefix = f"{count}x " if count > 1 else ""
            lines.append(f"  - {prefix}{reward_text}")
        if len(bucket) > 20:
            lines.append(f"  - и ещё {len(bucket) - 20} типов наград")
    return "\n".join(lines) if lines else "• Награды не найдены"


def _compact_case_reward_log(summary: str, limit: int = 1800) -> str:
    compact = summary.replace("\n", "; ")
    if len(compact) <= limit:
        return compact
    return compact[: limit - 3] + "..."


def _daily_remaining_text(delta: Optional[timedelta]) -> str:
    if not delta:
        return "доступен"
    total_minutes = max(1, int(delta.total_seconds() // 60))
    h, m = divmod(total_minutes, 60)
    return f"{h}ч {m}м"


async def _apply_event_reward(user_id: int, balance_data: dict, reward: dict) -> str:
    reward_type = str(reward.get("type", "")).lower()
    if reward_type == "money":
        amount = int(reward.get("amount", 0) or 0)
        if amount <= 0:
            raise ValueError("Для этой награды задана некорректная сумма.")
        balance_data["wallet"] = int(balance_data.get("wallet", 0)) + amount
        return f"{format_number(amount)}₽"
    if reward_type == "bananas":
        amount = int(reward.get("amount", 0) or 0)
        if amount <= 0:
            raise ValueError("Для этой награды задано некорректное количество коинов.")
        balance_data["bananas"] = int(balance_data.get("bananas", 0)) + amount
        return f"{format_number(amount)} коинов"
    if reward_type == "case":
        case_type = str(reward.get("case_type", "")).lower()
        if case_type not in CASE_DEFS:
            raise ValueError("У ивента указан неизвестный кейс.")
        quantity = max(1, int(reward.get("quantity", 1) or 1))
        case_ids = [await add_user_case(user_id, case_type) for _ in range(quantity)]
        case_name = CASE_DEFS[case_type]["name"]
        if quantity == 1:
            return f"кейс «{case_name}» (№{case_ids[0]})"
        return f"{format_number(quantity)} кейса «{case_name}» (№{', №'.join(str(case_id) for case_id in case_ids)})"
    if reward_type == "business":
        business_key = str(reward.get("business_key", "")).lower()
        if business_key not in BUSINESSES_CATALOG:
            raise ValueError("У ивента указан неизвестный бизнес.")
        quantity = max(1, int(reward.get("quantity", 1) or 1))
        try:
            branch_numbers = [await add_business(user_id, business_key) for _ in range(quantity)]
        except ValueError as error:
            raise ValueError(str(error))
        business_name = BUSINESSES_CATALOG[business_key]["name"]
        if quantity == 1:
            return f"бизнес «{business_name}» (филиал #{branch_numbers[0]})"
        branch_list = ", ".join(f"#{branch_no}" for branch_no in branch_numbers)
        return f"{format_number(quantity)} филиала бизнеса «{business_name}» ({branch_list})"
    if reward_type == "item":
        item_meta = _build_event_item_meta(
            str(reward.get("item_type", "")),
            str(reward.get("item_name", "")),
            int(reward.get("item_value", 0) or 0),
        )
        quantity = max(1, int(reward.get("quantity", 1) or 1))
        if quantity == 1:
            await add_item(
                user_id,
                item_meta["item_type"],
                item_meta["item_name"],
                item_meta["item_value"],
            )
            return f"предмет «{item_meta['item_name']}»"
        await add_items_bulk(
            user_id,
            item_meta["item_type"],
            item_meta["item_name"],
            item_meta["item_value"],
            quantity=quantity,
        )
        return f"{format_number(quantity)} предмета «{item_meta['item_name']}»"
    raise ValueError("Неизвестный тип ивентовой награды.")


async def _play_lottery_event(user_id: int, event_def: dict) -> tuple[bool, str]:
    cost = int(event_def.get("cost", LOTTERY_EVENT_COST) or LOTTERY_EVENT_COST)
    balance_data = _cached_user_balance(user_id)
    current_wallet = int(balance_data.get("wallet", 0) or 0)
    if cost <= 0:
        return False, "У этой игры не настроена стоимость."
    if current_wallet < cost:
        return False, f"Нужно {format_number(cost)}₽. У вас на руках: {format_number(current_wallet)}₽."

    updated_balance = dict(balance_data)
    updated_balance["wallet"] = current_wallet - cost

    try:
        reward = await _roll_lottery_reward(user_id)
        reward_text = await _apply_event_reward(user_id, updated_balance, reward)
    except ValueError as error:
        return False, str(error)
    except Exception as error:
        log.exception("Ошибка выдачи награды Лотыреи: %s", error)
        return False, "Не удалось выдать награду Лотыреи. Попробуйте ещё раз."

    _persist_user_balance(user_id, updated_balance)

    await log_economy(
        user_id=user_id,
        target_id=None,
        amount=cost,
        log=f"сыграл(-а) в Лотырею за {format_number(cost)}₽ и получил(-а) {reward_text}",
    )

    result_lines = [
        f"{event_def['title']}",
        "",
        f"💸 Списано за игру: {format_number(cost)}₽",
        f"🎁 Выпало: {reward_text}",
        "",
        f"💰 Кошелёк: {format_number(int(updated_balance.get('wallet', 0) or 0))}₽",
        f"🍌 Коины: {format_number(int(updated_balance.get('bananas', 0) or 0))}",
    ]
    return True, "\n".join(result_lines)


async def _redeem_vip_event_offer(user_id: int, event_def: dict, offer: dict) -> tuple[bool, str]:
    balance_data = _cached_user_balance(user_id)
    required_days = int(offer.get("days", 0) or 0)
    if required_days <= 0:
        return False, "У этого обмена некорректная стоимость VIP."

    vip_delta = _get_vip_remaining_delta(balance_data)
    required_delta = timedelta(days=required_days)
    if not vip_delta or vip_delta < required_delta:
        return False, f"Недостаточно активного VIP. Нужно {required_days}д, сейчас: {_format_vip_remaining_text(balance_data)}."

    try:
        reward_text = await _apply_event_reward(user_id, balance_data, offer["reward"])
    except ValueError as error:
        return False, str(error)
    except Exception as error:
        log.exception("Ошибка выдачи награды ивента: %s", error)
        return False, "Не удалось выдать награду. Попробуйте ещё раз."

    try:
        current_until = datetime.fromisoformat(str(balance_data["vip_until"]))
    except Exception:
        return False, "Не удалось прочитать ваш VIP-статус."

    new_until = current_until - required_delta
    now_dt = datetime.now()
    balance_data["vip_until"] = new_until.isoformat() if new_until > now_dt else None
    _persist_user_balance(user_id, balance_data)

    await log_economy(
        user_id=user_id,
        target_id=None,
        amount=None,
        log=f"обменял(-а) {required_days} дней VIP на {reward_text} во время ивента «{event_def['title']}»",
    )
    return True, f"✅ Обмен выполнен: {required_days}д VIP → {reward_text}"


async def _claim_event_bonus(user_id: int, event_id: str, event_def: dict, bonus_def: dict) -> tuple[bool, str]:
    balance_data = _cached_user_balance(user_id)
    remaining_delta = _get_event_bonus_remaining_delta(balance_data, event_id, bonus_def)
    if remaining_delta:
        return False, f"Бонус уже забран. Следующий будет доступен через {_format_compact_duration(remaining_delta)}."

    reward_money = int(bonus_def.get("reward_money", 0) or 0)
    reward_bananas = int(bonus_def.get("reward_bananas", 0) or 0)
    if reward_money <= 0 and reward_bananas <= 0:
        return False, "У этого бонуса не настроена награда."

    if reward_money > 0:
        balance_data["wallet"] = int(balance_data.get("wallet", 0)) + reward_money
    if reward_bananas > 0:
        balance_data["bananas"] = int(balance_data.get("bananas", 0)) + reward_bananas

    claims = _get_event_claims_store(balance_data)
    claims[_get_event_bonus_storage_key(event_id, bonus_def)] = msk_now().isoformat()
    _persist_user_balance(user_id, balance_data)

    reward_parts = []
    if reward_money > 0:
        reward_parts.append(f"{format_number(reward_money)}₽")
    if reward_bananas > 0:
        reward_parts.append(f"{format_number(reward_bananas)} коинов")
    reward_text = " + ".join(reward_parts)

    await log_economy(
        user_id=user_id,
        target_id=None,
        amount=reward_money if reward_money > 0 else None,
        log=f"забрал(-а) ивентовый бонус «{event_def['title']}»: {reward_text}",
    )
    return True, f"🎁 Ивентовый бонус получен: {reward_text}"


