def _format_business_roulette_returns(returned_items: list[dict]) -> str:
    if not returned_items:
        return "нет"
    grouped = {}
    for item in returned_items:
        key = (str(item["item_name"]), int(item["item_value"]))
        grouped[key] = grouped.get(key, 0) + 1
    parts = []
    for (item_name, item_value), quantity in grouped.items():
        suffix = f" x{quantity}" if quantity > 1 else ""
        parts.append(f"{item_name}{suffix}")
    return "; ".join(parts)


def _select_business_roulette_branch(branches: list[dict]) -> dict:
    def branch_score(branch: dict):
        talisman_bonus = get_business_talisman_bonus_percent(branch)
        return (
            1 if talisman_bonus > 0 else 0,
            int(branch.get("upgrade_level", 0) or 0),
            int(branch.get("branch_balance", 0) or 0),
            int(branch.get("products", 0) or 0),
            int(branch.get("branch_no", 0) or 0),
        )

    return sorted(branches, key=branch_score)[0]


def _available_branch_numbers(existing_branch_numbers: set[int], quantity: int) -> list[int]:
    result = []
    for branch_no in range(1, MAX_BRANCHES_PER_BUSINESS + 1):
        if branch_no not in existing_branch_numbers:
            result.append(branch_no)
            if len(result) >= quantity:
                return result
    return result


async def _execute_business_roulette_result(
    user_id: int,
    business: dict,
    won: bool,
    returned_items: list[dict],
) -> tuple[bool, list[int], str]:
    business_id = int(business["id"])
    business_key = str(business["business_key"])
    branch_no = int(business["branch_no"])
    reward_branch_numbers: list[int] = []

    async with DB_WRITE_LOCK:
        db = await connect_sqlite()
        try:
            cur = await db.execute(
                "SELECT id FROM businesses WHERE id = ? AND user_id = ?",
                (business_id, int(user_id)),
            )
            if not await cur.fetchone():
                return False, [], "Филиал ставки уже не найден. Попробуйте ещё раз."

            existing_cur = await db.execute(
                "SELECT branch_no FROM businesses WHERE user_id = ? AND business_key = ? AND id != ?",
                (int(user_id), business_key, business_id),
            )
            existing_branch_numbers = {int(row[0]) for row in await existing_cur.fetchall()}
            if won:
                reward_branch_numbers = _available_branch_numbers(
                    existing_branch_numbers,
                    BUSINESS_ROULETTE_REWARD_COUNT,
                )
                if len(reward_branch_numbers) < BUSINESS_ROULETTE_REWARD_COUNT:
                    return False, [], "Для выигрыша не хватает свободных слотов филиалов этого бизнеса."

            for item in returned_items:
                await db.execute(
                    "INSERT INTO inventory (user_id, item_type, item_name, item_value) VALUES (?, ?, ?, ?)",
                    (
                        int(user_id),
                        str(item["item_type"]),
                        str(item["item_name"]),
                        int(item["item_value"]),
                    ),
                )

            await db.execute(
                "DELETE FROM permanent_business_effects WHERE user_id = ? AND business_key = ? AND branch_no = ?",
                (int(user_id), business_key, branch_no),
            )
            await db.execute(
                "DELETE FROM businesses WHERE id = ? AND user_id = ?",
                (business_id, int(user_id)),
            )

            if won:
                await db.executemany(
                    "INSERT INTO businesses (user_id, business_key, branch_no, products) VALUES (?, ?, ?, ?)",
                    [
                        (int(user_id), business_key, reward_branch_no, DEFAULT_BUSINESS_PRODUCTS)
                        for reward_branch_no in reward_branch_numbers
                    ],
                )

            await db.commit()
            return True, reward_branch_numbers, ""
        finally:
            await db.close()


