def _cleanup_property_exchange_offers() -> None:
    now_ts = time.time()
    expired_offer_ids = [
        offer_id
        for offer_id, offer in property_exchange_offers.items()
        if now_ts - float(offer.get("created_at_ts", now_ts)) > PROPERTY_EXCHANGE_TTL_SECONDS
    ]
    for offer_id in expired_offer_ids:
        property_exchange_offers.pop(offer_id, None)

    expired_draft_users = [
        draft_user_id
        for draft_user_id, draft in property_exchange_drafts.items()
        if now_ts - float(draft.get("created_at_ts", now_ts)) > PROPERTY_EXCHANGE_TTL_SECONDS
    ]
    for draft_user_id in expired_draft_users:
        property_exchange_drafts.pop(draft_user_id, None)


def _banana_offer_created_ts(offer: dict) -> float:
    raw_ts = offer.get("created_at_ts")
    if raw_ts is not None:
        try:
            return float(raw_ts)
        except (TypeError, ValueError):
            pass
    raw_created_at = offer.get("created_at")
    if raw_created_at:
        try:
            return datetime.fromisoformat(str(raw_created_at)).timestamp()
        except (TypeError, ValueError):
            pass
    return time.time()


def _is_banana_offer_expired(offer: dict) -> bool:
    return time.time() - _banana_offer_created_ts(offer) > BANANA_OFFER_TTL_SECONDS


def _refund_banana_offer(offer_id: str) -> Optional[dict]:
    offer = banana_offers.pop(str(offer_id), None)
    if not offer:
        return None
    seller_id = int(offer.get("seller_id", 0) or 0)
    amount = int(offer.get("amount", 0) or 0)
    if seller_id > 0 and amount > 0:
        seller_bal = get_balance(seller_id)
        seller_bal["bananas"] = int(seller_bal.get("bananas", 0)) + amount
        _persist_user_balance(seller_id, seller_bal)
    save_data(BANANA_OFFERS_FILE, banana_offers)
    return offer


def _cleanup_expired_banana_offers() -> list[tuple[str, dict]]:
    expired_offers: list[tuple[str, dict]] = []
    for offer_id, offer in list(banana_offers.items()):
        if not _is_banana_offer_expired(offer):
            continue
        refunded_offer = _refund_banana_offer(offer_id)
        if refunded_offer:
            expired_offers.append((str(offer_id), refunded_offer))
    return expired_offers


