async def _build_talisman_branch_menu(user_id: int, item_id: int, business_key: str, page: int = 1):
    kb = Keyboard(inline=True)
    return kb, None, "Функция отключена."

    is_stackable_t34 = _is_stackable_business_talisman(item)
    filtered = [biz for biz in businesses if str(biz["business_key"]) == str(business_key)]
    if not is_stackable_t34:
        filtered = [biz for biz in filtered if int(biz.get("regular_talisman_active", 0) or 0) != 1]
    if not filtered:
        return kb, None, "Для этого бизнеса нет доступных филиалов."

    per_page = 4
    total_pages = max(1, (len(filtered) + per_page - 1) // per_page)
    page = min(max(1, page), total_pages)
    page_items = filtered[(page - 1) * per_page : (page - 1) * per_page + per_page]

    for biz in page_items:
        bonus_now = get_business_talisman_bonus_percent(biz)
        kb.add(
            Callback(
                f'{_business_emoji(biz["business_key"])} Филиал #{biz["branch_no"]}',
                {"command": "apply_talisman_choose", "item_id": item_id, "business_id": int(biz["id"]), "owner_id": user_id},
            ),
            color=KeyboardButtonColor.PRIMARY,
        ).row()

    nav_added = False
    if page > 1:
        kb.add(
            Callback(
                "⬅️ Назад",
                {"command": "apply_talisman_branch_menu", "item_id": item_id, "business_key": business_key, "page": page - 1, "owner_id": user_id},
            ),
            color=KeyboardButtonColor.SECONDARY,
        )
        nav_added = True
    if page < total_pages:
        kb.add(
            Callback(
                "➡️ Вперед",
                {"command": "apply_talisman_branch_menu", "item_id": item_id, "business_key": business_key, "page": page + 1, "owner_id": user_id},
            ),
            color=KeyboardButtonColor.SECONDARY,
        )
        nav_added = True
    if nav_added:
        kb.row()
    kb.add(
        Callback(
            "🔙 К бизнесам",
            {"command": "apply_talisman_menu", "item_id": item_id, "owner_id": user_id},
        ),
        color=KeyboardButtonColor.NEGATIVE,
    )

    business_name = filtered[0]["meta"]["name"]
    text = (
        f"🪬 Выберите филиал бизнеса «{business_name}» [{page}/{total_pages}].\n"
        f"{'Показаны все филиалы этого бизнеса.' if is_stackable_t34 else 'Показаны только филиалы без обычного талисмана.'}\n"
        f"После активации выбранный филиал получит +{_business_talisman_bonus_percent(item)}% к доходу."
    )
    return kb, page, text


def _item_banana_value(item: dict) -> int:
    item_type = str(item.get("item_type", "") or "").lower()
    item_name = str(item.get("item_name", "") or "").lower()
    item_value = int(item.get("item_value", 0) or 0)

    if "купальные плавки ярика массериа" in item_name or "плавки ярика массериа" in item_name:
        return 1_000_000
    if "корона курорта" in item_name:
        return 650
    if "коктейльный ускоритель" in item_name:
        return 450
    if "турбо-вентилятор инвестора" in item_name:
        return 350
    if "пляжная франшиза" in item_name:
        return 275
    if "золотой шезлонг" in item_name:
        return 220
    if "фестиваль на пирсе" in item_name:
        return 180
    if "сёрф-пропуск" in item_name or "серф-пропуск" in item_name:
        return 100
    if "лимонадный браслет" in item_name:
        return 60
    if item_type == "season_collectible":
        if "знамя победы" in item_name or "парадная фуражка" in item_name:
            return 180
        if "фронтовая каска" in item_name or "плащ-палатка" in item_name:
            return 120
        if "панама" in item_name or "фляга" in item_name or "планшет" in item_name:
            return 90
        return 75
    if "катюша" in item_name:
        return 150
    if "медаль" in item_name and "отвагу" in item_name:
        return 150
    if "орден победы" in item_name:
        return 150
    if "танк т-34" in item_name:
        return 250
    if "звание героя войны" in item_name:
        return 250
    if item_type == "business_talisman" or "талисман" in item_name:
        return 250
    if item_value >= 50 or "легендар" in item_name:
        return 150
    if item_value >= 25 or "эпическ" in item_name:
        return 50
    return 25


async def finalize_expired_auctions():
    now_dt = datetime.now()
    notifications = []
    economy_logs = []
    async with DB_WRITE_LOCK:
        db = await connect_sqlite()
        try:
            db.row_factory = aiosqlite.Row
            cur = await db.execute(
                "SELECT id, seller_id, item_type, item_name, item_value, current_bid, highest_bidder_id, created_at, ends_at "
                "FROM auction_items",
            )
            expired = [
                dict(row)
                for row in await cur.fetchall()
                if (_resolve_auction_ends_at(dict(row)) or now_dt) <= now_dt
            ]
            if not expired:
                return 0

            balances_data = load_data(BALANCES_FILE)
            for lot in expired:
                lot = normalize_public_item(lot)
                highest_bidder_id = lot.get("highest_bidder_id")
                if highest_bidder_id:
                    await db.execute(
                        "INSERT INTO inventory (user_id, item_type, item_name, item_value) VALUES (?, ?, ?, ?)",
                        (int(highest_bidder_id), lot["item_type"], lot["item_name"], int(lot["item_value"])),
                    )
                    notifications.append(
                        (
                            int(highest_bidder_id),
                            f"🏛 Вы успешно купили на аукционе предмет «{lot['item_name']}» "
                            f"со ставкой {format_number(int(lot['current_bid']))}₽.\n"
                            "🎒 Чтобы посмотреть предмет, пропишите /инв в любом чате с ботом.",
                        )
                    )
                    seller_bal = balances_data.get(str(lot["seller_id"])) or get_balance(int(lot["seller_id"]))
                    seller_bal["wallet"] = seller_bal.get("wallet", 0) + int(lot["current_bid"])
                    balances_data[str(lot["seller_id"])] = seller_bal
                    economy_logs.append(
                        (
                            int(lot["seller_id"]),
                            int(highest_bidder_id),
                            int(lot["current_bid"]),
                            f"получил(-а) {int(lot['current_bid'])}₽ за продажу предмета «{lot['item_name']}» на аукционе",
                        )
                    )
                    economy_logs.append(
                        (
                            int(highest_bidder_id),
                            int(lot["seller_id"]),
                            int(lot["current_bid"]),
                            f"купил(-а) на аукционе предмет «{lot['item_name']}» за {int(lot['current_bid'])}₽",
                        )
                    )
                else:
                    await db.execute(
                        "INSERT INTO inventory (user_id, item_type, item_name, item_value) VALUES (?, ?, ?, ?)",
                        (int(lot["seller_id"]), lot["item_type"], lot["item_name"], int(lot["item_value"])),
                    )
                await db.execute("DELETE FROM auction_items WHERE id = ?", (int(lot["id"]),))

            await db.commit()
        finally:
            await db.close()

    balances.update(balances_data)
    save_data(BALANCES_FILE, balances)
    _clear_balance_cache()

    for peer_id, message_text in notifications:
        try:
            await bot.api.messages.send(peer_id=peer_id, random_id=0, message=message_text)
        except Exception as notify_error:
            print(f"[AUCTION WINNER DM ERROR] {notify_error}")

    for log_user_id, log_target_id, log_amount, log_text in economy_logs:
        await log_economy(
            user_id=log_user_id,
            target_id=log_target_id,
            amount=log_amount,
            log=log_text,
        )
    return len(expired)


def format_vk_link(user_id: int, name: str) -> str:
    safe_name = str(name).replace("]", ")").replace("\n", " ").replace("\r", " ")
    if int(user_id) < 0:
        return f"[club{abs(int(user_id))}|{safe_name}]"
    return f"@id{int(user_id)} ({safe_name})"


def format_vk_profile_link(user_id: int, name: str) -> str:
    safe_name = str(name).replace("]", ")").replace("\n", " ").replace("\r", " ")
    if int(user_id) < 0:
        return f"[club{abs(int(user_id))}|{safe_name}]"
    return f"[id{int(user_id)}|{safe_name}]"


async def get_vk_entity_name(entity_id: int) -> str:
    entity_id = int(entity_id)
    now_ts = time.time()
    cached = vk_entity_name_cache.get(entity_id)
    if cached and cached[1] > now_ts:
        return cached[0]
    name = "Не удалось получить имя"
    try:
        if entity_id < 0:
            group_id = abs(entity_id)
            group_info = await bot.api.groups.get_by_id(group_ids=str(group_id))
            if isinstance(group_info, list) and group_info:
                name = str(getattr(group_info[0], "name", "") or name)
                vk_entity_name_cache[entity_id] = (name, time.time() + VK_ENTITY_NAME_CACHE_TTL_SECONDS)
                return name
            if hasattr(group_info, "groups") and group_info.groups:
                name = str(getattr(group_info.groups[0], "name", "") or name)
                vk_entity_name_cache[entity_id] = (name, time.time() + VK_ENTITY_NAME_CACHE_TTL_SECONDS)
                return name
            if hasattr(group_info, "name"):
                name = str(getattr(group_info, "name", "") or name)
                vk_entity_name_cache[entity_id] = (name, time.time() + VK_ENTITY_NAME_CACHE_TTL_SECONDS)
                return name
            vk_entity_name_cache[entity_id] = (name, time.time() + 30)
            return name
        user_info = await bot.api.users.get(user_ids=entity_id)
        if user_info:
            name = f"{user_info[0].first_name} {user_info[0].last_name}"
    except Exception:
        pass
    vk_entity_name_cache[entity_id] = (name, time.time() + VK_ENTITY_NAME_CACHE_TTL_SECONDS)
    return name


async def get_chat_display_info(
    chat_id: int,
    *,
    refresh_live: bool = True,
    fetch_invite_link: bool = True,
) -> tuple[str, str | None]:
    chat_id = int(chat_id)
    peer_id = 2000000000 + chat_id
    cached_title = None
    cached_link = None

    try:
        sql.execute("SELECT chat_title, invite_link FROM chats WHERE chat_id = ?", (chat_id,))
        row = sql.fetchone()
        if row:
            cached_title = row[0]
            cached_link = row[1]
    except Exception:
        pass

    if not cached_title:
        try:
            sql.execute("SELECT chat_title FROM server_links WHERE chat_id = ?", (chat_id,))
            row = sql.fetchone()
            if row and row[0]:
                cached_title = row[0]
        except Exception:
            pass

    title = cached_title or f"Беседа #{chat_id}"
    link = cached_link if isinstance(cached_link, str) and cached_link.startswith("http") else None
    updated = False

    if not refresh_live:
        return title, link

    try:
        response = await bot.api.messages.get_conversations_by_id(peer_ids=peer_id)
        if response.items:
            live_title = getattr(response.items[0].chat_settings, "title", None)
            if live_title:
                title = live_title
                updated = True
    except Exception as error:
        print(f"[get_chat_display_info] Не удалось получить название чата {chat_id}: {error}")

    if fetch_invite_link:
        try:
            link_response = await bot.api.messages.get_invite_link(peer_id=peer_id, reset=0)
            live_link = getattr(link_response, "link", None)
            if isinstance(live_link, str) and live_link.startswith("http"):
                link = live_link
                updated = True
        except Exception as error:
            error_text = str(error).lower()
            if "invite link" not in error_text and "can't see" not in error_text:
                print(f"[get_chat_display_info] Не удалось получить ссылку чата {chat_id}: {error}")

    if updated:
        try:
            sql.execute(
                "UPDATE chats SET chat_title = ?, invite_link = ? WHERE chat_id = ?",
                (title, link, chat_id),
            )
            sql.execute(
                "UPDATE server_links SET chat_title = ? WHERE chat_id = ?",
                (title, chat_id),
            )
            database.commit()
        except Exception as error:
            print(f"[get_chat_display_info] Не удалось сохранить данные чата {chat_id}: {error}")

    return title, link


def format_chat_link_text(link: str | None) -> str:
    if isinstance(link, str) and link.startswith("http"):
        return f"[{link}|Ссылка на чат]"
    return "Ссылка на чат недоступна"


async def get_chat_availability(chat_id: int) -> tuple[bool, str]:
    chat_id = int(chat_id)
    peer_id = 2000000000 + chat_id
    try:
        response = await bot.api.messages.get_conversations_by_id(peer_ids=peer_id)
        if not getattr(response, "items", None):
            return False, "чат недоступен или удалён"
    except Exception as error:
        return False, f"чат недоступен: {str(error)[:80]}"

    try:
        members = await bot.api.messages.get_conversation_members(peer_id=peer_id)
        bot_member_id = -abs(int(groupid))
        for member in getattr(members, "items", None) or []:
            member_id = int(getattr(member, "member_id", 0) or 0)
            if member_id != bot_member_id:
                continue
            if bool(getattr(member, "is_admin", False) or getattr(member, "is_owner", False)):
                return True, "ok"
            return False, "у бота нет прав администратора"
        return False, "бот не найден среди участников"
    except Exception as error:
        return False, f"не удалось проверить права бота: {str(error)[:80]}"


async def get_active_registered_chats(
    *,
    force_refresh: bool = False,
) -> tuple[list[tuple[int, int]], list[tuple[int, int, str]]]:
    now_ts = time.time()
    if not force_refresh and float(registered_chats_cache.get("expires_at", 0.0) or 0.0) > now_ts:
        return (
            list(registered_chats_cache.get("active_rows", []) or []),
            list(registered_chats_cache.get("inactive_rows", []) or []),
        )

    async with registered_chats_cache_lock:
        now_ts = time.time()
        if not force_refresh and float(registered_chats_cache.get("expires_at", 0.0) or 0.0) > now_ts:
            return (
                list(registered_chats_cache.get("active_rows", []) or []),
                list(registered_chats_cache.get("inactive_rows", []) or []),
            )

        active_rows, inactive_rows = await _load_active_registered_chats_uncached()
        registered_chats_cache["active_rows"] = list(active_rows)
        registered_chats_cache["inactive_rows"] = list(inactive_rows)
        registered_chats_cache["expires_at"] = time.time() + REGISTERED_CHATS_CACHE_TTL_SECONDS
        return list(active_rows), list(inactive_rows)


async def _load_active_registered_chats_uncached() -> tuple[list[tuple[int, int]], list[tuple[int, int, str]]]:
    sql.execute("SELECT chat_id, owner_id FROM chats ORDER BY chat_id ASC")
    rows = [(int(row[0]), int(row[1] or 0)) for row in sql.fetchall()]
    check_semaphore = asyncio.Semaphore(REGISTERED_CHAT_CHECK_CONCURRENCY)

    async def check_row(row: tuple[int, int]) -> tuple[bool, int, int, str]:
        chat_id_row, owner_id = row
        try:
            async with check_semaphore:
                is_active, reason = await asyncio.wait_for(
                    get_chat_availability(chat_id_row),
                    timeout=REGISTERED_CHAT_CHECK_TIMEOUT_SECONDS,
                )
        except asyncio.TimeoutError:
            is_active, reason = False, "таймаут проверки беседы"
        except Exception as error:
            is_active, reason = False, f"ошибка проверки: {str(error)[:80]}"
        return is_active, chat_id_row, owner_id, reason

    checked_rows = await asyncio.gather(*(check_row(row) for row in rows))
    active_rows: list[tuple[int, int]] = []
    inactive_rows: list[tuple[int, int, str]] = []
    for is_active, chat_id_row, owner_id, reason in checked_rows:
        if is_active:
            active_rows.append((chat_id_row, owner_id))
        else:
            inactive_rows.append((chat_id_row, owner_id, reason))

    return active_rows, inactive_rows


async def build_chats_registry_page(rows: list[tuple[int, int]], page: int, per_page: int = 20) -> tuple[str, int]:
    total = len(rows)
    max_page = max(1, (total + per_page - 1) // per_page)
    page = max(1, min(int(page or 1), max_page))
    start = (page - 1) * per_page
    end = start + per_page
    selected = rows[start:end]
    line_semaphore = asyncio.Semaphore(8)

    async def build_selected_line(idx: int, chat_id_row: int, owner_id: int) -> str:
        async with line_semaphore:
            return await build_chat_registry_line(idx, chat_id_row, owner_id)

    formatted = await asyncio.gather(
        *(
            build_selected_line(idx, chat_id_row, owner_id)
            for idx, (chat_id_row, owner_id) in enumerate(selected, start=start + 1)
        )
    )
    return "\n".join(formatted) or "Беседы отсутствуют!", max_page


async def build_chat_registry_line(index: int, chat_id: int, owner_id: int) -> str:
    chat_title, chat_link = await get_chat_display_info(chat_id, refresh_live=False, fetch_invite_link=False)
    owner_name = await get_vk_entity_name(owner_id)
    return f"{index}) {chat_id} | {chat_title} | {format_vk_link(owner_id, owner_name)} | {format_chat_link_text(chat_link)}"


async def collect_all_business_income(user_id: int):
    businesses = await get_user_businesses(user_id)
    total_income = 0
