def _get_active_duel_for_chat(peer_id: int | str):
    peer_id = str(peer_id)
    duel = duels.get(peer_id)
    if isinstance(duel, dict) and duel.get("author") and duel.get("stake"):
        expires_at = duel.get("expires_at")
        if expires_at:
            try:
                if datetime.now() >= datetime.fromisoformat(expires_at):
                    duels.pop(peer_id, None)
                    save_data(DUELS_FILE, duels)
                    return None
            except Exception:
                pass
        return duel
    return None


async def _cancel_duel_if_unanswered(peer_id: str, delay_seconds: int = 60):
    await asyncio.sleep(delay_seconds)
    duel = duels.get(peer_id)
    if not duel or duel.get("accepted"):
        return
    expires_at = duel.get("expires_at")
    if expires_at:
        try:
            if datetime.now() < datetime.fromisoformat(expires_at):
                return
        except Exception:
            pass
    message_id = duel.get("message_id")
    try:
        if message_id:
            await delete_message(groupid, int(peer_id), int(message_id))
    except Exception:
        pass
    duels.pop(peer_id, None)
    save_data(DUELS_FILE, duels)


async def sync_user_business_income(user_id: int):
    businesses = await get_user_businesses(user_id)
    synced = 0
    total_income = 0
    now_iso = datetime.now().isoformat()
    now_dt = datetime.now()
    updates = []
    for biz in businesses:
        if get_business_collect_seconds_left(biz) > 0:
            continue
        products = int(biz.get("products", 0))
        products_to_spend = BUSINESS_PRODUCTS_PER_COLLECT if products >= BUSINESS_PRODUCTS_PER_COLLECT else 0
        daily_income = _business_income_per_day(biz)
        if products_to_spend >= BUSINESS_PRODUCTS_PER_COLLECT and daily_income > 0:
            # Рассчитываем количество пропущенных дней
            last_collected_at = biz.get("last_collected_at")
            days_elapsed = 1  # По умолчанию 1 день
            if last_collected_at:
                try:
                    last_dt = datetime.fromisoformat(str(last_collected_at))
                    delta = now_dt - last_dt
                    total_seconds = delta.total_seconds()
                    days_elapsed = max(1, int(total_seconds / 86400))  # 86400 секунд в дне
                except (TypeError, ValueError):
                    days_elapsed = 1
            # Умножаем доход на количество пропущенных дней
            accumulated_income = daily_income * days_elapsed
            current_balance = int(biz.get("branch_balance", 0) or 0)
            new_balance = current_balance + int(accumulated_income)
            new_products = max(0, products - products_to_spend)
            updates.append((new_products, sqlite_int_or_text(new_balance), now_iso, int(biz["id"])))
            synced += 1
            total_income += int(accumulated_income)
    if not updates:
        return synced, total_income
    try:
        async with DB_WRITE_LOCK:
            db = await connect_sqlite()
            try:
                await db.executemany(
                    "UPDATE businesses SET products = ?, branch_balance = ?, last_collected_at = ? WHERE id = ?",
                    updates,
                )
                await db.commit()
            finally:
                await db.close()
    except sqlite3.OperationalError as e:
        print(f"[sync_user_business_income] DB error: {e}")
    except OverflowError as e:
        print(f"[sync_user_business_income] integer overflow: {e}")
    return synced, total_income


async def ensure_user_business_auto_sync(user_id: int, force: bool = False):
    user_id = int(user_id)
    now_ts = time.monotonic()
    last_sync_ts = business_auto_sync_cache.get(user_id, 0.0)
    if not force and now_ts - last_sync_ts < BUSINESS_AUTO_SYNC_INTERVAL_SECONDS:
        return 0, 0

    sync_lock = business_auto_sync_locks.setdefault(user_id, asyncio.Lock())
    if sync_lock.locked() and not force:
        return 0, 0

    async with sync_lock:
        now_ts = time.monotonic()
        last_sync_ts = business_auto_sync_cache.get(user_id, 0.0)
        if not force and now_ts - last_sync_ts < BUSINESS_AUTO_SYNC_INTERVAL_SECONDS:
            return 0, 0

        try:
            synced, total_income = await asyncio.wait_for(
                sync_user_business_income(user_id),
                timeout=BUSINESS_AUTO_SYNC_TIMEOUT_SECONDS,
            )
            business_auto_sync_cache[user_id] = time.monotonic()
            return synced, total_income
        except asyncio.TimeoutError:
            print(f"[BUSINESS AUTO SYNC TIMEOUT] user_id={user_id}")
        except Exception as error:
            print(f"[BUSINESS AUTO SYNC ERROR] user_id={user_id}: {error}")
        return 0, 0


def _format_business_collect_cooldown(branch: dict) -> str:
    seconds_left = get_business_collect_seconds_left(branch)
    if seconds_left <= 0:
        products = int(branch.get("products", 0) or 0)
        if products < BUSINESS_PRODUCTS_PER_COLLECT:
            return f"нужно {BUSINESS_PRODUCTS_PER_COLLECT} продуктов (сейчас {products}/100)"
        return "готов к сбору"
    days, remainder = divmod(seconds_left, 86400)
    hours, remainder = divmod(remainder, 3600)
    minutes, seconds = divmod(remainder, 60)
    parts = []
    if days > 0:
        parts.append(f"{days}д")
    parts.append(f"{hours:02d}ч")
    parts.append(f"{minutes:02d}м")
    parts.append(f"{seconds:02d}с")
    return " ".join(parts)


def _format_business_collect_ready_label(branch: dict) -> str:
    seconds_left = get_business_collect_seconds_left(branch)
    if seconds_left <= 0:
        products = int(branch.get("products", 0) or 0)
        if products < BUSINESS_PRODUCTS_PER_COLLECT:
            return "после пополнения склада"
        return "сейчас"
    ready_at = get_business_collect_ready_at(branch)
    if ready_at is None:
        return "неизвестно"
    return ready_at.strftime("%d.%m %H:%M:%S")


