    kb.add(Callback("Доход к бизнесу", {"command": "inventory_page", "owner_id": user_id, "page": 1, "section": "business"}), color=KeyboardButtonColor.PRIMARY if section == "business" else KeyboardButtonColor.SECONDARY).row()
