async def _remove_inventory_items_bulk(user_id: int, item_ids: list[int]) -> None:
    if not item_ids:
        return
    async with DB_WRITE_LOCK:
        db = await connect_sqlite()
        try:
            placeholders = ",".join("?" for _ in item_ids)
            await db.execute(
                f"DELETE FROM inventory WHERE user_id = ? AND id IN ({placeholders})",
                [int(user_id), *[int(item_id) for item_id in item_ids]],
            )
            await db.commit()
        finally:
            await db.close()


async def _apply_prize_items_bulk(user_id: int, prize_items: list) -> int:
    # Бонусы к призу отключены
    if not prize_items:
        return 0
    # Удаляем предметы из инвентаря, но не начисляем бонус
    await _remove_inventory_items_bulk(user_id, [int(item["id"]) for item in prize_items])
    return 0


