def _build_case_buy_quantity_menu(user_id: int, case_type: str):
    if case_type not in CASE_DEFS or CASE_DEFS[case_type]["daily"]:
        return None, "Недоступный кейс."
    if case_type in REGULAR_CASE_SHOP_EXCLUDED_TYPES:
        return None, "Админ кейс доступен только в /epoints."
    case_def = CASE_DEFS[case_type]
    kb = Keyboard(inline=True)
    kb.add(
        Callback("Купить x1", {"command": "buy_case", "case_type": case_type, "owner_id": user_id, "quantity": 1}),
        color=KeyboardButtonColor.POSITIVE,
    )
    kb.add(
        Callback("x5", {"command": "buy_case", "case_type": case_type, "owner_id": user_id, "quantity": 5}),
        color=KeyboardButtonColor.SECONDARY,
    )
    kb.add(
        Callback("MAX", {"command": "buy_case", "case_type": case_type, "owner_id": user_id, "quantity": "max"}),
        color=KeyboardButtonColor.SECONDARY,
    ).row()
    kb.add(Callback("⬅️ К кейсам", {"command": "case_menu", "owner_id": user_id}), color=KeyboardButtonColor.SECONDARY)
    price_parts = []
    if int(case_def.get("money_cost", 0) or 0) > 0:
        price_parts.append(f"{format_number(int(case_def['money_cost']))}₽")
    if int(case_def.get("banana_cost", 0) or 0) > 0:
        price_parts.append(f"{format_number(int(case_def['banana_cost']))} коинов")
    price_text = " + ".join(price_parts) if price_parts else "бесплатно"
    return kb, f"🎁 Выбран кейс: {case_def['name']}\nЦена за 1: {price_text}\n\nСколько купить?"


async def send_case_purchase_result(
    peer_id: int,
    user_id: int,
    case_type: str,
    quantity: int,
    case_ids: list[int],
    *,
    footer: str = "",
) -> None:
    case_def = CASE_DEFS[case_type]
    buyer_name = await get_user_name(user_id, None)
    kb = Keyboard(inline=True)
    if case_ids:
        first_case_id = int(case_ids[0])
        kb.add(
            Callback("Открыть x1", {"command": "open_case", "case_type": case_type, "owner_id": user_id, "case_id": first_case_id, "quantity": 1}),
            color=KeyboardButtonColor.POSITIVE,
        )
        if quantity >= 5:
            kb.add(
                Callback("x5", {"command": "open_case", "case_type": case_type, "owner_id": user_id, "case_id": first_case_id, "quantity": 5}),
                color=KeyboardButtonColor.SECONDARY,
            )
        if quantity >= 2:
            open_max = min(CASE_BULK_OPEN_LIMIT, quantity)
            if open_max != 5:
                kb.add(
                    Callback(f"x{open_max}", {"command": "open_case", "case_type": case_type, "owner_id": user_id, "case_id": first_case_id, "quantity": open_max}),
                    color=KeyboardButtonColor.POSITIVE,
                )
        kb.row()
    kb.add(Callback("Мои кейсы", {"command": "my_cases", "owner_id": user_id}), color=KeyboardButtonColor.SECONDARY)
    purchase_image = CASE_PURCHASE_IMAGES.get(case_type)
    purchase_attachment = await upload_message_photo(peer_id, purchase_image) if purchase_image else None
    case_numbers = ", ".join(f"#{case_id}" for case_id in case_ids[:10])
    if len(case_ids) > 10:
        case_numbers += f" и ещё {len(case_ids) - 10}"
    if not case_numbers:
        case_numbers = "не удалось определить номера"
    text = (
        f"@id{user_id} ({buyer_name}) успешно купил {case_def['name']} x{quantity}.\n"
        f"Кейсы добавлены на склад: {case_numbers}.\n"
        "Нажмите кнопку ниже или используйте /открытькейс [номер]."
    )
    if footer:
        text += f"\n\n{footer}"
    purchase_send_kwargs = {
        "peer_id": peer_id,
        "random_id": 0,
        "keyboard": kb,
        "message": text,
    }
    if purchase_attachment:
        purchase_send_kwargs["attachment"] = purchase_attachment
    await bot.api.messages.send(**purchase_send_kwargs)


async def handle_ep_shop_text_input(message: Message, user_id: int, chat_id: int) -> bool:
    state = ep_shop_inputs.get(int(user_id))
    if not state:
        return False

    raw_text = (message.text or "").strip()
    if not raw_text or raw_text.startswith(BOT_COMMAND_PREFIXES):
        return False

    if time.time() - float(state.get("created_at", 0) or 0) > EP_INPUT_TTL_SECONDS:
        ep_shop_inputs.pop(int(user_id), None)
        await message.reply("Время ввода количества EP истекло. Откройте /епоинтс заново.", disable_mentions=1)
        return True

    role = await get_role(user_id, chat_id)
    if not _role_can_satisfy_standard_min(role, 9):
        ep_shop_inputs.pop(int(user_id), None)
        await message.reply("Недостаточно прав!", disable_mentions=1)
        return True

    quantity = _parse_ep_quantity_text(raw_text)
    if quantity is None:
        await message.reply("Введите количество EP числом. Например: 10", disable_mentions=1)
        return True

    total_ep = await get_total_epoints(user_id)
    if total_ep < quantity:
        await message.reply(f"Недостаточно Epoints. Нужно {format_number(quantity)} EP, у вас {format_number(total_ep)} EP.", disable_mentions=1)
        return True

    cat = str(state.get("cat", ""))
    if cat not in {"money", "bananas"}:
        ep_shop_inputs.pop(int(user_id), None)
        return False

    spent = await spend_epoints(user_id, quantity, reason=f"ep_shop:{cat}")
    if not spent:
        await message.reply("Не удалось списать Epoints. Попробуйте ещё раз.", disable_mentions=1)
        return True

    bal = get_balance(user_id)
    if cat == "money":
        reward = quantity * EP_MONEY_RATE
        bal["wallet"] = int(bal.get("wallet", 0) or 0) + reward
        _persist_user_balance(user_id, bal)
        await log_economy(user_id=user_id, target_id=None, amount=reward, log=f"обменял(-а) {quantity} EP на {reward}₽")
        result_text = f"💱 Обмен выполнен: {format_number(quantity)} EP → {format_number(reward)}₽"
    else:
        reward = quantity * EP_BANANA_RATE
        bal["bananas"] = int(bal.get("bananas", 0) or 0) + reward
        _persist_user_balance(user_id, bal)
        await log_economy(user_id=user_id, target_id=None, amount=None, log=f"обменял(-а) {quantity} EP на {reward} коинов")
        result_text = f"🍌 Обмен выполнен: {format_number(quantity)} EP → {format_number(reward)} коинов"

    ep_shop_inputs.pop(int(user_id), None)
    remaining_ep = await get_total_epoints(user_id)
    kb = Keyboard(inline=True)
    kb.add(Callback("Назад в /епоинтс", {"command": "ep_back", "owner_id": user_id}), color=KeyboardButtonColor.SECONDARY)
    await message.reply(f"{result_text}\n💎 Баланс: {format_number(remaining_ep)} Epoints", keyboard=kb, disable_mentions=1)
    return True


async def _build_auction_page(chat_id: int, page: int = 1):
    await finalize_expired_auctions()
    async with aiosqlite.connect("database.db", timeout=30) as db:
        await _configure_async_db(db)
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            "SELECT id, item_name, current_bid, seller_id, highest_bidder_id, created_at, ends_at "
            "FROM auction_items ORDER BY current_bid DESC, id ASC"
        )
        lots = [dict(row) for row in await cur.fetchall()]

    per_page = 8
    total_pages = max(1, (len(lots) + per_page - 1) // per_page)
    page = min(max(1, page), total_pages)
    start = (page - 1) * per_page
    page_lots = lots[start:start + per_page]

    kb = Keyboard(inline=True)
    if total_pages > 1:
        if page > 1:
            kb.add(Callback("⬅️ Назад", {"command": "auction_page", "page": page - 1}), color=KeyboardButtonColor.SECONDARY)
        if page < total_pages:
            kb.add(Callback("➡️ Вперед", {"command": "auction_page", "page": page + 1}), color=KeyboardButtonColor.SECONDARY)

    lines = [
        f"🏛 Аукцион [{page}/{total_pages}]",
        f"📦 Активных лотов: {len(lots)}",
        "",
    ]
    for index, lot in enumerate(page_lots, start=start + 1):
        try:
            seller_name = await get_user_name(int(lot["seller_id"]), chat_id)
        except Exception:
            seller_name = str(lot["seller_id"])
        leader_text = "Нет ставок"
        if lot.get("highest_bidder_id"):
            try:
                leader_name = await get_user_name(int(lot["highest_bidder_id"]), chat_id)
            except Exception:
                leader_name = str(lot["highest_bidder_id"])
            leader_text = leader_name
        lines.append(
            f"┏ Лот #{lot['id']}\n"
            f"🎁 {lot['item_name']}\n"
            f"💰 Ставка: {format_number(int(lot['current_bid']))}₽\n"
            f"👤 Продавец: {seller_name}\n"
            f"🏁 Лидер: {leader_text}\n"
            f"⏳ Осталось: {_lot_time_left_text(lot)}\n"
            f"┗ Ставка: /купаук {lot['id']} [сумма]"
        )
        if index != start + len(page_lots) - 1:
            lines.append("")
    return lots, kb, "\n".join(lines)


