def _event_state_label(event_def: dict) -> str:
    state = _get_event_state(event_def)
    if state == "active":
        return "🟢 Активен"
    if state == "upcoming":
        return "🕒 Скоро начнётся"
    return "⚫ Завершён"


def _build_event_summary_lines(event_def: dict) -> list[str]:
    lines = [
        _event_state_label(event_def),
        f"📅 {_format_msk_event_dt(event_def['start'])} — {_format_msk_event_dt(event_def['end'])} МСК",
    ]
    state = _get_event_state(event_def)
    remaining_delta = _get_event_remaining_delta(event_def)
    if state == "active":
        lines.append(f"⏳ До конца: {_format_compact_duration(remaining_delta)}")
    elif state == "upcoming":
        lines.append(f"⏳ До начала: {_format_compact_duration(remaining_delta)}")
    description = str(event_def.get("description", "")).strip()
    if description:
        lines.append(description)
    return lines


async def build_events_menu(user_id: int):
    balance_data = _cached_user_balance(user_id)
    kb = Keyboard(inline=True)
    event_buttons: list[tuple[str, dict, str]] = []
    lines = [
        "🎉 Центр событий ADMIN MANAGER",
        "",
    ]
    visible_events = _get_visible_events()
    if not visible_events:
        lines.append("На данный момент нету активных ивентов")
        return kb, "\n".join(lines)

    for index, (event_id, event_def) in enumerate(visible_events, start=1):
        if index > 1:
            lines.append("")
        lines.append(f"{index}. {event_def['title']}")
        lines.extend(_build_event_summary_lines(event_def))
        event_buttons.append(
            (
                _fit_vk_button_label(f"Открыть: {event_def['title']}", 40),
                {"command": "event_open", "event_id": event_id, "owner_id": user_id},
                KeyboardButtonColor.PRIMARY,
            )
        )

    for idx, (label, payload, color) in enumerate(event_buttons, start=1):
        kb.add(
            Callback(label, payload),
            color=color,
        )
        if idx % 2 == 0 or idx == len(event_buttons):
            kb.row()

    kb.add(Callback("🔄 Обновить", {"command": "event_menu", "owner_id": user_id}), color=KeyboardButtonColor.SECONDARY)
    return kb, "\n".join(lines)


