async def getID(arg: str):
    arg = str(arg or "").strip()
    arg_split = arg.split("|")

    if arg_split[0] == arg:
        if arg.startswith("@") and not arg.lower().startswith("@id"):
            try:
                scr_split = await bot.api.utils.resolve_screen_name(arg[1:])
                x = json.loads(scr_split.model_dump_json())
                return int(x["object_id"])
            except:
                pass
        try:
            # --- Проверка на vk.com, vk.me, vk.ru ---
            if any(domain in arg for domain in ["vk.com/", "vk.me/", "vk.ru/"]):
                clean_arg = (
                    arg.replace("https://", "")
                    .replace("http://", "")
                    .replace("www.", "")
                )

                for domain in ["vk.com/", "vk.me/", "vk.ru/"]:
                    if domain in clean_arg:
                        clean_arg = clean_arg.split(domain)[1]
                        break
                clean_arg = re.split(r"[/?#]", clean_arg, maxsplit=1)[0]

                scr_split = await bot.api.utils.resolve_screen_name(clean_arg)
                x = json.loads(scr_split.model_dump_json())
                return int(x["object_id"])
        except:
            pass

        # --- Если передан vk.com/idXXX ---
        com_split = arg.split("vk.com/id")
        try:
            if com_split[1].isnumeric():
                return com_split[1]
            else:
                return False
        except:
            # --- Если просто vk.com/username ---
            for domain in ["vk.com/", "vk.me/", "vk.ru/"]:
                if domain in arg:
                    try:
                        screen_split = arg.split(domain)
                        scr_split = await bot.api.utils.resolve_screen_name(screen_split[1])
                        ut_split = str(scr_split).split(" ")
                        obj_split = ut_split[1].split("_id=")
                        if not obj_split[1].isnumeric():
                            return False
                        return obj_split[1]
                    except:
                        return False

    try:
        id_split = arg_split[0].split("id")
        return int(id_split[1])
    except:
        return False        

async def get_registration_date(user_id=int):
    vk_link = f"http://vk.com/foaf.php?id={user_id}"
    with urllib.request.urlopen(vk_link) as response:
        vk_xml = response.read().decode("windows-1251")

    parsed_xml = re.findall(r'created dc:date="(.*)"', vk_xml)
    for item in parsed_xml:
        sp_i = item.split('+')
        str = sp_i[0]  # строка с вашей датой

        PATTERN_IN1 = "%Y-%m-%dT%H:%M:%S"  # формат вашей даты
        PATTERN_OUT1 = "%B"  # формат даты, который вам нужен на выходе

        date1 = datetime.strptime(str, PATTERN_IN1)
        cp_date1 = datetime.strftime(date1, PATTERN_OUT1)

        locales = {"November": "ноября", "October": "октября", "September": "сентября", "August": "августа",
                   "July": "июля", "June": "июня", "May": "мая", "April": "апреля", "March": "марта",
                   "February": "февраля", "January": "января", "December": "декабря"}
        m = locales.get(cp_date1)

        PATTERN_IN = "%Y-%m-%dT%H:%M:%S"  # формат вашей даты
        PATTERN_OUT = f"%d-ого {m} 20%yг"  # формат даты, который вам нужен на выходе

        date = datetime.strptime(str, PATTERN_IN)
        cp_date = datetime.strftime(date, PATTERN_OUT)

    return cp_date

async def fetch_regvk_registration(user_id: int) -> dict:
    vk_url = f"https://vk.com/id{int(user_id)}"
    form_data = {
        "link": vk_url,
        "button": "Определить дату регистрации",
    }
    headers = {
        "User-Agent": "Mozilla/5.0",
    }
    timeout = aiohttp.ClientTimeout(total=12)
    async with aiohttp.ClientSession(timeout=timeout, headers=headers) as session:
        async with session.post("https://regvk.com/", data=form_data) as response:
            response.raise_for_status()
            page_text = await response.text()

    page_text = html.unescape(re.sub(r"\s+", " ", page_text))
    date_match = re.search(r"Дата регистрации:\s*([^<]+?)\s*<br", page_text, flags=re.IGNORECASE)
    elapsed_match = re.search(r"Прошло времени:\s*([^<]+?)\s*<", page_text, flags=re.IGNORECASE)
    url_match = re.search(r'Адрес страницы:\s*<a[^>]+href="([^"]+)"', page_text, flags=re.IGNORECASE)

    if not date_match:
        raise ValueError("regvk did not return registration date")

    return {
        "date": date_match.group(1).strip(),
        "elapsed": (elapsed_match.group(1).strip() if elapsed_match else "не удалось определить"),
        "url": (url_match.group(1).strip() if url_match else vk_url),
    }

async def get_string(text=[], arg=int):
    data_string = []
    for i in range(len(text)):
        if i < arg: pass
        else: data_string.append(text[i])
    return_string = " ".join(data_string)
    if return_string == "": return False
    else: return return_string


def get_raw_text_tail(text: str, arg: int = 1):
    """Return text after ``arg`` whitespace-separated tokens, preserving line breaks."""
    source = text or ""
    matches = list(re.finditer(r"\S+", source))
    if len(matches) <= arg:
        return False
    value = source[matches[arg].start():].strip()
    return value or False

def _open_main_sqlite_connection():
    conn = sqlite3.connect(
        'database.db',
        timeout=30,
        check_same_thread=False,
        isolation_level=None,
    )
    cur = conn.cursor()
    try:
        cur.execute("PRAGMA journal_mode=WAL")
    except sqlite3.OperationalError as error:
        print(f"[DB] WAL mode failed, fallback to DELETE journal: {error}")
        try:
            cur.execute("PRAGMA journal_mode=DELETE")
        except sqlite3.OperationalError as fallback_error:
            print(f"[DB] DELETE journal fallback failed: {fallback_error}")
    try:
        cur.execute("PRAGMA synchronous=NORMAL")
        cur.execute("PRAGMA busy_timeout=30000")
    except sqlite3.OperationalError as error:
        print(f"[DB] PRAGMA configure error: {error}")
    return conn, cur


database, sql = _open_main_sqlite_connection()
db_lock = asyncio.Lock()

# Тяжёлые операции не должны блокировать обработку остальных сообщений.
# Карты строятся по одной, одинаковые запросы объединяются и ненадолго кэшируются.
_COUNTRY_MAP_RENDER_SEMAPHORE = asyncio.Semaphore(1)
_COUNTRY_MAP_CACHE_LOCK = asyncio.Lock()
_COUNTRY_MAP_CACHE = {}
_COUNTRY_MAP_INFLIGHT = {}
_COUNTRY_MAP_CACHE_DIR = os.path.join(tempfile.gettempdir(), "country_map_cache")
_COUNTRY_STATE_OPERATION_LOCKS = {}
_COUNTRY_BACKGROUND_TASKS = set()


def _country_state_operation_lock(country_id: int) -> asyncio.Lock:
    key = int(country_id)
    lock = _COUNTRY_STATE_OPERATION_LOCKS.get(key)
    if lock is None:
        lock = asyncio.Lock()
        _COUNTRY_STATE_OPERATION_LOCKS[key] = lock
    return lock


def _country_spawn_background(coro, label: str = "background"):
    """Запустить необязательную сетевую работу, не задерживая ответ команды."""
    task = asyncio.create_task(coro)
    _COUNTRY_BACKGROUND_TASKS.add(task)

    def _done(done_task):
        _COUNTRY_BACKGROUND_TASKS.discard(done_task)
        try:
            done_task.result()
        except asyncio.CancelledError:
            pass
        except Exception as exc:
            print(f"[BACKGROUND {label}] {exc}")

    task.add_done_callback(_done)
    return task


async def _country_generate_cached_map(cache_key: str, ttl_seconds: int, renderer):
    os.makedirs(_COUNTRY_MAP_CACHE_DIR, exist_ok=True)
    async with _COUNTRY_MAP_RENDER_SEMAPHORE:
        # Даём циклу событий обработать новые сообщения перед тяжёлым рендером.
        await asyncio.sleep(0)
        generated_path = await renderer()
        cache_name = f"map_{abs(hash(cache_key))}.png"
        cache_path = os.path.join(_COUNTRY_MAP_CACHE_DIR, cache_name)
        try:
            await asyncio.to_thread(shutil.copy2, generated_path, cache_path)
        finally:
            try:
                os.remove(generated_path)
            except OSError:
                pass
        async with _COUNTRY_MAP_CACHE_LOCK:
            _COUNTRY_MAP_CACHE[cache_key] = (
                time.monotonic() + max(1, int(ttl_seconds)),
                cache_path,
            )
        return cache_path


async def _country_get_cached_map(cache_key: str, ttl_seconds: int, renderer) -> str:
    """Вернуть отдельную временную копию карты для загрузки во VK."""
    now = time.monotonic()
    expired_paths = []
    async with _COUNTRY_MAP_CACHE_LOCK:
        for old_key, old_value in list(_COUNTRY_MAP_CACHE.items()):
            if old_value[0] <= now:
                _COUNTRY_MAP_CACHE.pop(old_key, None)
                expired_paths.append(old_value[1])
        # Не держим на диске сотни карт стран, если ими редко пользуются.
        if len(_COUNTRY_MAP_CACHE) > 24:
            oldest = sorted(_COUNTRY_MAP_CACHE.items(), key=lambda item: item[1][0])
            for old_key, old_value in oldest[:-24]:
                _COUNTRY_MAP_CACHE.pop(old_key, None)
                expired_paths.append(old_value[1])
        cached = _COUNTRY_MAP_CACHE.get(cache_key)
        if cached and cached[0] > now and os.path.isfile(cached[1]):
            task = None
            cache_path = cached[1]
        else:
            task = _COUNTRY_MAP_INFLIGHT.get(cache_key)
            if task is None or task.done():
                task = asyncio.create_task(
                    _country_generate_cached_map(cache_key, ttl_seconds, renderer)
                )
                _COUNTRY_MAP_INFLIGHT[cache_key] = task
            cache_path = None

    for expired_path in expired_paths:
        try:
            await asyncio.to_thread(os.remove, expired_path)
        except OSError:
            pass

    if task is not None:
        try:
            cache_path = await asyncio.shield(task)
        finally:
            if task.done():
                async with _COUNTRY_MAP_CACHE_LOCK:
                    if _COUNTRY_MAP_INFLIGHT.get(cache_key) is task:
                        _COUNTRY_MAP_INFLIGHT.pop(cache_key, None)

    fd, temp_copy = tempfile.mkstemp(prefix="country_map_upload_", suffix=".png")
    os.close(fd)
    await asyncio.to_thread(shutil.copy2, cache_path, temp_copy)
    return temp_copy

async def db_execute(query, params=None, fetch='none'):
    """Безопасное выполнение SQL-запроса с блокировкой."""
    async with db_lock:
        for attempt in range(2):
            try:
                if params:
                    sql.execute(query, params)
                else:
                    sql.execute(query)
                if fetch == 'one':
                    return sql.fetchone()
                elif fetch == 'all':
                    return sql.fetchall()
                return None
            except (sqlite3.OperationalError, sqlite3.ProgrammingError) as e:
                print(f"[DB ERROR] {e} | Query: {query}")
                try:
                    database.rollback()
                except:
                    pass
                _reset_sql_cursor()
                if attempt == 0:
                    continue
                return None
            except Exception as e:
                print(f"[DB ERROR] {e} | Query: {query}")
                try:
                    database.rollback()
                except:
                    pass
                _reset_sql_cursor()
                return None


