def _country_quantity_limit(user_id: int, normal_limit: int) -> int:
    return COUNTRY_DEVELOPER_MAX_QUANTITY if int(user_id) in COUNTRY_DEVELOPER_BULK_IDS else int(normal_limit)


def _country_progressive_build_cost(base_cost: int, current_count: int, quantity: int) -> int:
    base_cost = max(0, int(base_cost))
    current_count = max(0, int(current_count))
    quantity = max(0, int(quantity))
    if quantity <= 0:
        return 0

    def floor_sum(n: int) -> int:
        if n < 0:
            return 0
        blocks, remainder = divmod(n + 1, 3)
        return 3 * blocks * (blocks - 1) // 2 + blocks * remainder

    multipliers = quantity + floor_sum(current_count + quantity - 1) - floor_sum(current_count - 1)
    return base_cost * multipliers


