_COUNTRY_BAD_WORDS = {"хуй", "пизд", "еб", "бляд", "сука", "долбо", "наци", "террор"}

def _normalize_country_name(value):
    return " ".join(str(value or "").strip().lower().replace("ё", "е").split())

def _country_by_name(value):
    key = _normalize_country_name(value)
    aliases = {
        "российская федерация": "россия", "рф": "россия",
        "usa": "сша", "америка": "сша", "соединенные штаты": "сша",
        "uk": "великобритания", "англия": "великобритания",
        "рк": "казахстан", "қазақстан": "казахстан", "kazakhstan": "казахстан", "kz": "казахстан",
        "белоруссия": "беларусь", "рб": "беларусь",
        "україна": "украина", "ua": "украина",
        "туркия": "турция", "turkey": "турция",
        "южнаякорея": "южная корея", "корея": "южная корея", "республика корея": "южная корея",
        "south korea": "южная корея", "кнр": "китай",
    }
    key = aliases.get(key, key)
    item = COUNTRY_CATALOG.get(key)
    if not item:
        return None
    return sql.execute("SELECT id, name, emoji, treasury, ip_tax, president_id, president_status, level, economy_score, military_score, happiness, infrastructure FROM countries WHERE name = ?", (item[0],)).fetchone()

def _citizen_row(user_id):
    return sql.execute("""SELECT cc.user_id, cc.country_id, cc.joined_at, cc.passport_number, cc.company_type, cc.company_name,
        cc.army_rank, cc.government_post, c.name, c.emoji, c.ip_tax, c.president_id
        FROM country_citizens cc JOIN countries c ON c.id = cc.country_id WHERE cc.user_id = ?""", (int(user_id),)).fetchone()

COUNTRY_CHANGE_COOLDOWN = timedelta(days=2)

def _country_change_remaining(user_id: int) -> Optional[timedelta]:
    row = sql.execute("SELECT last_country_change FROM country_citizens WHERE user_id = ?", (int(user_id),)).fetchone()
    if not row or not row[0]:
        return None
    try:
        changed_at = datetime.fromisoformat(str(row[0]).replace("Z", "+00:00"))
        if changed_at.tzinfo is not None:
            changed_at = changed_at.replace(tzinfo=None)
    except (TypeError, ValueError):
        return None
    remaining = COUNTRY_CHANGE_COOLDOWN - (datetime.now() - changed_at)
    return remaining if remaining.total_seconds() > 0 else None

def _format_country_change_remaining(delta: timedelta) -> str:
    seconds = max(0, int(delta.total_seconds()))
    days, seconds = divmod(seconds, 86400)
    hours, seconds = divmod(seconds, 3600)
    minutes, _ = divmod(seconds, 60)
    parts = []
    if days:
        parts.append(f"{days}д")
    if hours or days:
        parts.append(f"{hours}ч")
    parts.append(f"{minutes}м")
    return " ".join(parts)

def _make_passport(country_name, user_id):
    prefix = ''.join(ch for ch in country_name.upper() if ch.isalpha())[:2] or 'XX'
    return f"{prefix}-{int(user_id) % 100000000:08d}"

def _valid_company_name(name):
    clean = " ".join(str(name or "").strip().split())
    low = clean.lower().replace("ё", "е")
    if len(clean) < 2 or len(clean) > 32:
        return False, "Название должно содержать от 2 до 32 символов."
    if any(ch.isdigit() for ch in clean):
        return False, "Название не может содержать цифры."
    if not all(ch.isalpha() or ch in " -" for ch in clean):
        return False, "Разрешены только буквы, пробелы и дефис."
    if any(word in low for word in _COUNTRY_BAD_WORDS):
        return False, "Название содержит запрещённую лексику."
    exists = sql.execute("SELECT 1 FROM country_citizens WHERE lower(company_name) = lower(?)", (clean,)).fetchone()
    if exists:
        return False, "Компания с таким названием уже зарегистрирована."
    return True, clean

def _country_is_president(user_id, country_id):
    row = sql.execute("SELECT president_id FROM countries WHERE id = ?", (int(country_id),)).fetchone()
    return bool(row and row[0] and int(row[0]) == int(user_id))

def _country_is_defense_head(user_id, country_id):
    row = sql.execute("SELECT government_post FROM country_citizens WHERE user_id = ? AND country_id = ?", (int(user_id), int(country_id))).fetchone()
    return bool(row and row[0] in ("Министр вооружённых сил", "Маршал армии"))

def _country_tax_for_user(user_id, business_count):
    citizen = _citizen_row(user_id)
    if not citizen or business_count <= 0:
        return None
    country_id, ip_tax = int(citizen[1]), max(1, int(citizen[10]))
    if business_count >= 1000:
        company_type = "ООО" if citizen[4] == "ООО" and citizen[5] else "ТРЕБУЕТСЯ_ООО"
        return country_id, ip_tax + 6, company_type
    return country_id, ip_tax, "ИП"

def _country_company_status(citizen, business_count, display_name="Гражданин"):
    if business_count <= 0:
        return "Нет организации", "нет бизнеса"
    if business_count < 1000:
        return f"ИП {display_name}", "ИП"
    if citizen and citizen[4] == "ООО" and citizen[5]:
        return f"ООО «{citizen[5]}»", "ООО"
    return "ООО не зарегистрировано", "требуется регистрация"

def _country_post_level(post):
    order = {
        None: 0, "Гражданин": 0, "Депутат": 1, "Начальник отдела": 2,
        "Советник правительства": 3, "Заместитель министра": 4,
        "Министр финансов": 5, "Министр экономики": 5, "Министр вооружённых сил": 5,
        "Министр внутренних дел": 5, "Министр иностранных дел": 5,
        "Министр строительства": 5, "Министр науки": 5, "Министр промышленности": 5,
        "Министр здравоохранения": 5, "Министр образования": 5,
        "Премьер-министр": 6, "Президент": 7,
    }
    return order.get(post, 0)

async def _country_notify_user(user_id, text):
    try:
        await _country_dm(int(user_id), text)
    except Exception:
        pass

async def _country_user_mention(user_id: int, chat_id: int = 0) -> str:
    uid = int(user_id)
    try:
        users = await bot.api.users.get(user_ids=uid)
        if users:
            full_name = f"{users[0].first_name} {users[0].last_name}".strip()
            return f"[id{uid}|{full_name}]"
    except Exception:
        pass
    try:
        full_name = str(await get_user_name(uid, chat_id) or "").strip()
        if full_name and not full_name.lower().startswith(("@id", "id")):
            return f"[id{uid}|{full_name}]"
    except Exception:
        pass
    return f"[id{uid}|Пользователь]"


async def _build_country_citizens_page(
    country_id: int,
    page: int = 1,
    chat_id: int = 0,
    owner_id: int = 0,
    per_page: int = 12,
) -> Tuple[str, Keyboard, int, int]:
    country = sql.execute(
        "SELECT name, emoji, president_id FROM countries WHERE id = ?",
        (int(country_id),),
    ).fetchone()
    if not country:
        kb = Keyboard(inline=True)
        return "Государство не найдено.", kb, 1, 1

    rows = sql.execute(
        """SELECT user_id, joined_at, army_rank, government_post
           FROM country_citizens
           WHERE country_id = ?""",
        (int(country_id),),
    ).fetchall()

    president_id = int(country[2] or 0)
    government = []
    army = []
    civilians = []

    def government_priority(post: str) -> int:
        role = str(post or "")
        if role == "Президент":
            return 100
        if role == "Вице-президент":
            return 90
        if role == "Премьер-министр":
            return 80
        if role.startswith("Министр"):
            return 70
        if role == "Депутат":
            return 40
        if role == "Советник президента":
            return 30
        return 50

    for raw_user_id, joined_at, raw_rank, raw_post in rows:
        uid = int(raw_user_id)
        post = str(raw_post or "").strip()
        try:
            rank = int(raw_rank if raw_rank is not None else -1)
        except (TypeError, ValueError):
            rank = -1

        if uid == president_id:
            government.append((uid, "Президент", joined_at))
        elif post:
            government.append((uid, post, joined_at))
        elif 0 <= rank < len(ARMY_RANKS):
            army.append((uid, ARMY_RANKS[rank], rank, joined_at))
        else:
            civilians.append((uid, "Гражданин", joined_at))

    government.sort(key=lambda item: (-government_priority(item[1]), item[1], item[0]))
    army.sort(key=lambda item: (-int(item[2]), item[0]))
    civilians.sort(key=lambda item: (str(item[2] or ""), item[0]))

    entries = []
    entries.extend(("Правительство", uid, role) for uid, role, _joined in government)
    entries.extend(("Армия", uid, role) for uid, role, _rank, _joined in army)
    entries.extend(("Граждане", uid, role) for uid, role, _joined in civilians)

    per_page = max(1, int(per_page or 12))
    total_pages = max(1, (len(entries) + per_page - 1) // per_page)
    page = min(max(1, int(page or 1)), total_pages)
    start = (page - 1) * per_page
    page_entries = entries[start:start + per_page]

    lines = [
        f"{country[1]} {country[0]}",
        f"👥 Состав государства [{page}/{total_pages}]",
        (
            f"Всего: {len(entries)} | Правительство: {len(government)} | "
            f"Армия: {len(army)} | Граждане: {len(civilians)}"
        ),
    ]

    if not page_entries:
        lines.extend(["", "Граждан в государстве пока нет."])
    else:
        current_section = None
        for section, uid, role in page_entries:
            if section != current_section:
                lines.extend(["", f"{section}:"])
                current_section = section
            mention = await _country_user_mention(uid, chat_id)
            lines.append(f"• {mention} — {role}")

    if total_pages > 1:
        lines.extend(["", f"Страница {page} из {total_pages}. Также можно: /граждане [страница]"])

    kb = Keyboard(inline=True)
    if page > 1:
        kb.add(
            Callback(
                "⬅️ Назад",
                {
                    "command": "country_citizens_page",
                    "country_id": int(country_id),
                    "page": page - 1,
                    "owner_id": int(owner_id or 0),
                },
            ),
            color=KeyboardButtonColor.SECONDARY,
        )
    if page < total_pages:
        kb.add(
            Callback(
                "➡️ Вперёд",
                {
                    "command": "country_citizens_page",
                    "country_id": int(country_id),
                    "page": page + 1,
                    "owner_id": int(owner_id or 0),
                },
            ),
            color=KeyboardButtonColor.SECONDARY,
        )

    return "\n".join(lines), kb, page, total_pages


async def _country_resolve_target(message: Message, raw_text: str) -> Tuple[Optional[int], str]:
    """Возвращает (user_id, остаток аргументов) для госкоманд.

    Поддерживает ответ, пересланное сообщение, [id|Имя], @screen_name,
    ссылки vk.com, id123 и обычный числовой ID.
    """
    tail = str(get_raw_text_tail(raw_text, 1) or "").strip()

    reply = getattr(message, "reply_message", None)
    if reply is not None:
        try:
            reply_id = int(getattr(reply, "from_id", 0) or 0)
            if reply_id > 0:
                return reply_id, tail
        except Exception:
            pass

    forwarded = getattr(message, "fwd_messages", None) or []
    if forwarded:
        try:
            forward_id = int(getattr(forwarded[0], "from_id", 0) or 0)
            if forward_id > 0:
                return forward_id, tail
        except Exception:
            pass

    patterns = (
        r'^\s*\[id(?P<id>\d+)\|[^\]]*\]\s*(?P<rest>.*)$',
        r'^\s*\[[^\]]+\]\((?:https?://)?(?:m\.)?vk\.(?:com|ru)/(?P<screen>[A-Za-z0-9_.]+)\)\s*(?P<rest>.*)$',
        r'^\s*(?:https?://)?(?:m\.)?vk\.(?:com|ru)/(?P<screen>[A-Za-z0-9_.]+)\s*(?P<rest>.*)$',
        r'^\s*@(?P<screen>[A-Za-z0-9_.]+)\s*(?P<rest>.*)$',
        r'^\s*(?:id)?(?P<id>\d{4,})\s*(?P<rest>.*)$',
    )
    for pattern in patterns:
        match = re.match(pattern, tail, flags=re.IGNORECASE)
        if not match:
            continue
        rest = str(match.groupdict().get("rest") or "").strip()
        raw_id = match.groupdict().get("id")
        if raw_id:
            return int(raw_id), rest
        screen = str(match.groupdict().get("screen") or "").strip().rstrip("/")
        if screen.lower().startswith("id") and screen[2:].isdigit():
            return int(screen[2:]), rest
        try:
            users = await bot.api.users.get(user_ids=screen)
            if users:
                return int(users[0].id), rest
        except Exception:
            return None, rest
    return None, tail


def _normalize_country_token(value: str) -> str:
    return re.sub(r"[\s_\-]+", "", str(value or "").strip().lower().replace("ё", "е"))


def _resolve_government_post(value: str) -> Optional[str]:
    normalized = _normalize_country_token(value)
    for alias, post in GOVERNMENT_POSTS.items():
        if _normalize_country_token(alias) == normalized:
            return post
    for post in set(GOVERNMENT_POSTS.values()):
        if _normalize_country_token(post) == normalized:
            return post
    return None


def _country_parse_catalog_item(raw_value: str, catalog: Dict[str, Dict]) -> Tuple[Optional[str], str]:
    value = " ".join(str(raw_value or "").strip().split())
    normalized = value.lower().replace("ё", "е")
    candidates = []
    for key, meta in catalog.items():
        for alias in meta.get("aliases", ()):
            alias_text = " ".join(str(alias).strip().lower().replace("ё", "е").split())
            candidates.append((len(alias_text), alias_text, key))
    for _length, alias_text, key in sorted(candidates, reverse=True):
        if normalized == alias_text:
            return key, ""
        if normalized.startswith(alias_text + " "):
            return key, value[len(alias_text):].strip()
    return None, value


def _country_find_open_city(country_id: int, requested_name: str = "") -> Optional[str]:
    rows = sql.execute(
        "SELECT city_name FROM country_cities WHERE country_id = ? AND is_open = 1 ORDER BY id",
        (int(country_id),),
    ).fetchall()
    if not rows:
        return None
    if not requested_name:
        return str(rows[0][0])
    wanted = _normalize_country_name(requested_name)
    for (city_name,) in rows:
        if _normalize_country_name(city_name) == wanted:
            return str(city_name)
    return None


def _country_building_count(country_id: int, building_type: str) -> int:
    row = sql.execute(
        "SELECT COALESCE(SUM(count), 0) FROM country_buildings WHERE country_id = ? AND building_type = ?",
        (int(country_id), str(building_type)),
    ).fetchone()
    return int(row[0] or 0) if row else 0


def _country_mobilization_state(country_id: int) -> Tuple[bool, Optional[datetime]]:
    row = sql.execute(
        "SELECT mobilization_until FROM country_military_assets WHERE country_id = ?",
        (int(country_id),),
    ).fetchone()
    if not row or not row[0]:
        return False, None
    try:
        until = datetime.fromisoformat(str(row[0]).replace(" ", "T"))
    except Exception:
        return False, None
    return until > datetime.now(), until



def _country_is_active(country_id: int) -> bool:
    row = sql.execute("SELECT status FROM countries WHERE id = ?", (int(country_id),)).fetchone()
    return bool(row and str(row[0] or "active") == "active")


def _country_catalog_cities(country_id: int) -> List[str]:
    row = sql.execute("SELECT name FROM countries WHERE id = ?", (int(country_id),)).fetchone()
    if not row:
        return []
    country_name = str(row[0])
    for _key, (name, _emoji, cities) in COUNTRY_CATALOG.items():
        if name == country_name:
            return list(cities)
    return []


def _country_catalog_city_total(country_id: int) -> int:
    return len(_country_catalog_cities(country_id))


def _country_open_city_total(country_id: int) -> int:
    catalog_cities = _country_catalog_cities(country_id)
    if not catalog_cities:
        return 0
    placeholders = ",".join("?" for _ in catalog_cities)
    row = sql.execute(
        f"SELECT COUNT(*) FROM country_cities WHERE country_id = ? AND is_open = 1 AND city_name IN ({placeholders})",
        (int(country_id), *catalog_cities),
    ).fetchone()
    return int(row[0] or 0) if row else 0


def _country_next_locked_city(country_id: int) -> Optional[Tuple[int, str]]:
    for city_name in _country_catalog_cities(country_id):
        row = sql.execute(
            "SELECT id, is_open FROM country_cities WHERE country_id = ? AND city_name = ?",
            (int(country_id), city_name),
        ).fetchone()
        if row and not int(row[1] or 0):
            return int(row[0]), city_name
    return None


def _country_is_max_developed(country_id: int) -> bool:
    total = _country_catalog_city_total(country_id)
    if total != COUNTRY_MAX_CITIES:
        return False
    level_row = sql.execute("SELECT level FROM countries WHERE id = ?", (int(country_id),)).fetchone()
    level = int(level_row[0] or 0) if level_row else 0
    return (
        _country_open_city_total(country_id) >= COUNTRY_MAX_CITIES
        and level >= COUNTRY_MAX_CITIES
        and _country_is_active(country_id)
    )


def _country_award_nuclear_if_ready(country_id: int) -> bool:
    if not _country_is_max_developed(country_id):
        return False
    row = sql.execute(
        "SELECT nuclear_unlocked FROM countries WHERE id = ?",
        (int(country_id),),
    ).fetchone()
    if not row or int(row[0] or 0) > 0:
        return False
    sql.execute(
        "UPDATE countries SET nuclear_unlocked = 1 WHERE id = ?",
        (int(country_id),),
    )
    sql.execute(
        "INSERT OR IGNORE INTO country_military_assets(country_id) VALUES(?)",
        (int(country_id),),
    )
    sql.execute(
        "UPDATE country_military_assets SET nuclear_missiles = nuclear_missiles + 1, updated_at = CURRENT_TIMESTAMP WHERE country_id = ?",
        (int(country_id),),
    )
    database.commit()
    return True


def _country_development_ratio(country_id: int) -> float:
    row = sql.execute(
        "SELECT level, economy_score, military_score, happiness, infrastructure FROM countries WHERE id = ?",
        (int(country_id),),
    ).fetchone()
    if not row:
        return 0.0
    total_cities = max(1, _country_catalog_city_total(country_id))
    city_ratio = min(1.0, _country_open_city_total(country_id) / total_cities)
    economy_ratio = min(1.0, max(0, int(row[1] or 0)) / 500.0)
    military_ratio = min(1.0, max(0, int(row[2] or 0)) / 500.0)
    happiness_ratio = min(1.0, max(0, int(row[3] or 0)) / 100.0)
    infrastructure_ratio = min(1.0, max(0, int(row[4] or 0)) / max(10.0, total_cities * 4.0))
    return max(0.0, min(1.0, (
        city_ratio * 0.35 + economy_ratio * 0.20 + military_ratio * 0.20
        + happiness_ratio * 0.10 + infrastructure_ratio * 0.15
    )))


def _country_city_air_defense(country_id: int, city_name: str) -> int:
    row = sql.execute(
        "SELECT units FROM country_city_air_defense WHERE country_id = ? AND city_name = ?",
        (int(country_id), str(city_name)),
    ).fetchone()
    return max(0, int(row[0] or 0)) if row else 0


def _country_total_installed_air_defense(country_id: int) -> int:
    row = sql.execute(
        "SELECT COALESCE(SUM(units), 0) FROM country_city_air_defense WHERE country_id = ?",
        (int(country_id),),
    ).fetchone()
    return max(0, int(row[0] or 0)) if row else 0


def _country_interception_percent(
    country_id: int,
    city_name: str,
    strike_type: str,
    attacker_country_id: int | None = None,
    quantity: int = 1,
) -> float:
    """Рассчитывает перехват по реальному соотношению вооружений сторон."""
    strike_type = str(strike_type or "missile").lower()
    quantity = max(1, int(quantity or 1))

    defender_country = sql.execute(
        "SELECT military_score, infrastructure, happiness FROM countries WHERE id = ?",
        (int(country_id),),
    ).fetchone() or (0, 0, 0)
    defender_assets = sql.execute(
        "SELECT air_defense, aircraft, defense_points FROM country_military_assets WHERE country_id = ?",
        (int(country_id),),
    ).fetchone() or (0, 0, 0)

    installed_pvo = (
        _country_city_air_defense(int(country_id), str(city_name))
        if city_name
        else _country_total_installed_air_defense(int(country_id))
    )
    reserve_pvo = max(0, int(defender_assets[0] or 0)) if (not city_name or strike_type == "nuclear") else 0
    defender_aircraft = max(0, int(defender_assets[1] or 0))
    defense_points = max(0, int(defender_assets[2] or 0))
    defender_military = max(0, int(defender_country[0] or 0))
    defender_infrastructure = max(0, int(defender_country[1] or 0))
    defender_happiness = max(0, int(defender_country[2] or 0))

    if strike_type == "drone":
        defense_strength = (
            (installed_pvo + reserve_pvo) * 210
            + defender_aircraft * 75
            + defense_points * 24
            + defender_military * 145
            + defender_infrastructure * 95
            + defender_happiness * 8
        )
        projectile_strength = 75
    elif strike_type == "nuclear":
        defense_strength = (
            (installed_pvo + reserve_pvo) * 420
            + defender_aircraft * 110
            + defense_points * 35
            + defender_military * 230
            + defender_infrastructure * 180
            + defender_happiness * 10
        )
        projectile_strength = 18_000
    else:
        defense_strength = (
            (installed_pvo + reserve_pvo) * 300
            + defender_aircraft * 95
            + defense_points * 28
            + defender_military * 170
            + defender_infrastructure * 115
            + defender_happiness * 8
        )
        projectile_strength = 310

    attacker_support = 0
    if attacker_country_id is not None:
        attacker_country = sql.execute(
            "SELECT military_score, infrastructure, happiness FROM countries WHERE id = ?",
            (int(attacker_country_id),),
        ).fetchone() or (0, 0, 0)
        attacker_assets = sql.execute(
            "SELECT aircraft, drones, missiles, attack_points, ammunition, equipment, nuclear_missiles "
            "FROM country_military_assets WHERE country_id = ?",
            (int(attacker_country_id),),
        ).fetchone() or (0,) * 7
        aircraft = max(0, int(attacker_assets[0] or 0))
        drones = max(0, int(attacker_assets[1] or 0))
        missiles = max(0, int(attacker_assets[2] or 0))
        attack_points = max(0, int(attacker_assets[3] or 0))
        ammunition = max(0, int(attacker_assets[4] or 0))
        equipment = max(0, int(attacker_assets[5] or 0))
        nuclear = max(0, int(attacker_assets[6] or 0))
        military = max(0, int(attacker_country[0] or 0))
        infrastructure = max(0, int(attacker_country[1] or 0))
        happiness = max(0, int(attacker_country[2] or 0))

        if strike_type == "drone":
            attacker_support = (
                aircraft * 55 + drones * 16 + attack_points * 22
                + military * 135 + ammunition // 8 + equipment // 12
            )
        elif strike_type == "nuclear":
            attacker_support = (
                aircraft * 85 + missiles * 32 + nuclear * 1_500
                + attack_points * 34 + military * 220
                + infrastructure * 70 + happiness * 4
            )
        else:
            attacker_support = (
                aircraft * 70 + missiles * 22 + drones * 8
                + attack_points * 28 + military * 165
                + ammunition // 6 + equipment // 10
            )

    attack_strength = max(1, projectile_strength * quantity + attacker_support)
    defense_strength = max(0, int(defense_strength))
    if defense_strength <= 0:
        return 0.0
    return (defense_strength / (defense_strength + attack_strength)) * 100.0


def _country_roll_interceptions(quantity: int, chance_percent: float) -> int:
    """Рассчитывает перехваты без медленного цикла для залпов до 100 000."""
    quantity = max(0, int(quantity or 0))
    probability = max(0.0, min(1.0, float(chance_percent) / 100.0))
    if quantity <= 0 or probability <= 0.0:
        return 0
    if probability >= 1.0:
        return quantity
    if quantity <= 5_000:
        return sum(1 for _ in range(quantity) if random.random() < probability)
    expected = quantity * probability
    deviation = math.sqrt(quantity * probability * (1.0 - probability))
    return max(0, min(quantity, int(round(random.gauss(expected, deviation)))))



def _country_random_total(count: int, low: int, high: int) -> int:
    """Быстро рассчитывает суммарный случайный урон даже для залпов до 100 000."""
    count = max(0, int(count or 0))
    low, high = int(low), int(high)
    if count <= 0:
        return 0
    if low > high:
        low, high = high, low
    if count <= 2_000:
        return sum(random.randint(low, high) for _ in range(count))
    mean = count * (low + high) / 2.0
    variance = count * (((high - low + 1) ** 2 - 1) / 12.0)
    value = int(round(random.gauss(mean, math.sqrt(max(0.0, variance)))))
    return max(count * low, min(count * high, value))


def _country_reduce_installed_pvo(country_id: int, loss: int, city_name: str = "") -> int:
    """Уменьшает установленное ПВО и возвращает реально потерянное количество."""
    remaining_loss = max(0, int(loss or 0))
    destroyed = 0
    if remaining_loss <= 0:
        return 0

    if city_name:
        rows = sql.execute(
            "SELECT city_name, units FROM country_city_air_defense "
            "WHERE country_id = ? AND city_name = ? AND units > 0",
            (int(country_id), str(city_name)),
        ).fetchall()
    else:
        rows = sql.execute(
            "SELECT city_name, units FROM country_city_air_defense "
            "WHERE country_id = ? AND units > 0 ORDER BY units DESC, city_name",
            (int(country_id),),
        ).fetchall()

    for current_city, units in rows:
        if remaining_loss <= 0:
            break
        units = max(0, int(units or 0))
        current_loss = min(units, remaining_loss)
        left = units - current_loss
        remaining_loss -= current_loss
        destroyed += current_loss
        if left <= 0:
            sql.execute(
                "DELETE FROM country_city_air_defense WHERE country_id = ? AND city_name = ?",
                (int(country_id), str(current_city)),
            )
        else:
            sql.execute(
                "UPDATE country_city_air_defense SET units = ?, updated_at = CURRENT_TIMESTAMP "
                "WHERE country_id = ? AND city_name = ?",
                (int(left), int(country_id), str(current_city)),
            )
    return destroyed


def _country_exhaust_air_defense(
    country_id: int,
    city_name: str,
    strike_type: str,
    incoming: int,
    intercepted: int,
) -> dict:
    """Истощает ПВО пропорционально нагрузке и насыщению конкретного залпа.

    Отдельного фиксированного процента нет: потери зависят от количества целей,
    количества перехватов и реального числа комплексов, участвовавших в обороне.
    """
    incoming = max(0, int(incoming or 0))
    intercepted = max(0, min(incoming, int(intercepted or 0)))
    strike_type = str(strike_type or "missile").lower()

    installed = (
        _country_city_air_defense(int(country_id), str(city_name))
        if city_name
        else _country_total_installed_air_defense(int(country_id))
    )
    reserve_row = sql.execute(
        "SELECT air_defense FROM country_military_assets WHERE country_id = ?",
        (int(country_id),),
    ).fetchone()
    reserve = max(0, int(reserve_row[0] or 0)) if reserve_row else 0
    # При ударе по конкретному городу работают установленные там комплексы.
    # При стратегическом/ядерном ударе задействуется вся сеть и резерв.
    engaged_reserve = reserve if not city_name else 0
    engaged = installed + engaged_reserve
    if incoming <= 0 or engaged <= 0:
        return {'installed': 0, 'reserve': 0, 'total': 0, 'remaining': engaged}

    if strike_type == 'drone':
        target_load = 0.45
        intercept_load = 0.85
        capacity_per_unit = 28.0
        destructive_factor = 0.42
    elif strike_type == 'nuclear':
        target_load = 5.0
        intercept_load = 8.0
        capacity_per_unit = 5.0
        destructive_factor = 1.35
    else:
        target_load = 1.0
        intercept_load = 1.65
        capacity_per_unit = 16.0
        destructive_factor = 0.78

    operational_load = incoming * target_load + intercepted * intercept_load
    saturation = operational_load / max(1.0, operational_load + engaged * capacity_per_unit)
    expected_loss = engaged * saturation * destructive_factor
    base_loss = int(expected_loss)
    if random.random() < expected_loss - base_loss:
        base_loss += 1
    pvo_loss = max(0, min(engaged, base_loss))
    if pvo_loss <= 0 and intercepted > 0 and operational_load >= capacity_per_unit:
        pvo_loss = 1

    installed_loss = _country_reduce_installed_pvo(
        int(country_id), min(installed, pvo_loss), str(city_name or "")
    )
    reserve_loss = max(0, pvo_loss - installed_loss)
    reserve_loss = min(reserve, reserve_loss)
    if reserve_loss > 0:
        sql.execute(
            "UPDATE country_military_assets SET air_defense = MAX(0, air_defense - ?), "
            "updated_at = CURRENT_TIMESTAMP WHERE country_id = ?",
            (int(reserve_loss), int(country_id)),
        )
    total_loss = installed_loss + reserve_loss
    return {
        'installed': int(installed_loss),
        'reserve': int(reserve_loss),
        'total': int(total_loss),
        'remaining': max(0, engaged - total_loss),
    }


def _country_apply_strike_damage(
    country_id: int,
    city_name: str,
    strike_type: str,
    hits: int,
) -> dict:
    """Наносит стране комплексный урон в зависимости от силы попаданий и устойчивости."""
    hits = max(0, int(hits or 0))
    strike_type = str(strike_type or 'missile').lower()
    empty = {
        'population': 0, 'economy': 0, 'military': 0, 'infrastructure': 0,
        'happiness': 0, 'soldiers': 0, 'tanks': 0, 'aircraft': 0,
        'drones': 0, 'missiles': 0, 'equipment': 0, 'ammunition': 0,
        'defense_points': 0, 'buildings': 0,
    }
    if hits <= 0:
        return empty

    country = sql.execute(
        "SELECT population, economy_score, military_score, infrastructure, happiness "
        "FROM countries WHERE id = ?",
        (int(country_id),),
    ).fetchone() or (1000, 0, 0, 0, 0)
    assets = sql.execute(
        "SELECT soldiers, tanks, aircraft, drones, missiles, equipment, ammunition, defense_points "
        "FROM country_military_assets WHERE country_id = ?",
        (int(country_id),),
    ).fetchone() or (0,) * 8

    population = max(1000, int(country[0] or 0))
    economy = max(0, int(country[1] or 0))
    military = max(0, int(country[2] or 0))
    infrastructure = max(0, int(country[3] or 0))
    happiness = max(0, int(country[4] or 0))
    soldiers, tanks, aircraft, drones, missiles, equipment, ammunition, defense_points = [
        max(0, int(value or 0)) for value in assets
    ]

    if strike_type == 'drone':
        impact_per_hit = 520
        civilian_low, civilian_high = 80, 850
        military_exposure = 0.78
    else:
        impact_per_hit = 2_400
        civilian_low, civilian_high = 900, 7_500
        military_exposure = 1.0

    impact_strength = hits * impact_per_hit
    resilience = (
        infrastructure * 1_150
        + military * 720
        + defense_points * 85
        + equipment * 3
        + soldiers // 18
        + max(0, happiness) * 16
    )
    damage_pressure = impact_strength / max(1.0, impact_strength + resilience)
    # Большая армия предоставляет больше целей, но одновременно повышает устойчивость.
    army_target_share = (soldiers + tanks * 120 + aircraft * 180) / max(
        1.0, soldiers + tanks * 120 + aircraft * 180 + population / 35.0
    )
    military_pressure = min(1.0, damage_pressure * (0.72 + army_target_share * military_exposure))

    population_loss = int(_country_random_total(hits, civilian_low, civilian_high) * (0.55 + damage_pressure))
    population_loss = min(max(0, population - 1000), max(0, population_loss))
    economy_loss = min(economy, max(1, int(round(economy * damage_pressure * (0.38 if strike_type == 'drone' else 0.68))))) if economy > 0 else 0
    military_loss = min(military, max(1, int(round(military * military_pressure * (0.42 if strike_type == 'drone' else 0.76))))) if military > 0 else 0
    infrastructure_loss = min(infrastructure, max(1, int(round(infrastructure * damage_pressure * (0.32 if strike_type == 'drone' else 0.64))))) if infrastructure > 0 else 0
    happiness_loss = min(happiness, max(1, int(round((damage_pressure * 24.0) + math.log1p(hits))))) if happiness > 0 else 0

    def asset_loss(stock: int, exposure: float, direct_per_hit: float = 0.0) -> int:
        if stock <= 0:
            return 0
        calculated = stock * military_pressure * exposure + hits * direct_per_hit * damage_pressure
        return min(stock, max(0, int(round(calculated))))

    soldier_loss = asset_loss(soldiers, 0.72 if strike_type == 'missile' else 0.38, 12.0 if strike_type == 'missile' else 3.0)
    tank_loss = asset_loss(tanks, 0.58 if strike_type == 'missile' else 0.32, 0.18 if strike_type == 'missile' else 0.05)
    aircraft_loss = asset_loss(aircraft, 0.36 if strike_type == 'missile' else 0.22, 0.06)
    drone_loss = asset_loss(drones, 0.52 if strike_type == 'missile' else 0.46, 0.10)
    missile_loss = asset_loss(missiles, 0.42 if strike_type == 'missile' else 0.24, 0.06)
    equipment_loss = asset_loss(equipment, 0.62 if strike_type == 'missile' else 0.34, 2.0)
    ammunition_loss = asset_loss(ammunition, 0.70 if strike_type == 'missile' else 0.38, 3.0)
    defense_loss = asset_loss(defense_points, 0.75 if strike_type == 'missile' else 0.45, 0.35)
    damaged_buildings = _country_damage_city_buildings(int(country_id), str(city_name), hits, strike_type)

    sql.execute(
        """UPDATE countries SET
               population = MAX(1000, population - ?),
               economy_score = MAX(0, economy_score - ?),
               military_score = MAX(0, military_score - ?),
               infrastructure = MAX(0, infrastructure - ?),
               happiness = MAX(0, happiness - ?)
           WHERE id = ?""",
        (
            int(population_loss), int(economy_loss), int(military_loss),
            int(infrastructure_loss), int(happiness_loss), int(country_id),
        ),
    )
    sql.execute(
        """UPDATE country_military_assets SET
               soldiers = MAX(0, soldiers - ?), tanks = MAX(0, tanks - ?),
               aircraft = MAX(0, aircraft - ?), drones = MAX(0, drones - ?),
               missiles = MAX(0, missiles - ?), equipment = MAX(0, equipment - ?),
               ammunition = MAX(0, ammunition - ?), defense_points = MAX(0, defense_points - ?),
               updated_at = CURRENT_TIMESTAMP
           WHERE country_id = ?""",
        (
            int(soldier_loss), int(tank_loss), int(aircraft_loss), int(drone_loss),
            int(missile_loss), int(equipment_loss), int(ammunition_loss),
            int(defense_loss), int(country_id),
        ),
    )
    return {
        'population': population_loss, 'economy': economy_loss, 'military': military_loss,
        'infrastructure': infrastructure_loss, 'happiness': happiness_loss,
        'soldiers': soldier_loss, 'tanks': tank_loss, 'aircraft': aircraft_loss,
        'drones': drone_loss, 'missiles': missile_loss, 'equipment': equipment_loss,
        'ammunition': ammunition_loss, 'defense_points': defense_loss,
        'buildings': damaged_buildings,
    }


def _country_enemy_countries(country_id: int):
    rows = sql.execute(
        """SELECT DISTINCT c.id, c.name, c.emoji
           FROM country_wars w
           JOIN country_war_participants own ON own.war_id = w.id AND own.country_id = ?
           JOIN country_war_participants enemy ON enemy.war_id = w.id AND enemy.side != own.side
           JOIN countries c ON c.id = enemy.country_id
           WHERE w.status = 'active' AND COALESCE(c.status, 'active') = 'active'
           ORDER BY c.name""",
        (int(country_id),),
    ).fetchall()
    return rows


def _country_strike_city_keyboard(
    attacker_country_id: int,
    targets,
    strike_type: str,
    quantity: int,
    owner_id: int,
) -> Tuple[str, Keyboard]:
    weapon_name = "ракет" if strike_type == "missile" else "БПЛА"
    lines = [f"🎯 Выберите город для запуска {weapon_name} ×{quantity}:"]
    kb = Keyboard(inline=True)
    buttons = 0
    for target_id, target_name, target_emoji in targets:
        cities = sql.execute(
            "SELECT city_name FROM country_cities WHERE country_id = ? AND is_open = 1 ORDER BY id",
            (int(target_id),),
        ).fetchall()
        if not cities:
            continue
        lines.append(f"{target_emoji} {target_name}: " + ", ".join(str(row[0]) for row in cities))
        for (city_name,) in cities:
            if buttons >= 20:
                continue
            kb.add(
                Callback(
                    f"{target_emoji} {str(city_name)[:28]}",
                    {
                        "command": "country_strike_city",
                        "owner_id": int(owner_id),
                        "attacker_country_id": int(attacker_country_id),
                        "target_country_id": int(target_id),
                        "city_name": str(city_name),
                        "strike_type": str(strike_type),
                        "quantity": int(quantity),
                    },
                ),
                color=KeyboardButtonColor.NEGATIVE,
            )
            buttons += 1
            if buttons % 2 == 0:
                kb.row()
    if buttons >= 20:
        lines.append("\nПоказаны первые 20 кнопок. Для конкретной страны: /запуск ракета 5 Россия")
    return "\n".join(lines), kb




def _country_ensure_pillow() -> None:
    global Image, ImageDraw, ImageFont, ImageFilter, ImageChops, _COUNTRY_PILLOW_INSTALL_ATTEMPTED

    if Image is not None and ImageDraw is not None and ImageFont is not None and ImageFilter is not None and ImageChops is not None:
        return

    try:
        from PIL import Image as _Image, ImageDraw as _ImageDraw, ImageFont as _ImageFont, ImageFilter as _ImageFilter, ImageChops as _ImageChops
        Image, ImageDraw, ImageFont, ImageFilter, ImageChops = _Image, _ImageDraw, _ImageFont, _ImageFilter, _ImageChops
        return
    except ModuleNotFoundError:
        pass

    # Один раз пытаемся установить Pillow автоматически. Если хостинг не
    # разрешает установку пакетов, просто возвращаем понятную ошибку, не
    # останавливая весь бот.
    if not _COUNTRY_PILLOW_INSTALL_ATTEMPTED:
        _COUNTRY_PILLOW_INSTALL_ATTEMPTED = True
        try:
            result = subprocess.run(
                [sys.executable, '-m', 'pip', 'install', '--disable-pip-version-check', '--no-input', 'Pillow'],
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                timeout=120,
                check=False,
            )
            if result.returncode != 0:
                print(f'[WORLD MAP] Pillow install failed: {result.stdout[-1000:]}')
        except Exception as exc:
            print(f'[WORLD MAP] Pillow auto-install error: {exc}')

    try:
        from PIL import Image as _Image, ImageDraw as _ImageDraw, ImageFont as _ImageFont, ImageFilter as _ImageFilter, ImageChops as _ImageChops
        Image, ImageDraw, ImageFont, ImageFilter, ImageChops = _Image, _ImageDraw, _ImageFont, _ImageFilter, _ImageChops
        return
    except ModuleNotFoundError as exc:
        raise RuntimeError(
            'Для команды /карта нужен пакет Pillow. Добавьте Pillow в requirements.txt или установите: pip install Pillow'
        ) from exc


def _country_map_font(size: int, bold: bool = False):
    _country_ensure_pillow()
    cache_key = (int(size), bool(bold))
    cached = _COUNTRY_MAP_FONT_CACHE.get(cache_key)
    if cached is not None:
        return cached

    project_dir = os.path.dirname(os.path.abspath(__file__))
    env_regular = str(os.getenv('COUNTRY_MAP_FONT', '') or '').strip()
    env_bold = str(os.getenv('COUNTRY_MAP_FONT_BOLD', '') or '').strip()
    preferred = []
    if bold and env_bold:
        preferred.append(env_bold)
    if env_regular:
        preferred.append(env_regular)

    local_names = (
        ('NotoSans-Bold.ttf', 'DejaVuSans-Bold.ttf', 'LiberationSans-Bold.ttf')
        if bold else
        ('NotoSans-Regular.ttf', 'DejaVuSans.ttf', 'LiberationSans-Regular.ttf')
    )
    for name in local_names:
        preferred.append(os.path.join(project_dir, 'assets', name))

    system_candidates = [
        '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf' if bold else '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',
        '/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf' if bold else '/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf',
        '/usr/share/fonts/truetype/freefont/FreeSansBold.ttf' if bold else '/usr/share/fonts/truetype/freefont/FreeSans.ttf',
        '/usr/share/fonts/truetype/ubuntu/Ubuntu-B.ttf' if bold else '/usr/share/fonts/truetype/ubuntu/Ubuntu-R.ttf',
        '/usr/share/fonts/opentype/noto/NotoSans-Bold.ttf' if bold else '/usr/share/fonts/opentype/noto/NotoSans-Regular.ttf',
        '/usr/local/share/fonts/DejaVuSans-Bold.ttf' if bold else '/usr/local/share/fonts/DejaVuSans.ttf',
    ]
    preferred.extend(system_candidates)

    # Matplotlib ships DejaVu Sans with Cyrillic glyphs. This is the most
    # reliable fallback for minimal Linux containers without system fonts.
    try:
        from matplotlib import font_manager
        prop = font_manager.FontProperties(family='DejaVu Sans', weight='bold' if bold else 'normal')
        mpl_path = font_manager.findfont(prop, fallback_to_default=False)
        if mpl_path:
            preferred.append(mpl_path)
    except Exception:
        pass

    # Last system scan, without assuming a particular Linux distribution.
    wanted = [name.lower() for name in local_names]
    for root in ('/usr/share/fonts', '/usr/local/share/fonts', os.path.expanduser('~/.fonts')):
        if not os.path.isdir(root):
            continue
        try:
            for current_root, _dirs, files in os.walk(root):
                for filename in files:
                    lower_name = filename.lower()
                    if lower_name in wanted or (lower_name.endswith(('.ttf', '.otf', '.ttc')) and any(token in lower_name for token in ('dejavu', 'noto', 'liberation', 'freesans', 'ubuntu'))):
                        preferred.append(os.path.join(current_root, filename))
        except Exception:
            pass

    checked = set()
    for path in preferred:
        if not path or path in checked or not os.path.isfile(path):
            continue
        checked.add(path)
        try:
            font = ImageFont.truetype(path, size=int(size))
            # Do not silently fall back to Pillow's Latin-only bitmap font.
            # A real TrueType/OpenType font is required for readable Cyrillic.
            _COUNTRY_MAP_FONT_CACHE[cache_key] = font
            return font
        except Exception:
            continue

    raise RuntimeError(
        'Не найден шрифт с поддержкой кириллицы для /карта. '
        'Добавьте matplotlib в requirements.txt и перезапустите бот.'
    )


def _country_wrapped_lines(text: str, limit: int = 34, max_lines: int = 3) -> List[str]:
    words = str(text or '').split()
    if not words:
        return ['—']
    lines = []
    current = words[0]
    for word in words[1:]:
        candidate = current + ' ' + word
        if len(candidate) <= limit:
            current = candidate
        else:
            lines.append(current)
            current = word
            if len(lines) >= max_lines - 1:
                break
    if len(lines) < max_lines:
        tail_words = words[len(' '.join(lines).split()):]
        if tail_words:
            current = ' '.join(tail_words)
        lines.append(current)
    if len(lines) > max_lines:
        lines = lines[:max_lines]
    if len(lines[-1]) > limit:
        lines[-1] = lines[-1][:max(1, limit - 1)] + '…'
    return lines[:max_lines]


def _country_current_alerts(country_id: int):
    rows = sql.execute(
        """SELECT city_name, threat_type FROM country_strike_alerts
           WHERE country_id = ? AND active = 1
             AND datetime(last_launch_at) >= datetime('now', ?)
           ORDER BY city_name""",
        (int(country_id), f'-{COUNTRY_ALERT_CLEAR_MINUTES} minutes'),
    ).fetchall()
    return [(str(r[0]), str(r[1])) for r in rows]


def _country_active_coalition_name(country_id: int) -> Optional[str]:
    row = sql.execute(
        """SELECT co.name
           FROM country_coalition_members m
           JOIN country_coalitions co ON co.id = m.coalition_id AND co.status = 'active'
           WHERE m.country_id = ?
           LIMIT 1""",
        (int(country_id),),
    ).fetchone()
    return str(row[0]) if row and row[0] else None


def _country_wars_for(country_id: int):
    return sql.execute(
        """SELECT DISTINCT w.id
           FROM country_wars w
           JOIN country_war_participants p ON p.war_id = w.id
           WHERE p.country_id = ? AND w.status = 'active'""",
        (int(country_id),),
    ).fetchall()


def _country_public_status(country_id: int) -> str:
    row = sql.execute(
        "SELECT status FROM countries WHERE id = ?",
        (int(country_id),),
    ).fetchone()
    db_status = str(row[0] or 'active') if row else 'active'
    if db_status != 'active':
        return 'destroyed'
    alerts = _country_current_alerts(country_id)
    if alerts:
        return 'alert'
    active_wars = _country_wars_for(country_id)
    is_mobilized, _until = _country_mobilization_state(country_id)
    if active_wars:
        return 'war'
    if is_mobilized:
        return 'mobilization'
    if _country_active_coalition_name(country_id):
        return 'coalition'
    return 'peace'


def _country_status_label(country_id: int) -> str:
    status = _country_public_status(country_id)
    return {
        'peace': 'Мир',
        'war': 'Война',
        'coalition': 'Коалиция',
        'mobilization': 'Мобилизация',
        'alert': 'Тревога',
        'destroyed': 'Уничтожена',
    }.get(status, 'Мир')


def _country_status_color(country_id: int):
    row = sql.execute(
        "SELECT status, conquered_by FROM countries WHERE id = ?",
        (int(country_id),),
    ).fetchone()
    if row and str(row[0] or 'active') != 'active' and row[1]:
        conqueror = sql.execute(
            "SELECT status FROM countries WHERE id = ?",
            (int(row[1]),),
        ).fetchone()
        if conqueror and str(conqueror[0] or 'active') == 'active':
            return COUNTRY_STATUS_COLORS.get(
                _country_public_status(int(row[1])), COUNTRY_STATUS_COLORS['coalition']
            )
    return COUNTRY_STATUS_COLORS.get(_country_public_status(country_id), COUNTRY_STATUS_COLORS['peace'])



# Stable political colors: the same owner always has the same color. Captured
# territories use the conqueror's color and a diagonal hatch on the map.
COUNTRY_TERRITORY_OWNER_COLORS = (
    (76, 151, 255), (239, 83, 80), (92, 196, 126), (255, 183, 77),
    (171, 113, 255), (38, 198, 218), (255, 112, 167), (174, 213, 79),
    (255, 213, 79), (77, 208, 225), (129, 199, 132), (255, 138, 101),
    (149, 117, 205), (79, 195, 247), (220, 231, 117), (244, 143, 177),
    (128, 203, 196), (255, 204, 128), (179, 157, 219), (144, 202, 249),
)


def _country_owner_color(country_id: int):
    country_id = max(1, int(country_id or 1))
    return COUNTRY_TERRITORY_OWNER_COLORS[(country_id - 1) % len(COUNTRY_TERRITORY_OWNER_COLORS)]


def _country_territory_owner(country_id: int) -> int:
    row = sql.execute(
        "SELECT status, conquered_by FROM countries WHERE id = ?",
        (int(country_id),),
    ).fetchone()
    if row and str(row[0] or 'active') != 'active' and row[1]:
        return int(row[1])
    return int(country_id)


def _country_recent_strike_map_items(minutes: int = 45, limit: int = 30):
    """Returns active and recent missile, drone and nuclear trajectories.

    Ordinary missile/drone attacks resolve immediately in the game, therefore
    recently resolved strikes remain visible for a short time as faded trails.
    Pending nuclear launches stay visible until their resolution time.
    """
    try:
        columns = {
            str(row[1]) for row in sql.execute("PRAGMA table_info(country_strikes)").fetchall()
            if len(row) > 1
        }
    except Exception as exc:
        print(f"[WORLD MAP] Не удалось прочитать country_strikes: {exc}")
        return []

    required = {'attacker_country_id', 'target_country_id', 'strike_type', 'status'}
    if not required.issubset(columns):
        return []

    launched_col = 'launched_at' if 'launched_at' in columns else (
        'created_at' if 'created_at' in columns else (
            'resolved_at' if 'resolved_at' in columns else None
        )
    )
    due_col = 'resolves_at' if 'resolves_at' in columns else (
        'arrives_at' if 'arrives_at' in columns else None
    )
    quantity_expr = 'COALESCE(s.quantity, 1)' if 'quantity' in columns else '1'
    city_expr = "COALESCE(s.city_name, '')" if 'city_name' in columns else "''"
    launched_expr = f's.{launched_col}' if launched_col else 'CURRENT_TIMESTAMP'
    due_expr = f's.{due_col}' if due_col else 'NULL'
    recent_clause = (
        f"datetime(COALESCE(s.{launched_col}, CURRENT_TIMESTAMP)) >= datetime('now', ?)"
        if launched_col else '0'
    )
    params = []
    if launched_col:
        params.append(f'-{max(1, int(minutes))} minutes')
    params.append(max(1, int(limit)))

    try:
        rows = sql.execute(
            f"""SELECT s.attacker_country_id, s.target_country_id, s.strike_type,
                       {quantity_expr} AS quantity, s.status, {city_expr} AS city_name,
                       {launched_expr} AS launched_at, {due_expr} AS due_at,
                       a.name, t.name
                FROM country_strikes s
                JOIN countries a ON a.id = s.attacker_country_id
                JOIN countries t ON t.id = s.target_country_id
                WHERE s.status = 'pending' OR ({recent_clause})
                ORDER BY CASE WHEN s.status = 'pending' THEN 0 ELSE 1 END,
                         datetime(COALESCE({due_expr}, {launched_expr}, CURRENT_TIMESTAMP)) DESC
                LIMIT ?""",
            tuple(params),
        ).fetchall()
    except Exception as exc:
        print(f"[WORLD MAP] Не удалось получить траектории ударов: {exc}")
        return []

    items = []
    for attacker_id, target_id, strike_type, quantity, status, city_name, launched_at, due_at, attacker_name, target_name in rows:
        remain = ''
        if due_at and str(status) == 'pending':
            try:
                raw_due = str(due_at).strip().replace('Z', '+00:00')
                if 'T' not in raw_due:
                    raw_due = raw_due.replace(' ', 'T', 1)
                target_dt = datetime.fromisoformat(raw_due)
                now = datetime.now(target_dt.tzinfo) if target_dt.tzinfo else datetime.now()
                total = max(0, int((target_dt - now).total_seconds()))
                days, rem = divmod(total, 86400)
                hours, rem = divmod(rem, 3600)
                minutes_left = rem // 60
                remain = f'{days}д {hours}ч' if days else (f'{hours}ч {minutes_left}м' if hours else f'{minutes_left}м')
            except Exception:
                remain = ''
        items.append({
            'attacker_id': int(attacker_id),
            'target_id': int(target_id),
            'attacker_name': str(attacker_name),
            'target_name': str(target_name),
            'strike_type': str(strike_type or 'missile').lower(),
            'quantity': max(1, int(quantity or 1)),
            'status': str(status or 'resolved'),
            'city_name': str(city_name or ''),
            'launched_at': launched_at,
            'due_at': due_at,
            'remain': remain,
        })
    return items

def _country_world_map_data():
    countries = sql.execute(
        """SELECT c.id, c.name, c.emoji, c.president_id, c.treasury, c.level, c.population, c.status,
                  c.nuclear_unlocked, c.economy_score, c.military_score, c.happiness, c.infrastructure
           FROM countries c
           ORDER BY c.name"""
    ).fetchall()
    wars = []
    war_rows = sql.execute(
        """SELECT id, attacker_id, defender_id, attacker_power, defender_power, started_at
           FROM country_wars WHERE status = 'active' ORDER BY id DESC"""
    ).fetchall()
    for war_id, original_attacker_id, original_defender_id, stored_attack, stored_defense, started_at in war_rows:
        participants = sql.execute(
            """SELECT p.country_id, p.side, c.name, c.emoji
               FROM country_war_participants p
               JOIN countries c ON c.id = p.country_id
               WHERE p.war_id = ?
               ORDER BY CASE WHEN p.country_id IN (?, ?) THEN 0 ELSE 1 END, p.side, c.name""",
            (int(war_id), int(original_attacker_id), int(original_defender_id)),
        ).fetchall()
        attackers = [row for row in participants if str(row[1]) == 'attacker']
        defenders = [row for row in participants if str(row[1]) == 'defender']

        attacker_power = max(0, int(stored_attack or 0))
        defender_power = max(0, int(stored_defense or 0))
        try:
            live_attack = sum(_country_campaign_power(int(row[0]), True)[0] for row in attackers)
            live_defense = sum(_country_campaign_power(int(row[0]), False)[0] for row in defenders)
            if live_attack > 0 or live_defense > 0:
                attacker_power, defender_power = int(live_attack), int(live_defense)
        except Exception as exc:
            print(f'[WORLD MAP] Не удалось рассчитать текущие силы войны #{war_id}: {exc}')

        total_power = max(1, attacker_power + defender_power)
        attack_share = max(0.02, min(0.98, attacker_power / total_power))
        if attack_share >= 0.68:
            stage = 'прорыв атаки'
        elif attack_share >= 0.56:
            stage = 'преимущество атаки'
        elif attack_share <= 0.32:
            stage = 'контрнаступление обороны'
        elif attack_share <= 0.44:
            stage = 'преимущество обороны'
        else:
            stage = 'позиционный фронт'

        original_attacker = _country_row_by_id(int(original_attacker_id))
        original_defender = _country_row_by_id(int(original_defender_id))
        wars.append({
            'id': int(war_id),
            'attackers': attackers,
            'defenders': defenders,
            'attacker_id': int(original_attacker_id),
            'defender_id': int(original_defender_id),
            'attacker_name': str(original_attacker[1]) if original_attacker else (str(attackers[0][2]) if attackers else 'Атакующие'),
            'defender_name': str(original_defender[1]) if original_defender else (str(defenders[0][2]) if defenders else 'Обороняющиеся'),
            'attacker_power': int(attacker_power),
            'defender_power': int(defender_power),
            'attack_share': float(attack_share),
            'stage': stage,
            'started_at': started_at,
        })

    coalition_rows = sql.execute(
        """SELECT co.id, co.name, c.id, c.name, c.emoji
           FROM country_coalitions co
           JOIN country_coalition_members m ON m.coalition_id = co.id
           JOIN countries c ON c.id = m.country_id
           WHERE co.status = 'active'
           ORDER BY co.name, c.name"""
    ).fetchall()
    coalitions = {}
    for cid, name, member_id, member_name, member_emoji in coalition_rows:
        coalitions.setdefault(int(cid), {'name': str(name), 'members': []})['members'].append(
            (int(member_id), str(member_name), str(member_emoji))
        )

    alerts = sql.execute(
        """SELECT a.country_id, c.name, c.emoji, a.city_name, a.threat_type
           FROM country_strike_alerts a
           JOIN countries c ON c.id = a.country_id
           WHERE a.active = 1 AND datetime(a.last_launch_at) >= datetime('now', ?)
           ORDER BY c.name, a.city_name""",
        (f'-{COUNTRY_ALERT_CLEAR_MINUTES} minutes',),
    ).fetchall()
    return countries, wars, list(coalitions.values()), alerts


def _country_pending_nuclear_map_items():
    """Возвращает активные ядерные запуски для карты.

    В основной схеме время завершения хранится в ``resolves_at``. Для
    совместимости со старыми сборками дополнительно поддерживается
    ``arrives_at``. Если время отсутствует, оно вычисляется от launched_at.
    """
    try:
        strike_columns = {
            str(row[1])
            for row in sql.execute("PRAGMA table_info(country_strikes)").fetchall()
            if len(row) > 1
        }
    except Exception as exc:
        print(f"[WORLD MAP] Не удалось прочитать схему country_strikes: {exc}")
        return []

    if "resolves_at" in strike_columns:
        due_column = "resolves_at"
    elif "arrives_at" in strike_columns:
        due_column = "arrives_at"
    else:
        due_column = None

    if due_column:
        due_expression = (
            f"COALESCE(s.{due_column}, "
            f"datetime(s.launched_at, '+{int(COUNTRY_NUCLEAR_FLIGHT_DAYS)} days'))"
        )
    elif "launched_at" in strike_columns:
        due_expression = (
            f"datetime(s.launched_at, '+{int(COUNTRY_NUCLEAR_FLIGHT_DAYS)} days')"
        )
    else:
        due_expression = "NULL"

    try:
        rows = sql.execute(
            f"""SELECT s.attacker_country_id, s.target_country_id,
                       {due_expression} AS due_at,
                       a.name, a.emoji, t.name, t.emoji
                FROM country_strikes s
                JOIN countries a ON a.id = s.attacker_country_id
                JOIN countries t ON t.id = s.target_country_id
                WHERE s.strike_type = 'nuclear' AND s.status = 'pending'
                ORDER BY datetime(due_at) ASC"""
        ).fetchall()
    except Exception as exc:
        print(f"[WORLD MAP] Не удалось получить активные ядерные удары: {exc}")
        return []

    items = []
    for attacker_id, target_id, due_at, attacker_name, attacker_emoji, target_name, target_emoji in rows:
        remain_text = "неизвестно"
        try:
            if due_at:
                raw_due = str(due_at).strip()
                parsed_due = raw_due.replace("Z", "+00:00")
                if "T" not in parsed_due:
                    parsed_due = parsed_due.replace(" ", "T", 1)
                target_dt = datetime.fromisoformat(parsed_due)
                now = datetime.now(target_dt.tzinfo) if target_dt.tzinfo else datetime.now()
                total = int(max(0, (target_dt - now).total_seconds()))
                days, remainder = divmod(total, 86400)
                hours, remainder = divmod(remainder, 3600)
                minutes = remainder // 60
                if days > 0:
                    remain_text = f"{days}д {hours}ч"
                elif hours > 0:
                    remain_text = f"{hours}ч {minutes}м"
                else:
                    remain_text = f"{minutes}м"
        except Exception as exc:
            print(f"[WORLD MAP] Ошибка расчёта времени ядерного удара: {exc}")

        items.append({
            "attacker_id": int(attacker_id),
            "target_id": int(target_id),
            "attacker_name": str(attacker_name),
            "attacker_emoji": str(attacker_emoji),
            "target_name": str(target_name),
            "target_emoji": str(target_emoji),
            "remain": remain_text,
        })
    return items


async def _country_render_world_map(chat_id: int = 0) -> str:
    _country_ensure_pillow()
    countries, wars, coalitions, alerts = _country_world_map_data()
    strike_items = _country_recent_strike_map_items(minutes=45, limit=30)

    project_dir = os.path.dirname(os.path.abspath(__file__))
    asset_dir = os.path.join(project_dir, 'assets')
    base_path = os.path.join(asset_dir, 'world_map_base.png')
    ids_path = os.path.join(asset_dir, 'world_map_country_ids_all.png')
    ids_meta_path = os.path.join(asset_dir, 'world_map_ids_all.json')
    if not os.path.isfile(ids_path):
        ids_path = os.path.join(asset_dir, 'world_map_country_ids_all.png')
    if not os.path.isfile(ids_path):
        ids_path = os.path.join(asset_dir, 'world_map_country_ids.png')
    if not os.path.isfile(base_path) or not os.path.isfile(ids_path):
        raise RuntimeError(
            'Не найдены файлы карты. Загрузите рядом с main.py папку assets '
            'с world_map_base.png, world_map_country_ids_all.png и world_map_ids_all.json.'
        )

    all_asset_ids = {}
    all_geo_points = {}
    if os.path.isfile(ids_meta_path):
        try:
            with open(ids_meta_path, 'r', encoding='utf-8') as fh:
                raw_ids = json.load(fh)
            for country_name, meta in raw_ids.items():
                if not isinstance(meta, dict):
                    continue
                asset_id = int(meta.get('id') or 0)
                iso2 = str(meta.get('iso2') or '').upper()
                if iso2 and asset_id:
                    all_asset_ids[iso2] = asset_id
                if asset_id:
                    all_asset_ids[str(country_name)] = asset_id
                try:
                    all_geo_points[str(country_name)] = (float(meta.get('lon')), float(meta.get('lat')))
                except Exception:
                    pass
        except Exception as exc:
            print(f'[WORLD MAP] Не удалось прочитать world_map_ids_all.json: {exc}')

    canvas_w, canvas_h = 1800, 1040
    map_left, map_top = 24, 118
    map_w, map_h = 1320, 720
    side_left, side_top, side_right, side_bottom = 1365, 118, 1776, 838

    canvas = Image.new('RGBA', (canvas_w, canvas_h), (5, 11, 22, 255))
    draw = ImageDraw.Draw(canvas)
    for y in range(canvas_h):
        t = y / max(1, canvas_h - 1)
        draw.line((0, y, canvas_w, y), fill=(5 + int(7 * t), 11 + int(13 * t), 22 + int(25 * t), 255))
    for x in range(0, canvas_w, 60):
        draw.line((x, 100, x, canvas_h), fill=(17, 31, 51, 70), width=1)
    for y in range(100, canvas_h, 60):
        draw.line((0, y, canvas_w, y), fill=(17, 31, 51, 60), width=1)

    title_font = _country_map_font(34, bold=True)
    subtitle_font = _country_map_font(15, bold=False)
    section_font = _country_map_font(18, bold=True)
    label_font = _country_map_font(14, bold=True)
    small_font = _country_map_font(13, bold=False)
    tiny_font = _country_map_font(11, bold=False)

    def rounded(box, fill, outline=(50, 76, 117, 255), radius=18, width=2):
        draw.rounded_rectangle(box, radius=radius, fill=fill, outline=outline, width=width)

    def fit_text(value, max_chars):
        value = str(value or '')
        return value if len(value) <= max_chars else value[:max(1, max_chars - 1)] + '…'

    def map_xy(country_name):
        name = str(country_name)
        lon_lat = COUNTRY_WORLD_MAP_GEO_POINTS.get(name) or all_geo_points.get(name)
        if not lon_lat:
            return None
        lon, lat = lon_lat
        x = map_left + int((float(lon) + 180.0) / 360.0 * map_w)
        y = map_top + int((85.0 - float(lat)) / 145.0 * map_h)
        return x, y

    def mask_for(asset_id, id_layer):
        lookup = [255 if value == int(asset_id) else 0 for value in range(256)]
        return id_layer.point(lookup)

    def paint_territory(map_layer, binary, color, alpha=135, border_alpha=220, hatch=False):
        fill_alpha = binary.point([0 if value == 0 else int(alpha) for value in range(256)])
        fill = Image.new('RGBA', (map_w, map_h), tuple(color) + (0,))
        fill.putalpha(fill_alpha)
        map_layer.alpha_composite(fill)

        expanded = binary.filter(ImageFilter.MaxFilter(5))
        contracted = binary.filter(ImageFilter.MinFilter(5))
        edge = ImageChops.subtract(expanded, contracted)
        edge_alpha = edge.point([0 if value == 0 else int(border_alpha) for value in range(256)])
        edge_layer = Image.new('RGBA', (map_w, map_h), tuple(color) + (0,))
        edge_layer.putalpha(edge_alpha)
        map_layer.alpha_composite(edge_layer)

        if hatch:
            pattern = Image.new('RGBA', (map_w, map_h), (0, 0, 0, 0))
            pd = ImageDraw.Draw(pattern)
            hatch_color = tuple(min(255, int(channel) + 70) for channel in color) + (190,)
            for offset in range(-map_h, map_w + map_h, 18):
                pd.line((offset, map_h, offset + map_h, 0), fill=hatch_color, width=3)
            try:
                clipped_alpha = ImageChops.multiply(pattern.getchannel('A'), binary)
                pattern.putalpha(clipped_alpha)
                map_layer.alpha_composite(pattern)
            except Exception:
                pass

    def curve_points(p1, p2, lift=80, steps=48):
        x1, y1 = p1
        x2, y2 = p2
        dx, dy = x2 - x1, y2 - y1
        distance = max(1.0, math.hypot(dx, dy))
        # Perpendicular bend makes routes look like trajectories instead of straight lines.
        nx, ny = -dy / distance, dx / distance
        bend = max(35.0, min(float(lift), distance * 0.24))
        cx = (x1 + x2) / 2.0 + nx * bend
        cy = (y1 + y2) / 2.0 + ny * bend
        points = []
        for index in range(steps + 1):
            t = index / steps
            omt = 1.0 - t
            points.append((
                omt * omt * x1 + 2 * omt * t * cx + t * t * x2,
                omt * omt * y1 + 2 * omt * t * cy + t * t * y2,
            ))
        return points

    def draw_arrow_head(points, color, size=10):
        if len(points) < 2:
            return
        x2, y2 = points[-1]
        x1, y1 = points[-2]
        angle = math.atan2(y2 - y1, x2 - x1)
        a1, a2 = angle + math.pi * 0.82, angle - math.pi * 0.82
        draw.polygon((
            (x2, y2),
            (x2 + math.cos(a1) * size, y2 + math.sin(a1) * size),
            (x2 + math.cos(a2) * size, y2 + math.sin(a2) * size),
        ), fill=color)

    def draw_dashed_curve(points, color, width=3, dash=4):
        for index in range(len(points) - 1):
            if (index // dash) % 2 == 0:
                draw.line((points[index], points[index + 1]), fill=color, width=width)

    def draw_war_front(p1, p2, attack_share, war_id):
        points = curve_points(p1, p2, lift=55, steps=64)
        split_index = max(3, min(len(points) - 4, int((len(points) - 1) * float(attack_share))))
        attacker_part = points[:split_index + 1]
        defender_part = points[split_index:]
        draw.line(attacker_part, fill=(255, 82, 82, 235), width=8)
        draw.line(defender_part, fill=(89, 222, 126, 235), width=8)
        front_x, front_y = points[split_index]
        # Jagged front marker.
        jagged = []
        for offset in range(-22, 23, 6):
            jagged.append((front_x + (5 if (offset // 6) % 2 else -5), front_y + offset))
        draw.line(jagged, fill=(255, 238, 157, 255), width=4)
        badge_x, badge_y = points[len(points) // 2]
        text_value = f'#{war_id}  А {int(attack_share * 100)}% / О {100 - int(attack_share * 100)}%'
        bbox = draw.textbbox((0, 0), text_value, font=tiny_font)
        bw = bbox[2] - bbox[0] + 18
        rounded((badge_x - bw / 2, badge_y - 28, badge_x + bw / 2, badge_y - 5),
                (12, 20, 34, 238), (255, 229, 139, 245), radius=8, width=1)
        draw.text((badge_x - bw / 2 + 9, badge_y - 25), text_value,
                  fill=(255, 242, 194, 255), font=tiny_font)

    # Header.
    rounded((24, 18, 1776, 98), (9, 18, 35, 238), radius=22)
    draw.text((45, 29), 'ПОЛИТИЧЕСКАЯ И ВОЕННАЯ КАРТА МИРА', fill=(240, 246, 255, 255), font=title_font)
    draw.text((47, 70),
              f'20 игровых стран • {_autonomous_country_count()} автономных • территории окрашены по фактическому владельцу',
              fill=(156, 180, 213, 255), font=subtitle_font)
    draw.text((1572, 43), datetime.now().strftime('%d.%m.%Y  %H:%M'), fill=(170, 191, 220, 255), font=subtitle_font)

    rounded((map_left - 2, map_top - 2, map_left + map_w + 2, map_top + map_h + 2),
            (8, 16, 29, 255), radius=18)
    map_layer = Image.open(base_path).convert('RGBA')
    if map_layer.size != (map_w, map_h):
        map_layer = map_layer.resize((map_w, map_h), Image.Resampling.LANCZOS)
    id_layer = Image.open(ids_path).convert('L')
    if id_layer.size != (map_w, map_h):
        id_layer = id_layer.resize((map_w, map_h), Image.Resampling.NEAREST)

    player_rows = sql.execute(
        "SELECT id, name, status, conquered_by FROM countries ORDER BY id"
    ).fetchall()
    player_owner_names = {int(row[0]): str(row[1]) for row in player_rows}
    captured_player_count = 0
    captured_auto_count = 0

    # Autonomous territory layer.
    autonomous_rows = sql.execute(
        """SELECT name, iso2, status, conquered_by, economy_score, military_score,
                  development_level, cities_open
           FROM autonomous_countries"""
    ).fetchall()
    for auto_name, iso2, auto_status, conquered_by, auto_economy, auto_military, auto_level, auto_cities in autonomous_rows:
        asset_id = all_asset_ids.get(str(iso2 or '').upper()) or all_asset_ids.get(str(auto_name))
        if not asset_id:
            continue
        conquered = bool(conquered_by)
        if conquered:
            captured_auto_count += 1
            color = _country_owner_color(int(conquered_by))
        elif str(auto_status or 'active') != 'active':
            color = COUNTRY_STATUS_COLORS['destroyed']
        else:
            progress = min(1.0, (int(auto_economy or 0) + int(auto_military or 0) + int(auto_level or 1) * 10) / 700.0)
            color = (int(52 + 30 * progress), int(75 + 44 * progress), int(103 + 58 * progress))
        paint_territory(map_layer, mask_for(asset_id, id_layer), color,
                        alpha=155 if conquered else 100, border_alpha=220 if conquered else 120,
                        hatch=conquered)

    # Player territories, including defeated/captured player states.
    for country_id, country_name, country_status, conquered_by in player_rows:
        asset_id = all_asset_ids.get(str(country_name)) or COUNTRY_WORLD_MAP_ASSET_IDS.get(str(country_name))
        if not asset_id:
            continue
        conquered = str(country_status or 'active') != 'active' and bool(conquered_by)
        if conquered:
            captured_player_count += 1
        owner_id = int(conquered_by) if conquered else int(country_id)
        color = _country_owner_color(owner_id) if (str(country_status or 'active') == 'active' or conquered) else COUNTRY_STATUS_COLORS['destroyed']
        paint_territory(map_layer, mask_for(asset_id, id_layer), color,
                        alpha=175 if conquered else 145, border_alpha=245, hatch=conquered)

    canvas.alpha_composite(map_layer, (map_left, map_top))

    # Coalition links remain subtle underneath combat information.
    for coalition in coalitions:
        members = coalition.get('members', [])
        for index in range(1, len(members)):
            first = map_xy(members[0][1])
            other = map_xy(members[index][1])
            if first and other:
                draw_dashed_curve(curve_points(first, other, lift=35, steps=40), (74, 151, 255, 150), width=2, dash=3)

    # Active wars: a split red/green curved front and exact live force share.
    for war in wars:
        p1 = map_xy(war.get('attacker_name'))
        p2 = map_xy(war.get('defender_name'))
        if p1 and p2:
            draw_war_front(p1, p2, float(war.get('attack_share', 0.5)), int(war.get('id', 0)))

    # Active/recent launch trajectories. Nuclear routes remain visible while pending.
    for strike in reversed(strike_items):
        p1 = map_xy(strike['attacker_name'])
        p2 = map_xy(strike['target_name'])
        if not p1 or not p2:
            continue
        strike_type = strike['strike_type']
        pending = strike['status'] == 'pending'
        if strike_type == 'nuclear':
            color, width, lift, short_label = (255, 213, 64, 255), 5, 135, 'ЯО'
        elif strike_type == 'drone':
            color, width, lift, short_label = (190, 126, 255, 230 if pending else 165), 3, 90, 'БПЛА'
        else:
            color, width, lift, short_label = (255, 132, 73, 235 if pending else 170), 4, 110, 'РКТ'
        points = curve_points(p1, p2, lift=lift, steps=56)
        if pending or strike_type == 'nuclear':
            draw_dashed_curve(points, color, width=width, dash=3)
        else:
            draw.line(points, fill=color, width=width)
        draw_arrow_head(points, color, size=12 if strike_type == 'nuclear' else 9)
        mid_x, mid_y = points[len(points) // 2]
        label = f"{short_label} ×{strike['quantity']}"
        if strike_type == 'nuclear' and strike.get('remain'):
            label += f" • {strike['remain']}"
        elif strike.get('city_name'):
            label += f" • {fit_text(strike['city_name'], 12)}"
        bbox = draw.textbbox((0, 0), label, font=tiny_font)
        bw = bbox[2] - bbox[0] + 16
        rounded((mid_x - bw / 2, mid_y - 14, mid_x + bw / 2, mid_y + 8),
                (10, 17, 30, 232), color, radius=7, width=1)
        draw.text((mid_x - bw / 2 + 8, mid_y - 11), label, fill=(246, 249, 255, 255), font=tiny_font)

    # Player markers and ownership labels.
    ownership_map = {int(row[0]): (str(row[2] or 'active'), row[3]) for row in player_rows}
    for row in countries:
        country_id, name, _emoji, _president_id, _treasury, level, _population, status, nuclear_unlocked, economy_score, military_score, _happiness, _infrastructure = row
        point = map_xy(name)
        if not point:
            continue
        x, y = point
        state, conquered_by = ownership_map.get(int(country_id), ('active', None))
        conquered = state != 'active' and bool(conquered_by)
        owner_id = int(conquered_by) if conquered else int(country_id)
        owner_color = _country_owner_color(owner_id) if (state == 'active' or conquered) else COUNTRY_STATUS_COLORS['destroyed']
        public_status = _country_public_status(int(country_id)) if state == 'active' else 'destroyed'
        ring_color = {
            'war': (255, 76, 76, 255), 'alert': (197, 132, 255, 255),
            'mobilization': (255, 208, 54, 255), 'coalition': (73, 151, 255, 255),
        }.get(public_status, tuple(owner_color) + (255,))
        if public_status in ('war', 'alert', 'mobilization'):
            draw.ellipse((x - 17, y - 17, x + 17, y + 17), outline=ring_color, width=4)
        draw.ellipse((x - 7, y - 7, x + 7, y + 7), fill=tuple(owner_color) + (255,), outline=(245, 250, 255, 255), width=2)

        opened = _country_open_city_total(int(country_id))
        if conquered:
            owner_name = player_owner_names.get(owner_id, f'страна #{owner_id}')
            line1 = f'{name} → {owner_name}'
        else:
            line1 = f'{name} {opened}/{COUNTRY_MAX_CITIES}'
        absolute_label = COUNTRY_WORLD_MAP_LABEL_POSITIONS.get(str(name))
        if absolute_label:
            label_x = map_left + int(absolute_label[0] * map_w / 1100)
            label_y = map_top + int(absolute_label[1] * map_h / 600)
        else:
            dx, dy = COUNTRY_WORLD_MAP_LABEL_OFFSETS.get(str(name), (14, -18))
            label_x, label_y = x + int(dx * map_w / 1100), y + int(dy * map_h / 600)
        box_w = max(90, min(205, draw.textbbox((0, 0), line1, font=label_font)[2] + 18))
        box_h = 27
        label_x = max(map_left + 4, min(label_x, map_left + map_w - box_w - 4))
        label_y = max(map_top + 4, min(label_y, map_top + map_h - box_h - 4))
        rounded((label_x, label_y, label_x + box_w, label_y + box_h),
                (7, 14, 27, 225), tuple(owner_color) + (240,), radius=8, width=1)
        draw.text((label_x + 8, label_y + 5), fit_text(line1, 29), fill=(241, 247, 255, 255), font=label_font)
        if int(nuclear_unlocked or 0) > 0:
            draw.ellipse((label_x + box_w - 13, label_y + 9, label_x + box_w - 7, label_y + 15), fill=(255, 213, 64, 255))

    # Sidebar.
    rounded((side_left, side_top, side_right, side_bottom), (10, 18, 34, 240), radius=20)
    draw.text((side_left + 19, side_top + 18), 'СВОДКА МИРА', fill=(240, 246, 255, 255), font=section_font)
    total_captured = captured_player_count + captured_auto_count
    stats = f'Войн: {len(wars)}  Ударов: {len(strike_items)}  Захвачено: {total_captured}'
    draw.text((side_left + 19, side_top + 48), stats, fill=(151, 177, 211, 255), font=tiny_font)

    def side_section(y, title, lines, accent, max_rows=5):
        draw.text((side_left + 19, y), title, fill=accent, font=label_font)
        panel_top = y + 23
        shown = list(lines[:max_rows]) or ['Нет данных']
        panel_bottom = panel_top + max(48, 16 + len(shown) * 19)
        rounded((side_left + 14, panel_top, side_right - 14, panel_bottom),
                (15, 25, 45, 225), (43, 62, 94, 255), radius=12, width=1)
        yy = panel_top + 10
        for line in shown:
            draw.text((side_left + 26, yy), fit_text(line, 49), fill=(213, 226, 244, 255), font=small_font)
            yy += 19
        return panel_bottom + 13

    war_lines = []
    for war in wars[:5]:
        attack_pct = int(float(war.get('attack_share', 0.5)) * 100)
        war_lines.append(
            f"#{war['id']} {war['attacker_name']} {attack_pct}% — {100 - attack_pct}% {war['defender_name']}"
        )
        war_lines.append(f"  {war.get('stage', 'позиционный фронт')}")
    sy = side_section(side_top + 76, 'АКТИВНЫЕ ФРОНТЫ', war_lines, (255, 112, 112, 255), max_rows=8)

    launch_lines = []
    for strike in strike_items[:6]:
        weapon = 'ЯО' if strike['strike_type'] == 'nuclear' else ('БПЛА' if strike['strike_type'] == 'drone' else 'РКТ')
        suffix = f" ({strike['remain']})" if strike.get('remain') else ''
        launch_lines.append(f"{weapon} ×{strike['quantity']}: {strike['attacker_name']} → {strike['target_name']}{suffix}")
    sy = side_section(sy, 'УДАРЫ И ПОЛЁТЫ', launch_lines, (255, 201, 92, 255), max_rows=6)

    captured_lines = []
    for country_id, country_name, country_status, conquered_by in player_rows:
        if str(country_status or 'active') != 'active' and conquered_by:
            captured_lines.append(f"{country_name} → {player_owner_names.get(int(conquered_by), 'победитель')}")
    for auto_name, _iso2, _status, conquered_by, *_rest in autonomous_rows:
        if conquered_by:
            captured_lines.append(f"{auto_name} → {player_owner_names.get(int(conquered_by), 'победитель')}")
    sy = side_section(sy, 'ЗАХВАЧЕННЫЕ ТЕРРИТОРИИ', captured_lines, (200, 166, 255, 255), max_rows=7)

    event_lines = [f'Тревога: {alert[1]}, {alert[3]}' for alert in alerts[:3]]
    if len(event_lines) < 4:
        for auto_name, _event_type, description, _created_at in _autonomous_recent_events(4 - len(event_lines)):
            event_lines.append(f'{auto_name}: {description}')
    side_section(sy, 'СОБЫТИЯ', event_lines, (220, 229, 242, 255), max_rows=4)

    # Bottom legend.
    rounded((24, 858, 1776, 1015), (9, 18, 34, 240), radius=20)
    draw.text((44, 876), 'КАК ЧИТАТЬ КАРТУ', fill=(240, 246, 255, 255), font=section_font)
    draw.rectangle((45, 918, 73, 942), fill=_country_owner_color(1), outline=(240, 246, 255, 255), width=1)
    draw.text((84, 921), 'цвет территории = фактический владелец', fill=(215, 227, 245, 255), font=small_font)
    draw.rectangle((420, 918, 448, 942), fill=_country_owner_color(2), outline=(240, 246, 255, 255), width=1)
    for offset in range(420, 470, 8):
        draw.line((offset, 942, offset + 24, 918), fill=(250, 250, 250, 220), width=2)
    draw.text((460, 921), 'штриховка = захваченная территория', fill=(215, 227, 245, 255), font=small_font)
    draw.line((805, 930, 870, 930), fill=(255, 82, 82, 255), width=7)
    draw.line((870, 930, 935, 930), fill=(89, 222, 126, 255), width=7)
    draw.text((948, 921), 'линия фронта и доля сил сторон', fill=(215, 227, 245, 255), font=small_font)
    draw.line((1235, 930, 1298, 910), fill=(255, 132, 73, 255), width=4)
    draw.line((1308, 930, 1371, 910), fill=(190, 126, 255, 255), width=4)
    draw.line((1381, 930, 1444, 910), fill=(255, 213, 64, 255), width=5)
    draw.text((1455, 921), 'ракета / БПЛА / ядерный удар', fill=(215, 227, 245, 255), font=small_font)
    draw.text((45, 966),
              'Обычные удары видны 45 минут после запуска; ожидающий ядерный удар остаётся на карте до разрешения.',
              fill=(151, 177, 211, 255), font=small_font)

    fd, output_path = tempfile.mkstemp(prefix='country_world_map_', suffix='.png')
    os.close(fd)
    canvas.convert('RGB').save(output_path, format='PNG', quality=95)
    return output_path



def _country_load_world_assets():
    project_dir = os.path.dirname(os.path.abspath(__file__))
    asset_dir = os.path.join(project_dir, 'assets')
    base_path = os.path.join(asset_dir, 'world_map_base.png')
    ids_path = os.path.join(asset_dir, 'world_map_country_ids.png')
    if not os.path.isfile(base_path) or not os.path.isfile(ids_path):
        raise RuntimeError('Не найдены файлы карты. Загрузите рядом с main.py папку assets с world_map_base.png и world_map_country_ids.png.')
    return base_path, ids_path


def _country_asset_layers(map_w: int, map_h: int):
    _country_ensure_pillow()
    base_path, ids_path = _country_load_world_assets()
    map_layer = Image.open(base_path).convert('RGBA')
    if map_layer.size != (map_w, map_h):
        map_layer = map_layer.resize((map_w, map_h), Image.Resampling.LANCZOS)
    id_layer = Image.open(ids_path).convert('L')
    if id_layer.size != (map_w, map_h):
        id_layer = id_layer.resize((map_w, map_h), Image.Resampling.NEAREST)
    return map_layer, id_layer


def _country_paint_world_status(map_layer, id_layer, countries, focus_country_id=None, dim_others=False):
    """Paint player territories by actual owner, including captured regions."""
    for row in countries:
        country_id, name = int(row[0]), str(row[1])
        asset_id = COUNTRY_WORLD_MAP_ASSET_IDS.get(name)
        if not asset_id:
            continue
        owner_id = _country_territory_owner(country_id)
        captured = owner_id != country_id
        is_focus_owned = focus_country_id is not None and owner_id == int(focus_country_id)
        status_color = _country_owner_color(owner_id)
        if dim_others and focus_country_id is not None and not is_focus_owned:
            status_color = (58, 70, 91)
        lookup = [255 if value == asset_id else 0 for value in range(256)]
        binary = id_layer.point(lookup)
        alpha_value = 205 if is_focus_owned else (145 if captured else 105)
        fill_alpha = binary.point([0 if value == 0 else alpha_value for value in range(256)])
        fill = Image.new('RGBA', map_layer.size, tuple(status_color) + (0,))
        fill.putalpha(fill_alpha)
        map_layer.alpha_composite(fill)
        expanded = binary.filter(ImageFilter.MaxFilter(5))
        contracted = binary.filter(ImageFilter.MinFilter(5))
        edge = ImageChops.subtract(expanded, contracted)
        edge_alpha = edge.point([0 if value == 0 else (255 if is_focus_owned else 205) for value in range(256)])
        edge_layer = Image.new('RGBA', map_layer.size, tuple(status_color) + (0,))
        edge_layer.putalpha(edge_alpha)
        map_layer.alpha_composite(edge_layer)
        if captured and (not dim_others or is_focus_owned):
            pattern = Image.new('RGBA', map_layer.size, (0, 0, 0, 0))
            pd = ImageDraw.Draw(pattern)
            bright = tuple(min(255, int(channel) + 75) for channel in status_color) + (180,)
            width, height = map_layer.size
            for offset in range(-height, width + height, 18):
                pd.line((offset, height, offset + height, 0), fill=bright, width=3)
            try:
                pattern.putalpha(ImageChops.multiply(pattern.getchannel('A'), binary))
                map_layer.alpha_composite(pattern)
            except Exception:
                pass
    return map_layer


def _country_latest_strikes_for_war(war_id: int, limit: int = 6):
    cols = {str(row[1]) for row in sql.execute('PRAGMA table_info(country_strikes)').fetchall() if len(row) > 1}
    launched = 'launched_at' if 'launched_at' in cols else ('created_at' if 'created_at' in cols else 'resolved_at')
    city_sel = 'COALESCE(city_name, "Цель")' if 'city_name' in cols else '"Цель"'
    query = (
        f"SELECT attacker_country_id, target_country_id, strike_type, quantity, status, {city_sel} as city_name "
        f"FROM country_strikes WHERE war_id = ? ORDER BY datetime(COALESCE({launched}, resolved_at, CURRENT_TIMESTAMP)) DESC LIMIT ?"
    )
    return sql.execute(query, (int(war_id), int(limit))).fetchall()


def _country_active_war_context(country_id: int):
    row = sql.execute(
        '''SELECT w.id, w.attacker_id, w.defender_id, w.status, w.attacker_power, w.defender_power, w.started_at
           FROM country_wars w
           JOIN country_war_participants p ON p.war_id = w.id
           WHERE p.country_id = ? AND w.status IN ('active', 'preparation')
           ORDER BY w.id DESC LIMIT 1''',
        (int(country_id),),
    ).fetchone()
    if not row:
        return None
    participants = sql.execute(
        '''SELECT p.country_id, p.side, c.name, c.emoji
           FROM country_war_participants p
           JOIN countries c ON c.id = p.country_id
           WHERE p.war_id = ?
           ORDER BY p.side, c.name''',
        (int(row[0]),),
    ).fetchall()
    return {
        'id': int(row[0]),
        'attacker_id': int(row[1]),
        'defender_id': int(row[2]),
        'status': str(row[3]),
        'attacker_power': int(row[4] or 0),
        'defender_power': int(row[5] or 0),
        'started_at': row[6],
        'attackers': [r for r in participants if str(r[1]) == 'attacker'],
        'defenders': [r for r in participants if str(r[1]) == 'defender'],
    }


def _country_side_assets(country_ids):
    if not country_ids:
        return {'soldiers': 0, 'tanks': 0, 'air_defense': 0, 'missiles': 0, 'ships': 0, 'aircraft': 0, 'drones': 0, 'nuclear_missiles': 0}
    placeholders = ','.join('?' for _ in country_ids)
    row = sql.execute(
        f'''SELECT COALESCE(SUM(soldiers),0), COALESCE(SUM(tanks),0), COALESCE(SUM(air_defense),0), COALESCE(SUM(missiles),0),
                   COALESCE(SUM(ships),0), COALESCE(SUM(aircraft),0), COALESCE(SUM(drones),0), COALESCE(SUM(nuclear_missiles),0)
            FROM country_military_assets WHERE country_id IN ({placeholders})''',
        tuple(int(x) for x in country_ids),
    ).fetchone() or (0,) * 8
    return {'soldiers': int(row[0] or 0), 'tanks': int(row[1] or 0), 'air_defense': int(row[2] or 0), 'missiles': int(row[3] or 0), 'ships': int(row[4] or 0), 'aircraft': int(row[5] or 0), 'drones': int(row[6] or 0), 'nuclear_missiles': int(row[7] or 0)}


def _country_stage_label(attacker_power: int, defender_power: int):
    total = max(1, int(attacker_power) + int(defender_power))
    ratio = float(attacker_power) / float(total)
    if ratio >= 0.68:
        return 'Наступление атакующей стороны', ratio
    if ratio >= 0.56:
        return 'Преимущество атакующей стороны', ratio
    if ratio <= 0.32:
        return 'Наступление обороняющейся стороны', ratio
    if ratio <= 0.44:
        return 'Преимущество обороняющейся стороны', ratio
    return 'Позиционное противостояние', ratio


async def _country_render_country_detail_map(country_id: int, chat_id: int = 0) -> str:
    _country_ensure_pillow()
    country = _country_row_by_id(country_id)
    if not country:
        raise RuntimeError('Государство не найдено.')
    all_countries = sql.execute('SELECT id, name, emoji, president_id, treasury, level, population, status, 0, economy_score, military_score, happiness, infrastructure FROM countries ORDER BY id').fetchall()
    canvas_w, canvas_h = 1600, 920
    canvas = Image.new('RGBA', (canvas_w, canvas_h), (5, 11, 22, 255))
    draw = ImageDraw.Draw(canvas)
    for y in range(canvas_h):
        t = y / max(1, canvas_h - 1)
        draw.line((0, y, canvas_w, y), fill=(6 + int(7 * t), 11 + int(15 * t), 22 + int(24 * t), 255))
    title_font = _country_map_font(30, True)
    section_font = _country_map_font(19, True)
    label_font = _country_map_font(15, True)
    text_font = _country_map_font(14, False)
    tiny_font = _country_map_font(12, False)
    def rr(box, fill, outline=(44, 66, 101, 255), radius=18, width=2):
        draw.rounded_rectangle(box, radius=radius, fill=fill, outline=outline, width=width)
    rr((20, 18, 1580, 92), (10, 18, 35, 235), radius=22)
    draw.text((40, 32), f'КАРТА ГОСУДАРСТВА: {country[1].upper()}', fill=(239, 245, 255, 255), font=title_font)
    draw.text((42, 67), 'Детальная карта страны, её параметры, города, армия и правительство', fill=(156, 180, 213, 255), font=text_font)
    map_left, map_top, map_w, map_h = 30, 120, 900, 500
    rr((map_left - 2, map_top - 2, map_left + map_w + 2, map_top + map_h + 2), (8, 16, 29, 255), radius=18)
    base, ids = _country_asset_layers(map_w, map_h)
    base = _country_paint_world_status(base, ids, all_countries, focus_country_id=country_id, dim_others=True)
    canvas.alpha_composite(base, (map_left, map_top))
    lon_lat = COUNTRY_WORLD_MAP_GEO_POINTS.get(str(country[1]))
    if lon_lat:
        x = map_left + int((float(lon_lat[0]) + 180.0) / 360.0 * map_w)
        y = map_top + int((85.0 - float(lon_lat[1])) / 145.0 * map_h)
        draw.ellipse((x - 9, y - 9, x + 9, y + 9), fill=tuple(_country_status_color(country_id)) + (255,), outline=(245, 250, 255, 255), width=2)
        draw.text((x + 14, y - 26), str(country[1]), fill=(245, 248, 255, 255), font=label_font)

    right_l, right_t, right_r = 960, 120, 1570
    rr((right_l, right_t, right_r, 620), (10, 18, 35, 235), radius=20)
    draw.text((right_l + 20, right_t + 18), 'ПАСПОРТ СТРАНЫ', fill=(239, 245, 255, 255), font=section_font)
    president_name = 'Нет лидера'
    if country[5]:
        try:
            president_name = await get_user_name(int(country[5]), chat_id or None)
        except Exception:
            president_name = f'id{int(country[5])}'
    population = sql.execute('SELECT population, population_capacity FROM countries WHERE id = ?', (int(country_id),)).fetchone() or (0, 0)
    coalition = _country_coalition_for_country(country_id)
    coalition_name = coalition[1] if coalition else 'Нет'
    assets = sql.execute('SELECT soldiers, tanks, air_defense, missiles, ships, aircraft, drones, nuclear_missiles FROM country_military_assets WHERE country_id = ?', (int(country_id),)).fetchone() or (0,) * 8
    buildings = sql.execute('SELECT building_type, COALESCE(SUM(count),0) FROM country_buildings WHERE country_id = ? GROUP BY building_type ORDER BY 2 DESC', (int(country_id),)).fetchall()
    rows = [
        ('Статус', _country_status_label(country_id)), ('Президент', president_name), ('Президентский статус', str(country[6] or '—')),
        ('Казна', format_number(country[3]) + '₽'), ('Налог ИП', f'{int(country[4] or 1)}%'), ('Развитие', f'{_country_open_city_total(country_id)}/{COUNTRY_MAX_CITIES}'),
        ('Экономика', str(country[8])), ('Военная мощь', str(country[9])), ('Счастье', str(country[10])), ('Инфраструктура', str(country[11])),
        ('Население', f'{format_number(population[0])}/{format_number(population[1])}'), ('Коалиция', str(coalition_name)),
    ]
    yy = right_t + 56
    for label, value in rows:
        draw.text((right_l + 22, yy), f'{label}:', fill=(154, 180, 213, 255), font=text_font)
        draw.text((right_l + 250, yy), str(value)[:34], fill=(240, 246, 255, 255), font=text_font)
        yy += 24
    yy += 8
    draw.text((right_l + 20, yy), 'АРМИЯ И ТЕХНИКА', fill=(255, 219, 129, 255), font=label_font)
    yy += 24
    for line in [
        f'Солдаты: {format_number(assets[0])}', f'Танки: {format_number(assets[1])}', f'ПВО: {format_number(assets[2] + _country_total_installed_air_defense(country_id))}',
        f'Ракеты: {format_number(assets[3])}', f'Корабли: {format_number(assets[4])}', f'Авиация: {format_number(assets[5])}', f'БПЛА: {format_number(assets[6])}', f'Ядерные: {format_number(assets[7])}',
    ]:
        draw.text((right_l + 26, yy), line, fill=(218, 228, 244, 255), font=text_font)
        yy += 19
    yy += 8
    draw.text((right_l + 20, yy), 'КЛЮЧЕВЫЕ ПОСТРОЙКИ', fill=(153, 223, 180, 255), font=label_font)
    yy += 24
    if buildings:
        for btype, count in buildings[:8]:
            bname = COUNTRY_BUILDINGS.get(str(btype), {}).get('name', str(btype))
            draw.text((right_l + 26, yy), f'{bname}: {format_number(count)}', fill=(218, 228, 244, 255), font=text_font)
            yy += 18
    else:
        draw.text((right_l + 26, yy), 'Построек пока нет', fill=(218, 228, 244, 255), font=text_font)

    rr((30, 645, 1570, 890), (10, 18, 35, 235), radius=20)
    draw.text((48, 664), 'ГОРОДА И ОБОРОНА', fill=(239, 245, 255, 255), font=section_font)
    city_rows = sql.execute(
        '''SELECT c.city_name, c.is_open, c.level, COALESCE(p.units,0)
           FROM country_cities c
           LEFT JOIN country_city_air_defense p ON p.country_id = c.country_id AND p.city_name = c.city_name
           WHERE c.country_id = ? ORDER BY c.id''',
        (int(country_id),),
    ).fetchall()
    card_w, card_h = 498, 72
    start_x, start_y = 45, 700
    for idx, row in enumerate(city_rows[:18]):
        cx = start_x + (idx % 3) * (card_w + 10)
        cy = start_y + (idx // 3) * (card_h + 10)
        rr((cx, cy, cx + card_w, cy + card_h), (15, 25, 45, 225), (43, 62, 94, 255), radius=14, width=1)
        is_open = int(row[1] or 0) == 1
        status_col = (92, 226, 126, 255) if is_open else (120, 132, 149, 255)
        draw.ellipse((cx + 14, cy + 18, cx + 28, cy + 32), fill=status_col)
        draw.text((cx + 38, cy + 12), str(row[0]), fill=(240, 246, 255, 255), font=label_font)
        draw.text((cx + 38, cy + 36), f"{'Открыт' if is_open else 'Закрыт'} • уровень {int(row[2] or 0)} • ПВО {int(row[3] or 0)}", fill=(170, 191, 219, 255), font=text_font)
    if len(city_rows) > 18:
        draw.text((1320, 862), f'Показано 18 из {len(city_rows)} городов', fill=(151, 177, 211, 255), font=tiny_font)
    fd, output_path = tempfile.mkstemp(prefix='country_detail_map_', suffix='.png')
    os.close(fd)
    canvas.convert('RGB').save(output_path, format='PNG', quality=95)
    return output_path


