    W, H = 1600, 920
    img = Image.new('RGBA', (W, H), (5, 11, 22, 255))
    draw = ImageDraw.Draw(img)
    for y in range(H):
        t = y / max(1, H - 1)
        draw.line((0, y, W, y), fill=(5 + int(8 * t), 11 + int(12 * t), 22 + int(26 * t), 255))
    title_font = _country_map_font(30, True)
    section_font = _country_map_font(18, True)
