def _country_parse_prefix(raw_value: str):
    value = " ".join(str(raw_value or "").strip().split())
    if not value:
        return None, ""
    parts = value.split()
    for end in range(len(parts), 0, -1):
        country = _country_by_name(" ".join(parts[:end]))
        if country:
            return country, " ".join(parts[end:]).strip()
    return None, value


