def _countries_same_coalition(first_country_id: int, second_country_id: int) -> bool:
    if int(first_country_id) == int(second_country_id):
        return True
    row = sql.execute(
        """SELECT 1
           FROM country_coalition_members a
           JOIN country_coalition_members b ON b.coalition_id = a.coalition_id
           JOIN country_coalitions co ON co.id = a.coalition_id AND co.status = 'active'
           WHERE a.country_id = ? AND b.country_id = ?
           LIMIT 1""",
        (int(first_country_id), int(second_country_id)),
    ).fetchone()
    return bool(row)


def _validate_coalition_name(value: str):
    clean = " ".join(str(value or "").strip().split())
    if not 3 <= len(clean) <= 40:
        return False, "Название коалиции должно содержать от 3 до 40 символов."
    if not all(ch.isalpha() or ch.isdigit() or ch in " -_" for ch in clean):
        return False, "В названии разрешены буквы, цифры, пробел, дефис и подчёркивание."
    low = clean.lower().replace("ё", "е")
    if any(word in low for word in _COUNTRY_BAD_WORDS):
        return False, "Название содержит запрещённую лексику."
    existing = sql.execute(
        "SELECT 1 FROM country_coalitions WHERE lower(name) = lower(?) LIMIT 1",
        (clean,),
    ).fetchone()
    if existing:
        return False, "Это название коалиции уже использовалось. Выберите другое."
    return True, clean


