def _country_transaction_totals(country_id: int) -> tuple[int, int]:
    rows = sql.execute(
        "SELECT COALESCE(amount_text, CAST(amount AS TEXT)) FROM country_transactions WHERE country_id = ?",
        (int(country_id),),
    ).fetchall()
    income = 0
    expenses = 0
    for (raw_amount,) in rows:
        try:
            value = int(str(raw_amount or "0"))
        except Exception:
            continue
        if value >= 0:
            income += value
        else:
            expenses += abs(value)
    return income, expenses


