def _build_election_candidates(election_id, country_id):
    country = sql.execute("SELECT president_id FROM countries WHERE id = ?", (int(country_id),)).fetchone()
    president_id = int(country[0]) if country and country[0] else None
    nominated = [int(r[0]) for r in sql.execute("""SELECT n.user_id
        FROM country_election_nominations n
        JOIN country_citizens cc ON cc.user_id = n.user_id
        LEFT JOIN country_activity ca ON ca.country_id = cc.country_id AND ca.user_id = cc.user_id
        WHERE n.election_id = ? AND cc.country_id = ?
          AND NOT EXISTS (SELECT 1 FROM country_prisoners cp WHERE cp.user_id = n.user_id AND cp.status = 'imprisoned')
        ORDER BY COALESCE(ca.activity_points, 0) DESC, n.created_at ASC""", (int(election_id), int(country_id))).fetchall()]
    active = [int(r[0]) for r in sql.execute("""SELECT cc.user_id
        FROM country_citizens cc
        LEFT JOIN country_activity ca ON ca.country_id = cc.country_id AND ca.user_id = cc.user_id
        WHERE cc.country_id = ?
          AND NOT EXISTS (SELECT 1 FROM country_prisoners cp WHERE cp.user_id = cc.user_id AND cp.status = 'imprisoned')
        ORDER BY COALESCE(ca.activity_points, 0) DESC, cc.joined_at ASC""", (int(country_id),)).fetchall()]
    selected = []
    if president_id and president_id in active:
        selected.append(president_id)
    for uid in nominated + active:
        if uid not in selected:
            selected.append(uid)
        if len(selected) >= 3:
            break
    sql.execute("DELETE FROM country_election_candidates WHERE election_id = ?", (int(election_id),))
    for pos, uid in enumerate(selected, 1):
        ap = sql.execute("SELECT activity_points FROM country_activity WHERE country_id = ? AND user_id = ?", (int(country_id), uid)).fetchone()
        sql.execute("INSERT INTO country_election_candidates(election_id, user_id, position, activity_points) VALUES(?, ?, ?, ?)", (int(election_id), uid, pos, int(ap[0]) if ap else 0))
    database.commit()
    return selected

