COUNTRY_DM_PERMISSION_DENIED_USERS = set()


async def _country_dm(user_id, text):
    user_id = int(user_id)
    if user_id in COUNTRY_DM_PERMISSION_DENIED_USERS:
        return False
    try:
        await bot.api.messages.send(user_id=user_id, random_id=0, message=str(text))
        return True
    except Exception as exc:
        error_text = str(exc)
        lowered = error_text.lower()
        if (
            'without permission' in lowered
            or "can't send messages" in lowered
            or 'cannot send messages' in lowered
            or 'messages are disabled' in lowered
        ):
            COUNTRY_DM_PERMISSION_DENIED_USERS.add(user_id)
            return False
        print(f"[COUNTRY DM] Не удалось отправить ЛС user={user_id}: {exc}")
        return False

