def _country_notification_recipients(country_id: int, audience="all") -> List[int]:
    rows = sql.execute(
        """SELECT user_id, COALESCE(government_post, ''), COALESCE(army_rank, -1)
           FROM country_citizens
           WHERE country_id = ?""",
        (int(country_id),),
    ).fetchall()

    if audience is None or audience == "all":
        return [int(row[0]) for row in rows]

    if isinstance(audience, str):
        audiences = {audience}
    else:
        audiences = {str(item) for item in audience if item}

    if "all" in audiences:
        return [int(row[0]) for row in rows]

    allowed_posts = set()
    include_government = "government" in audiences
    minimum_army_rank = None

    for audience_name in audiences:
        allowed_posts.update(COUNTRY_NOTIFICATION_AUDIENCE_POSTS.get(audience_name, set()))
        if audience_name == "military":
            minimum_army_rank = 5 if minimum_army_rank is None else min(minimum_army_rank, 5)
        elif audience_name == "war_command":
            minimum_army_rank = 7 if minimum_army_rank is None else min(minimum_army_rank, 7)

    recipients = []
    for uid, government_post, army_rank in rows:
        post = str(government_post or "")
        rank = int(army_rank if army_rank is not None else -1)
        if include_government and post:
            recipients.append(int(uid))
            continue
        if post in allowed_posts:
            recipients.append(int(uid))
            continue
        if minimum_army_rank is not None and rank >= minimum_army_rank:
            recipients.append(int(uid))

    return list(dict.fromkeys(recipients))


async def _country_broadcast(country_id, text, audience="all"):
    users = _country_notification_recipients(int(country_id), audience)
    sent = 0
    for uid in users:
        if await _country_dm(uid, text):
            sent += 1
        await asyncio.sleep(0.03)
    return sent


async def _country_send_war_alert(country_id: int, text: str) -> dict:
    """Дублирует важное уведомление в ЛС и последние беседы страны.

    Это необходимо, потому что VK может запрещать боту писать пользователю в ЛС.
    """
    country_id = int(country_id)
    recipients = set(_country_notification_recipients(country_id, "all"))
    president = sql.execute(
        "SELECT president_id FROM countries WHERE id = ?",
        (country_id,),
    ).fetchone()
    if president and president[0]:
        recipients.add(int(president[0]))

    dm_sent = 0
    for uid in recipients:
        if await _country_dm(uid, text):
            dm_sent += 1
        await asyncio.sleep(0.03)

    peer_sent = 0
    peers = sql.execute(
        """SELECT peer_id FROM country_alert_peers
           WHERE country_id = ?
           ORDER BY datetime(last_seen_at) DESC LIMIT 3""",
        (country_id,),
    ).fetchall()
    for (alert_peer_id,) in peers:
        try:
            await bot.api.messages.send(
                peer_id=int(alert_peer_id),
                random_id=0,
                message=str(text),
                disable_mentions=1,
            )
            peer_sent += 1
        except Exception as exc:
            print(f"[COUNTRY WAR ALERT] peer={alert_peer_id}: {exc}")
        await asyncio.sleep(0.03)
    return {"dm": dm_sent, "peers": peer_sent}


def _country_election_due(country_id):
    active = _active_country_election(country_id)
    if active:
        return False
    last = sql.execute("SELECT created_at FROM country_elections WHERE country_id = ? ORDER BY id DESC LIMIT 1", (int(country_id),)).fetchone()
    if not last:
        return True
    return bool(sql.execute("SELECT datetime(?) <= datetime('now', ?)", (last[0], f'-{COUNTRY_ELECTION_INTERVAL_DAYS} days')).fetchone()[0])

async def _start_country_election(country_id):
    country = sql.execute("SELECT name, emoji, president_id FROM countries WHERE id = ?", (int(country_id),)).fetchone()
    if not country or _active_country_election(country_id):
        return None
    sql.execute("INSERT INTO country_elections(country_id, status) VALUES(?, 'registration')", (int(country_id),))
    election_id = int(sql.lastrowid)
    if country[2]:
        sql.execute("INSERT OR IGNORE INTO country_election_nominations(election_id, user_id) VALUES(?, ?)", (election_id, int(country[2])))
    database.commit()
    await _country_broadcast(country_id,
        f"{country[1]} 🗳 В государстве {country[0]} автоматически начались выборы президента.\n"
        f"Выдвижение открыто на {COUNTRY_ELECTION_REGISTRATION_HOURS} часов.\n"
        "Подать кандидатуру: /выдвинуться\nПосмотреть состояние: /выборы\n\n"
        "Итоговый бюллетень: действующий президент и два наиболее активных гражданина.")
    return election_id

async def _begin_country_voting(election_id, country_id):
    selected = _build_election_candidates(election_id, country_id)
    country = sql.execute("SELECT name, emoji FROM countries WHERE id = ?", (int(country_id),)).fetchone()
    if len(selected) < 2:
        sql.execute("UPDATE country_elections SET status = 'finished', ended_at = CURRENT_TIMESTAMP WHERE id = ?", (int(election_id),))
        database.commit()
        await _country_broadcast(country_id, f"{country[1]} Выборы в государстве {country[0]} отменены: требуется минимум два гражданина.")
        return
    sql.execute("UPDATE country_elections SET status = 'voting', voting_started_at = CURRENT_TIMESTAMP WHERE id = ?", (int(election_id),))
    database.commit()
    lines = [f"{country[1]} 🗳 Началось голосование за президента государства {country[0]}."]
    for pos, uid in enumerate(selected, 1):
        ap = sql.execute("SELECT activity_points FROM country_election_candidates WHERE election_id = ? AND user_id = ?", (int(election_id), int(uid))).fetchone()
        lines.append(f"{pos}. @id{uid} — активность {int(ap[0]) if ap else 0}")
    lines += [f"\nГолосование продлится {COUNTRY_ELECTION_VOTING_HOURS} часа.", "Отдать голос: /голос [номер]", "Посмотреть результаты: /выборы"]
    await _country_broadcast(country_id, "\n".join(lines))

async def _finish_country_election(election_id, country_id):
    country = sql.execute("SELECT name, emoji, president_id FROM countries WHERE id = ?", (int(country_id),)).fetchone()
    rows = sql.execute("""SELECT c.user_id, c.position, c.activity_points, COUNT(v.voter_id) AS votes
        FROM country_election_candidates c
        LEFT JOIN country_election_votes v ON v.election_id = c.election_id AND v.candidate_id = c.user_id
        WHERE c.election_id = ?
        GROUP BY c.user_id, c.position, c.activity_points
        ORDER BY votes DESC, c.activity_points DESC, c.position ASC""", (int(election_id),)).fetchall()
    if not rows:
        sql.execute("UPDATE country_elections SET status = 'finished', ended_at = CURRENT_TIMESTAMP WHERE id = ?", (int(election_id),))
        database.commit()
        return
    winner = int(rows[0][0])
    old_president = int(country[2]) if country and country[2] else None
    if old_president and old_president != winner:
        sql.execute("UPDATE country_citizens SET government_post = NULL WHERE user_id = ? AND government_post = 'Президент'", (old_president,))
    sql.execute("UPDATE countries SET president_id = ?, president_status = 'Избран' WHERE id = ?", (winner, int(country_id)))
    sql.execute("UPDATE country_citizens SET government_post = 'Президент' WHERE user_id = ?", (winner,))
    sql.execute("UPDATE country_elections SET status = 'finished', ended_at = CURRENT_TIMESTAMP WHERE id = ?", (int(election_id),))
    database.commit()
    lines = [f"{country[1]} 🏛 Выборы президента государства {country[0]} завершены.", f"Победитель: @id{winner}", f"Срок полномочий: {COUNTRY_ELECTION_INTERVAL_DAYS} дней.", "", "Результаты:"]
    for uid, pos, ap, votes in rows:
        lines.append(f"{pos}. @id{uid} — {votes} голос(ов), активность {ap}")
    await _country_broadcast(country_id, "\n".join(lines))

async def country_elections_scheduler():
    await asyncio.sleep(10)
    while True:
        try:
            countries = sql.execute("SELECT id FROM countries WHERE COALESCE(status, 'active') = 'active' ORDER BY id").fetchall()
            for (country_id,) in countries:
                election = _active_country_election(country_id)
                if not election:
                    if _country_election_due(country_id):
                        await _start_country_election(country_id)
                    continue
                election_id, status, created_at, voting_started_at = election
                if status == 'registration':
                    expired = sql.execute("SELECT datetime(?) <= datetime('now', ?)", (created_at, f'-{COUNTRY_ELECTION_REGISTRATION_HOURS} hours')).fetchone()[0]
                    if expired:
                        await _begin_country_voting(election_id, country_id)
                elif status == 'voting' and voting_started_at:
                    expired = sql.execute("SELECT datetime(?) <= datetime('now', ?)", (voting_started_at, f'-{COUNTRY_ELECTION_VOTING_HOURS} hours')).fetchone()[0]
                    if expired:
                        await _finish_country_election(election_id, country_id)
        except Exception as exc:
            print(f"[COUNTRY ELECTIONS] Ошибка цикла: {exc}")
            _reset_sql_cursor()
        await asyncio.sleep(60)


COUNTRY_DEVELOPMENT_TICK_HOURS = 6
COUNTRY_UPGRADE_COOLDOWN_HOURS = 12
COUNTRY_CITY_BASE_COST = 5_000_000_000
COUNTRY_CITY_BASE_POINTS = 250


def _country_upgrade_requirements(opened_cities: int) -> Tuple[int, int]:
    """Цена и очки для открытия следующего города.

    Рост квадратичный: ранние этапы доступны активной стране, а последние
    требуют долгого накопления очков развития и крупной государственной казны.
    """
    stage = max(1, min(COUNTRY_MAX_CITIES - 1, int(opened_cities or 1)))
    cost = COUNTRY_CITY_BASE_COST * (stage ** 2)
    points = COUNTRY_CITY_BASE_POINTS + stage * 150 + (stage ** 2) * 20
    return int(cost), int(points)


def _country_upgrade_cooldown_remaining(country_id: int) -> Optional[timedelta]:
    row = sql.execute(
        "SELECT last_city_opened_at FROM country_development_state WHERE country_id = ?",
        (int(country_id),),
    ).fetchone()
    if not row or not row[0]:
        return None
    try:
        last_opened = datetime.fromisoformat(str(row[0]).replace(" ", "T"))
    except Exception:
        return None
    remaining = timedelta(hours=COUNTRY_UPGRADE_COOLDOWN_HOURS) - (datetime.now() - last_opened)
    return remaining if remaining.total_seconds() > 0 else None


def _country_total_activity(country_id: int) -> int:
    row = sql.execute(
        "SELECT COALESCE(SUM(activity_points), 0) FROM country_activity WHERE country_id = ?",
        (int(country_id),),
    ).fetchone()
    return int(row[0] or 0) if row else 0


def _country_total_tax_income(country_id: int) -> int:
    row = sql.execute(
        """
        SELECT COALESCE(SUM(amount), 0)
        FROM country_transactions
        WHERE country_id = ? AND amount > 0 AND kind IN ('tax', 'company_registration', 'company_rename')
        """,
        (int(country_id),),
    ).fetchone()
    return int(row[0] or 0) if row else 0


async def _run_country_development_tick(country_id: int) -> None:
    if not _country_is_active(country_id):
        return
    country = sql.execute(
        "SELECT name, emoji, treasury, level, economy_score, military_score, happiness, infrastructure, population, population_capacity FROM countries WHERE id = ?",
        (int(country_id),),
    ).fetchone()
    if not country:
        return

    state = sql.execute(
        "SELECT development_points, last_activity_total, last_treasury_income FROM country_development_state WHERE country_id = ?",
        (int(country_id),),
    ).fetchone()
    if not state:
        sql.execute("INSERT OR IGNORE INTO country_development_state(country_id) VALUES(?)", (int(country_id),))
        state = (0, 0, 0)

    citizens_row = sql.execute(
        "SELECT COUNT(*) FROM country_citizens WHERE country_id = ?", (int(country_id),)
    ).fetchone()
    citizens = int(citizens_row[0] or 0) if citizens_row else 0
    activity_total = _country_total_activity(country_id)
    tax_total = _country_total_tax_income(country_id)
    activity_delta = max(0, activity_total - int(state[1] or 0))
    tax_delta = max(0, tax_total - int(state[2] or 0))

    # Активность важнее богатства: деньги помогают, но не могут в одиночку
    # мгновенно открыть все города.
    gained_points = min(250, activity_delta // 5)
    gained_points += min(120, tax_delta // 250_000_000)
    gained_points += min(25, citizens // 3)
    new_points = int(state[0] or 0) + max(0, gained_points)

    economy_gain = min(3, activity_delta // 250 + tax_delta // 5_000_000_000)
    happiness_gain = 1 if citizens >= 5 and activity_delta >= 100 else 0
    if economy_gain or happiness_gain:
        sql.execute(
            """
            UPDATE countries
            SET economy_score = economy_score + ?,
                happiness = MIN(100, happiness + ?)
            WHERE id = ?
            """,
            (int(economy_gain), int(happiness_gain), int(country_id)),
        )

    # Население — виртуальный показатель государства. Оно растёт при сильной
    # экономике, высокой удовлетворённости и развитой инфраструктуре, а при
    # кризисах и войне жители уезжают. Количество аккаунтов-граждан напрямую
    # численность населения не задаёт.
    old_population = max(1, int(country[8] or 100000))
    capacity = max(old_population, int(country[9] or 250000))
    active_wars_row = sql.execute(
        "SELECT COUNT(*) FROM country_wars WHERE status = 'active' AND (attacker_id = ? OR defender_id = ?)",
        (int(country_id), int(country_id)),
    ).fetchone()
    active_wars = int(active_wars_row[0] or 0) if active_wars_row else 0
    open_cities_row = sql.execute(
        "SELECT COUNT(*) FROM country_cities WHERE country_id = ? AND is_open = 1",
        (int(country_id),),
    ).fetchone()
    open_cities = max(1, int(open_cities_row[0] or 1)) if open_cities_row else 1
    infrastructure_value = max(0, int(country[7] or 0))
    desired_capacity = max(
        capacity,
        open_cities * 250000 + infrastructure_value * 120000,
    )

    # Инфраструктура является главным долгосрочным ускорителем демографии.
    # Формула плавная: каждый новый уровень полезен, но эффект не растёт бесконечно.
    infrastructure_growth = min(0.018, infrastructure_value / (6500.0 + infrastructure_value * 20.0))
    growth_rate = 0.0006
    growth_rate += infrastructure_growth
    growth_rate += (int(country[4]) - 100) / 120000.0
    growth_rate += (int(country[6]) - 60) / 30000.0
    growth_rate += min(0.0025, activity_delta / 450000.0)
    growth_rate -= active_wars * 0.005
    if infrastructure_value < 5:
        growth_rate -= (5 - infrastructure_value) * 0.0005
    if int(country[6]) < 35:
        growth_rate -= 0.006
    if int(country[4]) < 60:
        growth_rate -= 0.004
    growth_rate = max(-0.025, min(0.025, growth_rate))

    population_change = int(old_population * growth_rate)
    if growth_rate > 0 and old_population >= desired_capacity:
        population_change = -max(1, int(old_population * 0.001))
    new_population = max(1000, min(desired_capacity, old_population + population_change))

    # Численность регулярной армии также формируется автоматически.
    # Военная мощь, население и активная война определяют целевой размер.
    military_share = 0.006 + min(0.024, max(0, int(country[5])) / 5000.0)
    if active_wars:
        military_share += 0.012
    target_soldiers = max(500, int(new_population * military_share))
    assets = sql.execute(
        "SELECT soldiers, mobilization_until FROM country_military_assets WHERE country_id = ?",
        (int(country_id),),
    ).fetchone()
    old_soldiers = int(assets[0] or 0) if assets else 0
    mobilization_active = False
    if assets and assets[1]:
        try:
            mobilization_active = datetime.fromisoformat(str(assets[1]).replace(" ", "T")) > datetime.now()
        except Exception:
            mobilization_active = False
    if mobilization_active:
        military_share += 0.035
        target_soldiers = max(target_soldiers, int(new_population * min(0.12, military_share)))
    if target_soldiers > old_soldiers:
        recruitment_rate = (
            0.00020
            + infrastructure_value / 220000.0
            + max(0, int(country[6] or 0)) / 500000.0
        )
        if active_wars:
            recruitment_rate *= 1.65
        if int(country[4] or 0) < 50 or int(country[6] or 0) < 30:
            recruitment_rate *= 0.55
        recruitment_rate = max(0.00005, min(0.004, recruitment_rate))
        recruitment_capacity = max(50, int(new_population * recruitment_rate))
        new_soldiers = old_soldiers + min(target_soldiers - old_soldiers, recruitment_capacity)
    else:
        step = max(1, abs(target_soldiers - old_soldiers) // 4)
        new_soldiers = max(target_soldiers, old_soldiers - step)

    sql.execute(
        "UPDATE countries SET population = ?, population_capacity = ? WHERE id = ?",
        (int(new_population), int(desired_capacity), int(country_id)),
    )
    sql.execute(
        "UPDATE country_military_assets SET soldiers = ?, updated_at = CURRENT_TIMESTAMP WHERE country_id = ?",
        (int(new_soldiers), int(country_id)),
    )

    # Фоновый цикл больше не открывает города автоматически.
    # Он только накапливает очки развития; решение принимает президент.

    sql.execute(
        """
        INSERT INTO country_development_state(
            country_id, development_points, last_activity_total,
            last_treasury_income, last_tick_at, last_city_opened_at
        ) VALUES(?, ?, ?, ?, CURRENT_TIMESTAMP, CASE WHEN ? <> 0 THEN CURRENT_TIMESTAMP ELSE NULL END)
        ON CONFLICT(country_id) DO UPDATE SET
            development_points = excluded.development_points,
            last_activity_total = excluded.last_activity_total,
            last_treasury_income = excluded.last_treasury_income,
            last_tick_at = CURRENT_TIMESTAMP,
            last_city_opened_at = CASE
                WHEN excluded.last_city_opened_at IS NOT NULL THEN excluded.last_city_opened_at
                ELSE country_development_state.last_city_opened_at
            END
        """,
        (int(country_id), int(new_points), int(activity_total), int(tax_total), 0),
    )
    database.commit()

    if _country_award_nuclear_if_ready(country_id):
        await _country_broadcast(
            country_id,
            f"{country[1]} ☢ Государство {country[0]} достигло максимального развития.\n\n"
            "Все города открыты. В стратегический арсенал передана одна ядерная ракета.\n"
            "Применение возможно только против государства с противоположной стороны активной войны.",
            audience="military",
        )

    # Не спамим каждые 6 часов: сообщаем только о заметном изменении.
    population_delta = int(new_population) - int(old_population)
    population_notice_threshold = max(10000, int(old_population * 0.02))
    if abs(population_delta) >= population_notice_threshold:
        direction = "выросло" if population_delta > 0 else "сократилось"
        reason = "развитию экономики и инфраструктуры" if population_delta > 0 else "экономическим трудностям или военной обстановке"
        await _country_broadcast(
            country_id,
            f"{country[1]} 👥 Население государства {country[0]} заметно {direction}.\n\n"
            f"Изменение: {population_delta:+,} жителей\n".replace(",", ".")
            + f"Текущее население: {format_number(new_population)}\n"
            + f"Причина связана с {reason}.",
            audience="social",
        )

    soldier_delta = int(new_soldiers) - int(old_soldiers)
    soldier_notice_threshold = max(5000, int(max(1, old_soldiers) * 0.15))
    if old_soldiers > 0 and abs(soldier_delta) >= soldier_notice_threshold:
        action = "мобилизацию" if soldier_delta > 0 else "сокращение вооружённых сил"
        await _country_broadcast(
            country_id,
            f"{country[1]} ⚔ Государство {country[0]} проводит {action}.\n"
            f"Численность армии: {format_number(new_soldiers)} военнослужащих.",
            audience="military",
        )


async def country_development_scheduler():
    await asyncio.sleep(20)
    while True:
        try:
            countries = sql.execute("SELECT id FROM countries WHERE COALESCE(status, 'active') = 'active' ORDER BY id").fetchall()
            for (country_id,) in countries:
                state = sql.execute(
                    "SELECT last_tick_at FROM country_development_state WHERE country_id = ?",
                    (int(country_id),),
                ).fetchone()
                due = not state or not state[0]
                if state and state[0]:
                    row = sql.execute(
                        "SELECT datetime(?) <= datetime('now', ?)",
                        (state[0], f'-{COUNTRY_DEVELOPMENT_TICK_HOURS} hours'),
                    ).fetchone()
                    due = bool(row and row[0])
                if due:
                    await _run_country_development_tick(int(country_id))
                    await asyncio.sleep(0.05)
        except Exception as exc:
            print(f"[COUNTRY DEVELOPMENT] Ошибка цикла: {exc}")
            _reset_sql_cursor()
        await asyncio.sleep(300)

