async def _perform_user_reset(target_user_id: int, ptype: str):
    global balances
    uid = str(target_user_id)
    if uid in balances:
        if ptype in ("balance", "all"):
            balances[uid]["wallet"] = 0
        if ptype in ("bank", "all"):
            balances[uid]["bank"] = 0
        if ptype in ("vip", "all"):
            balances[uid]["vip_until"] = None
        if ptype in ("bananas", "all"):
            balances[uid]["bananas"] = 0
        if ptype in ("rebirth", "all"):
            balances[uid]["rebirth"] = 0
        save_data(BALANCES_FILE, balances)
        _drop_user_cache(target_user_id)

    async with DB_WRITE_LOCK:
        db = await connect_sqlite()
        try:
            if ptype in ("business", "all"):
                await db.execute("DELETE FROM businesses WHERE user_id = ?", (target_user_id,))
            if ptype in ("cases", "all"):
                await db.execute("DELETE FROM user_cases WHERE user_id = ?", (target_user_id,))
            if ptype in ("inventory", "items", "all"):
                await db.execute("DELETE FROM inventory WHERE user_id = ?", (target_user_id,))
            await db.commit()
        finally:
            await db.close()


