# ================== РЕФЕРАЛЬНАЯ СИСТЕМА ==================
REFERRAL_MIN_REWARD = 1_000_000
REFERRAL_MAX_REWARD = 25_000_000
REFERRAL_PRIZE_MULTIPLIER = 10
REFERRAL_INVITED_PERCENT = 50
REFERRAL_DAILY_PAID_LIMIT = 5
REFERRAL_DB_FILE = "database.db"
DUELS_CHAT_URL = "https://vk.me/join/Bp/rS5GCao5gcWOOKtuX/qA7Uc4x0acv78g="
_referral_balance_lock = asyncio.Lock()




def _current_referral_rewards() -> tuple[int, int]:
    """Возвращает стабильные награды пригласившему и новому пользователю.

    Награда привязана к актуальному базовому /приз, но ограничена снизу и
    сверху. Поэтому после вайпа она автоматически уменьшается и никогда не
    разгоняет экономику фиксированной выплатой в миллиард.
    """
    try:
        settings = get_daily_economy_settings()
        prize_base = max(1, int(settings.get("prize_base", BASE_ECONOMY_PRIZE) or BASE_ECONOMY_PRIZE))
    except Exception:
        prize_base = int(BASE_ECONOMY_PRIZE)

    inviter_reward = round_economy_amount(prize_base * REFERRAL_PRIZE_MULTIPLIER)
    inviter_reward = max(REFERRAL_MIN_REWARD, min(REFERRAL_MAX_REWARD, int(inviter_reward)))
    invited_reward = round_economy_amount(inviter_reward * REFERRAL_INVITED_PERCENT // 100)
    invited_reward = max(500_000, min(inviter_reward, int(invited_reward)))
    return inviter_reward, invited_reward


def _has_meaningful_economy_progress(balance_data: dict) -> bool:
    """Не позволяет старому развитому аккаунту получать стартовую награду."""
    if not isinstance(balance_data, dict):
        return False
    numeric_fields = (
        "wallet", "bank", "won", "lost", "won_total", "lost_total",
        "received_total", "sent_total", "bananas", "donated",
        "business_income_today",
    )
    for field in numeric_fields:
        try:
            if int(balance_data.get(field, 0) or 0) != 0:
                return True
        except Exception:
            continue
    return bool(balance_data.get("vip_until") or balance_data.get("nolim_until"))


