@bot.on.chat_message(rules.ChatActionRule("chat_kick_user"))
async def user_leave(message: Message) -> None:
    user_id = message.from_id
    chat_id = message.chat_id
    if not await check_chat(chat_id): return True
    if not message.action.member_id == message.from_id: return True
    if await leave_kick(chat_id):
        try: await bot.api.messages.remove_chat_user(chat_id, user_id)
        except: pass
        await message.answer(f"@id{user_id} ({await get_user_name(user_id, chat_id)}), вышел(-ла) из беседы", disable_mentions=1)
    else:
        keyboard = (
            Keyboard(inline=True)
            .add(Callback("Исключить", {"command": "kick", "user": user_id, "chatId": chat_id}), color=KeyboardButtonColor.NEGATIVE)
        )
        await message.answer(f"@id{user_id} ({await get_user_name(user_id, chat_id)}), вышел(-ла) из беседы", disable_mentions=1, keyboard=keyboard)

@bot.on.chat_message(rules.ChatActionRule("chat_invite_user"))
@bot.on.chat_message(rules.ChatActionRule("chat_invite_user_by_link"))
async def user_joined(message: Message) -> None:
    action = getattr(message, "action", None)
    user_id = message.from_id
    chat_id = message.chat_id    
    if not chat_id:
        return True
    action_type = getattr(action, "type", None)
    joined_by_link = action_type == "chat_invite_user_by_link"
    invited_user = getattr(action, "member_id", None)
    if invited_user is None and joined_by_link:
        invited_user = user_id
    if invited_user is None:
        return True
        
    async def _safe_first_name(uid: int) -> str:
        try:
            resp = await bot.api.users.get(uid)
            if resp and len(resp) > 0:
                return resp[0].first_name
        except Exception:
            pass
        return str(uid)

    try:
        # Бот добавлен
        if invited_user == -groupid:
            # Проверка: если чат был удален через /delchat (в banschats), но не зарегистрирован в chats — восстановить
            banned_chat_row = await db_execute("SELECT chat_id FROM banschats WHERE chat_id = ?", (chat_id,), fetch='one')
            is_registered = await check_chat(chat_id)
            
            if banned_chat_row and not is_registered:
                # Восстанавливаем чат: удаляем из banschats и добавляем в chats
                sql.execute("DELETE FROM banschats WHERE chat_id = ?", (chat_id,))
                database.commit()
                await new_chat(chat_id, message.peer_id, user_id, "def")
                database.commit()
                print(f"[CHAT RESTORED] Чат {chat_id} восстановлен из banschats при добавлении бота")
            
            await message.answer(
                "Бот добавлен в беседу, выдайте мне администратора, а затем введите /start для активации беседы!\n\n"
                "Также с помощью /type Вы можете выбрать тип беседы!"
            )
            return True

        if not await check_chat(chat_id):
            return True

        # ==== 🔹 Глобальный антиспам по добавлению сторонних сообществ ====
        # Если пользователь ранее несколько раз пытался добавлять сторонние
        # сообщества в защищённые беседы, он автоматически удаляется при
        # любом последующем вступлении или добавлении в зарегистрированный чат.
        if int(invited_user) > 0 and _is_community_spammer(int(invited_user)):
            kicked = await _protection_kick(chat_id, int(invited_user))
            try:
                spammer_name = await get_user_name(int(invited_user), chat_id)
            except Exception:
                spammer_name = str(invited_user)
            await message.answer(
                f"🚫 @id{int(invited_user)} ({spammer_name}) автоматически исключён: "
                f"пользователь внесён в список спамеров за частое добавление сторонних сообществ."
                + ("" if kicked else "\n⚠️ Боту не удалось исключить пользователя — проверьте права администратора."),
                disable_mentions=1,
            )
            return True

        # ==== 🔹 Проверка защиты от сторонних сообществ ====
        sql.execute("SELECT mode FROM protection WHERE chat_id = ?", (chat_id,))
        prot = sql.fetchone()
        protection_enabled = bool(prot and int(prot[0] or 0) == 1)
        if protection_enabled and int(invited_user) < 0:  # стороннее сообщество
            community_kicked = await _protection_kick(chat_id, int(invited_user))

            # message.from_id — пользователь, совершивший действие добавления.
            inviter_id = int(user_id) if int(user_id or 0) > 0 else 0
            inviter_kicked = False
            strikes = 0
            became_spammer = False
            if inviter_id > 0:
                strikes, became_spammer = _record_community_spam_attempt(
                    inviter_id, chat_id, int(invited_user)
                )
                inviter_kicked = await _protection_kick(chat_id, inviter_id)

            try:
                inviter_name = await get_user_name(inviter_id, chat_id) if inviter_id > 0 else "неизвестный пользователь"
            except Exception:
                inviter_name = str(inviter_id or "неизвестно")

            details = []
            if not community_kicked:
                details.append("⚠️ Не удалось исключить сообщество — проверьте права бота.")
            if inviter_id > 0 and not inviter_kicked:
                details.append("⚠️ Не удалось исключить пригласившего — возможно, у него права выше прав бота.")
            if became_spammer:
                details.append(
                    f"🚨 Пользователь внесён в глобальный список спамеров "
                    f"({strikes} нарушений за {COMMUNITY_SPAM_WINDOW_HOURS} ч.)."
                )
            elif inviter_id > 0 and strikes > 0:
                details.append(
                    f"Нарушений за {COMMUNITY_SPAM_WINDOW_HOURS} ч.: {strikes}/{COMMUNITY_SPAM_THRESHOLD}."
                )

            suffix = ("\n" + "\n".join(details)) if details else ""
            await message.answer(
                f"🛡 @id{inviter_id} ({inviter_name}) добавил стороннее сообщество. "
                f"Сообщество и пригласивший исключены системой защиты.{suffix}\n\n"
                f"Чтобы выключить защиту, используйте /защита",
                disable_mentions=1,
            )
            return True

        # ==== 🔹 Проверка глобального бана ====
        sql.execute("SELECT * FROM blacklist WHERE user_id = ?", (invited_user,))
        blacklist_user = sql.fetchone()
        if blacklist_user:
            try:
                await bot.api.messages.remove_chat_user(chat_id, invited_user)
            except:
                pass

            await message.answer(
                f"@id{invited_user} ({await get_user_name(invited_user, chat_id)}) находится в ЧСБ ADMIN MANAGER.",
                disable_mentions=1
            )
            return True
            
        # ==== Проверка блокировки в беседах игроков (gbanpl) — кик из чата ====
        sql.execute("SELECT * FROM gbanlist WHERE user_id = ?", (invited_user,))
        gbanpl_entry = sql.fetchone()
        if gbanpl_entry:
            try:
                await bot.api.messages.remove_chat_user(chat_id, invited_user)
            except:
                pass

            first = await _safe_first_name(invited_user)
            await message.answer(
                f"@id{invited_user} ({await get_user_name(invited_user, chat_id)}) заблокирован(-а) в беседах игроков!\n\n"
                f"@id{gbanpl_entry[1]} (Модератор) | {gbanpl_entry[2]} | {gbanpl_entry[3]}",
                disable_mentions=1
            )
            return True

        # ==== Проверка ЧС игр (банигры) — НЕ кикает, только уведомление ====
        sql.execute("SELECT * FROM games_blacklist WHERE user_id = ?", (invited_user,))
        games_bl = sql.fetchone()
        if games_bl:
            first = await _safe_first_name(invited_user)
            await message.answer(
                f"@id{invited_user} ({await get_user_name(invited_user, chat_id)}) находится в ЧС игр (заблокированы игровые команды).\n\n"
                f"@id{games_bl[1]} (Модератор) | {games_bl[2]} | {games_bl[3]}",
                disable_mentions=1
            )
            # НЕ кикаем — ЧС игр только блокирует игровые команды
        # ==== Пользователь вошёл сам ====
        if user_id == invited_user or joined_by_link:
            checkban_str = await checkban(invited_user, chat_id)
            if checkban_str:
                try:
                    await bot.api.messages.remove_chat_user(chat_id, invited_user)
                except:
                    pass

                first = await _safe_first_name(invited_user)
                keyboard = (
                    Keyboard(inline=True)
                    .add(Callback("✅ Снять бан", {"command": "unban", "user": invited_user, "chatId": chat_id}), color=KeyboardButtonColor.POSITIVE)
                )
                await message.answer(
                    f"@id{invited_user} ({await get_user_name(invited_user, chat_id)}) заблокирован(-а) в этой беседе!\n\n"
                    f"Информация о блокировке:\n@id{checkban_str['moder']} (Модератор) | {checkban_str['reason']} | {checkban_str['date']}",
                    disable_mentions=1,
                    keyboard=keyboard
                )
                return True

            welcome = await get_welcome(chat_id)
            if welcome:
                welcome = welcome.replace('%u', f'@id{invited_user}')
                welcome = welcome.replace('%n', f'@id{invited_user} ({await get_user_name(invited_user, chat_id)})')
                welcome = welcome.replace('%i', f'@id{user_id}')
                welcome = welcome.replace('%p', f'@id{user_id} ({await get_user_name(user_id, chat_id)})')
                await message.answer(welcome)
            return True

        # ==== Кто-то пригласил другого пользователя ====
        if not await _can_use_command(user_id, chat_id, 1) and await invite_kick(chat_id):
            try:
                await bot.api.messages.remove_chat_user(chat_id, invited_user)
            except:
                pass
            return True

        checkban_str = await checkban(invited_user, chat_id)
        if checkban_str:
            try:
                await bot.api.messages.remove_chat_user(chat_id, invited_user)
            except:
                pass

            first = await _safe_first_name(invited_user)
            keyboard = (
                Keyboard(inline=True)
                .add(Callback("✅ Снять бан", {"command": "unban", "user": invited_user, "chatId": chat_id}), color=KeyboardButtonColor.POSITIVE)
            )
            await message.answer(
                f"@id{invited_user} ({await get_user_name(invited_user, chat_id)}) заблокирован(-а) в этой беседе!\n\n"
                f"Информация о блокировке:\n@id{checkban_str['moder']} (Модератор) | {checkban_str['reason']} | {checkban_str['date']}",
                disable_mentions=1,
                keyboard=keyboard
            )
            return True

        welcome = await get_welcome(chat_id)
        if welcome:
            first = await _safe_first_name(invited_user)
            inviter_first = await _safe_first_name(user_id)
            welcome = welcome.replace('%u', f'@id{invited_user}')
            welcome = welcome.replace('%n', f'@id{invited_user} ({await get_user_name(invited_user, chat_id)})')
            welcome = welcome.replace('%i', f'@id{user_id}')
            welcome = welcome.replace('%p', f'@id{user_id} ({await get_user_name(user_id, chat_id)})')
            await message.answer(welcome)
            return True

    except Exception as e:
        print(f"[user_joined] Ошибка: {e}")
        return True        


def _dice_load_games() -> dict:
    data = load_data(DICE_GAMES_FILE)
    return data if isinstance(data, dict) else {}


def _dice_save_games(data: dict) -> None:
    save_data(DICE_GAMES_FILE, data)


def _dice_load_dealers() -> set[int]:
    data = load_data(DICE_DEALERS_FILE)
    if isinstance(data, dict):
        values = data.get("dealers", [])
    else:
        values = data if isinstance(data, list) else []
    result = set()
    for value in values:
        try:
            result.add(int(value))
        except Exception:
            pass
    return result


def _dice_save_dealers(dealers: set[int]) -> None:
    save_data(DICE_DEALERS_FILE, {"dealers": sorted(int(x) for x in dealers)})


def _dice_lock(chat_id: int) -> asyncio.Lock:
    chat_id = int(chat_id)
    lock = DICE_GAME_LOCKS.get(chat_id)
    if lock is None:
        lock = asyncio.Lock()
        DICE_GAME_LOCKS[chat_id] = lock
    return lock


def _dice_money(amount: int) -> str:
    return f"{format_number(int(amount))}₽"


async def _dice_name(user_id: int) -> str:
    user_id = int(user_id)
    cached = DICE_NAME_CACHE.get(user_id)
    if cached:
        return cached
    try:
        info = await bot.api.users.get(user_ids=user_id)
        name = f"{info[0].first_name} {info[0].last_name}"
    except Exception:
        name = str(user_id)
    DICE_NAME_CACHE[user_id] = name
    return name


async def _dice_mention(user_id: int) -> str:
    return f"[id{int(user_id)}|{await _dice_name(int(user_id))}]"


DICE_DEALERS_PER_PAGE = 10


async def _dice_dealers_page(page: int = 1):
    dealer_ids = sorted(_dice_load_dealers())
    dealer_rows = []
    for dealer_id in dealer_ids:
        dealer_rows.append((await _dice_name(dealer_id), dealer_id))
    dealer_rows.sort(key=lambda item: item[0].casefold())

    total_pages = max(1, (len(dealer_rows) + DICE_DEALERS_PER_PAGE - 1) // DICE_DEALERS_PER_PAGE)
    page = max(1, min(int(page or 1), total_pages))
    start = (page - 1) * DICE_DEALERS_PER_PAGE
    current_rows = dealer_rows[start:start + DICE_DEALERS_PER_PAGE]

    lines = ["🎲 Крупье", ""]
    if current_rows:
        lines.extend(f"- [id{dealer_id}|{name}]" for name, dealer_id in current_rows)
    else:
        lines.append("Крупье пока не назначены.")

    keyboard = Keyboard(inline=True)
    previous_page = page - 1 if page > 1 else 1
    next_page = page + 1 if page < total_pages else total_pages
    keyboard.add(
        Callback("⏪️", {"command": "dice_dealers_page", "page": previous_page}),
        color=KeyboardButtonColor.SECONDARY,
    )
    keyboard.add(
        Callback(f"{page}/{total_pages}", {"command": "dice_dealers_page", "page": page}),
        color=KeyboardButtonColor.SECONDARY,
    )
    keyboard.add(
        Callback("⏩️", {"command": "dice_dealers_page", "page": next_page}),
        color=KeyboardButtonColor.SECONDARY,
    )
    return "\n".join(lines), keyboard, page, total_pages


def _dice_keyboard(game: dict, enabled: bool = True):
    kb = Keyboard(inline=True)
    game_id = str(game.get("game_id", ""))
    if enabled:
        kb.add(Callback("🎲 Бросить кости", {"command": "dice_start", "game_id": game_id, "chatId": int(game["chat_id"])}), color=KeyboardButtonColor.POSITIVE)
        kb.row()
        kb.add(Callback("💰 Поставить ставку", {"command": "dice_join", "game_id": game_id, "chatId": int(game["chat_id"])}), color=KeyboardButtonColor.PRIMARY)
    return kb


async def _dice_lobby_text(game: dict) -> str:
    participants = [int(x) for x in game.get("players", [])]
    lines = []
    for uid in participants:
        lines.append(f"• {await _dice_mention(uid)}")
    participants_text = "\n".join(lines) if lines else "• Пока никто не поставил ставку"
    bank = int(game.get("bet", 0)) * len(participants)
    # Показываем таймер только трёхсекундными шагами. Так он выглядит
    # последовательно: 02:00 -> 01:57 -> 01:54, без значений между тиками.
    raw_remaining = max(0.0, float(game.get("expires_at", 0)) - time.time())
    if raw_remaining <= 0:
        remaining = 0
    else:
        remaining = min(
            int(game.get("timeout_seconds", DICE_GAME_TIMEOUT_SECONDS) or DICE_GAME_TIMEOUT_SECONDS),
            int(((raw_remaining + 2.999999) // 3) * 3),
        )
    minutes, seconds = divmod(remaining, 60)
    return (
        "🎲 Началась игра в кости!\n"
        "Успейте сыграть!\n\n"
        f"Ставка: {_dice_money(int(game.get('bet', 0)))}\n"
        f"Количество участников: {len(participants)}/{int(game.get('max_players', 0))}\n"
        f"До отмены игры: {minutes:02d}:{seconds:02d}\n\n"
        f"Участники:\n{participants_text}\n\n"
        f"Крупье: {await _dice_mention(int(game.get('dealer_id', 0)))}\n"
        f"Банк: {_dice_money(bank)}"
    )


def _dice_store_message_reference(game: dict, *, message_id: int = 0, cmid: int = 0) -> None:
    """Сохраняет идентификатор сообщения без чтения истории беседы."""
    if message_id > 0:
        game["message_id"] = int(message_id)
    if cmid > 0:
        game["conversation_message_id"] = int(cmid)

    chat_id = int(game.get("chat_id", 0) or 0)
    if chat_id <= 0:
        return
    games = _dice_load_games()
    stored = games.get(str(chat_id))
    if not stored or str(stored.get("game_id", "")) != str(game.get("game_id", "")):
        return
    if message_id > 0:
        stored["message_id"] = int(message_id)
    if cmid > 0:
        stored["conversation_message_id"] = int(cmid)
    games[str(chat_id)] = stored
    _dice_save_games(games)


def _dice_edit_lock(chat_id: int) -> asyncio.Lock:
    chat_id = int(chat_id)
    lock = DICE_EDIT_LOCKS.get(chat_id)
    if lock is None:
        lock = asyncio.Lock()
        DICE_EDIT_LOCKS[chat_id] = lock
    return lock


async def _dice_edit_lobby(game: dict, enabled: bool = True, force: bool = False) -> bool:
    """
    Безопасно обновляет одно сообщение лобби.

    - не допускает параллельных messages.edit для одной беседы;
    - перед редактированием берёт свежую версию игры из JSON, чтобы старый
      таймер не затёр новый список участников или банк;
    - пропускает запрос, если текст и состояние клавиатуры не изменились;
    - использует сохранённый message_id/cmid без чтения истории VK.
    """
    chat_id = int(game.get("chat_id", 0) or 0)
    if chat_id <= 0:
        return False

    async with _dice_edit_lock(chat_id):
        # Для активного лобби всегда используем самую свежую сохранённую игру.
        if enabled:
            current = _dice_load_games().get(str(chat_id))
            if (isinstance(current, dict)
                    and str(current.get("game_id", "")) == str(game.get("game_id", ""))
                    and current.get("status") == "waiting"):
                game = current

        message_id = int(game.get("message_id", 0) or 0)
        cmid = int(game.get("conversation_message_id", 0) or 0)
        if message_id <= 0 and cmid <= 0:
            return False

        text = await _dice_lobby_text(game)
        # В ключ включено состояние клавиатуры: финальное отключение кнопок
        # выполнится даже при совпадающем тексте. hash() достаточно, поскольку
        # кэш используется только в памяти текущего процесса.
        content_hash = hash((text, bool(enabled)))
        cache_key = (chat_id, str(game.get("game_id", "")))
        if not force and DICE_LAST_MESSAGE_HASH.get(cache_key) == content_hash:
            return False

        kwargs = {
            "peer_id": int(game["peer_id"]),
            "message": text,
            "keyboard": _dice_keyboard(game, enabled=enabled),
            "group_id": int(game.get("group_id", 0) or groupid),
        }
        if message_id > 0:
            kwargs["message_id"] = message_id
        else:
            kwargs["conversation_message_id"] = cmid

        try:
            # Lock удерживается до завершения API-запроса, поэтому второй edit
            # для этой беседы не начнётся раньше окончания первого.
            await bot.api.messages.edit(**kwargs)
            DICE_LAST_MESSAGE_HASH[cache_key] = content_hash
            return True
        except Exception as exc:
            ref = f"message_id={message_id}" if message_id > 0 else f"cmid={cmid}"
            print(f"[DICE] lobby edit failed: {type(exc).__name__}: {exc}; peer_id={game.get('peer_id')} {ref}")
            return False


async def _dice_delete_lobby(game: dict) -> None:
    cmid = int(game.get("conversation_message_id", 0) or 0)
    if cmid <= 0:
        return
    try:
        await bot.api.messages.delete(
            group_id=int(game.get("group_id", 0) or 0),
            peer_id=int(game["peer_id"]),
            cmids=cmid,
            delete_for_all=True,
        )
    except Exception as exc:
        print(f"[DICE] lobby delete failed: {exc}")


async def _dice_refund_game(chat_id: int, expected_game_id: str = "", reason: str = "Время ожидания истекло") -> bool:
    async with _dice_lock(chat_id):
        games = _dice_load_games()
        game = games.get(str(chat_id))
        if not game or game.get("status") != "waiting":
            return False
        if expected_game_id and str(game.get("game_id")) != str(expected_game_id):
            return False
        players = [int(x) for x in game.get("players", [])]
        bet = int(game.get("bet", 0))
        balances_data = load_data(BALANCES_FILE)
        for uid in players:
            bal = balances_data.get(str(uid)) or get_balance(uid)
            bal["wallet"] = int(bal.get("wallet", 0) or 0) + bet
            balances_data[str(uid)] = bal
        save_data(BALANCES_FILE, balances_data)
        globals()["balances"] = balances_data
        _clear_balance_cache()
        games.pop(str(chat_id), None)
        _dice_save_games(games)
        DICE_LAST_MESSAGE_HASH.pop((int(chat_id), str(game.get("game_id", ""))), None)
        await _dice_delete_lobby(game)
        return True


async def _dice_timeout_worker(chat_id: int, game_id: str, delay: float) -> None:
    try:
        # Первый edit выполняется ровно через 3 секунды после фактической
        # отправки лобби. Далее тики привязаны к времени старта игры, а не к
        # длительности предыдущего API-запроса — накопления задержки нет.
        while True:
            games = _dice_load_games()
            game = games.get(str(chat_id))
            if (not game or game.get("status") != "waiting"
                    or str(game.get("game_id", "")) != str(game_id)):
                return

            expires_at = float(game.get("expires_at", 0) or 0)
            created_at = float(game.get("created_at", expires_at - DICE_GAME_TIMEOUT_SECONDS) or 0)
            now = time.time()
            remaining = expires_at - now
            if remaining <= 0:
                break

            elapsed = max(0.0, now - created_at)
            next_tick_number = int(elapsed // 3.0) + 1
            next_tick_at = created_at + next_tick_number * 3.0
            sleep_for = min(remaining, max(0.05, next_tick_at - now))
            await asyncio.sleep(sleep_for)

            games = _dice_load_games()
            game = games.get(str(chat_id))
            if (not game or game.get("status") != "waiting"
                    or str(game.get("game_id", "")) != str(game_id)):
                return
            if time.time() >= float(game.get("expires_at", 0) or 0):
                break

            await _dice_edit_lobby(game, enabled=True)

        await _dice_refund_game(chat_id, game_id)
    except asyncio.CancelledError:
        return
    except Exception as exc:
        print(f"[DICE] timeout worker failed: {exc}")
    finally:
        current = DICE_TIMEOUT_TASKS.get(int(chat_id))
        if current is asyncio.current_task():
            DICE_TIMEOUT_TASKS.pop(int(chat_id), None)


def _dice_schedule_timeout(game: dict) -> None:
    chat_id = int(game["chat_id"])
    old = DICE_TIMEOUT_TASKS.pop(chat_id, None)
    if old and not old.done():
        old.cancel()
    expires_at = float(game.get("expires_at", time.time()))
    DICE_TIMEOUT_TASKS[chat_id] = asyncio.create_task(
        _dice_timeout_worker(chat_id, str(game.get("game_id", "")), expires_at - time.time())
    )


async def _dice_restore_games() -> None:
    """Восстанавливает таймеры активных лобби после перезапуска бота."""
    games = _dice_load_games()
    if not games:
        return

    restored = 0
    expired = 0
    for raw_chat_id, game in list(games.items()):
        try:
            chat_id = int(raw_chat_id)
            if not isinstance(game, dict) or game.get("status") != "waiting":
                continue

            game_id = str(game.get("game_id", ""))
            if not game_id:
                continue

            if time.time() >= float(game.get("expires_at", 0) or 0):
                expired += 1
                await _dice_refund_game(chat_id, game_id, reason="Бот был перезапущен")
            else:
                _dice_schedule_timeout(game)
                restored += 1
        except Exception as exc:
            print(f"[DICE] restore failed for chat {raw_chat_id}: {exc}")

    if restored or expired:
        print(f"[DICE] restored={restored}, expired_refunded={expired}")


async def _dice_send_result_dm(user_id: int, text: str, game_link: str) -> bool:
    """Отправляет участнику результат игры в ЛС."""
    try:
        await bot.api.messages.send(
            peer_id=int(user_id),
            random_id=0,
            message=str(text),
        )
        return True
    except Exception as exc:
        # Например, пользователь запретил сообщения от сообщества.
        print(f"[DICE] result DM failed for user {user_id}: {exc}")
        return False


async def _dice_finish_game(game: dict) -> dict:
    players = [int(x) for x in game.get("players", [])]
    scores = {uid: random.randint(1, 6) + random.randint(1, 6) for uid in players}
    top = max(scores.values())
    leaders = [uid for uid, value in scores.items() if value == top]
    while len(leaders) > 1:
        rerolls = {uid: random.randint(1, 6) + random.randint(1, 6) for uid in leaders}
        best = max(rerolls.values())
        leaders = [uid for uid, value in rerolls.items() if value == best]
    winner = leaders[0]
    bet = int(game["bet"])
    bank = bet * len(players)
    commission = bank * DICE_DEALER_COMMISSION_PERCENT // 100
    prize = bank - commission
    dealer_id = int(game["dealer_id"])
    balances_data = load_data(BALANCES_FILE)
    winner_bal = balances_data.get(str(winner)) or get_balance(winner)
    winner_bal["wallet"] = int(winner_bal.get("wallet", 0) or 0) + prize
    balances_data[str(winner)] = winner_bal
    dealer_bal = balances_data.get(str(dealer_id)) or get_balance(dealer_id)
    dealer_bal["wallet"] = int(dealer_bal.get("wallet", 0) or 0) + commission
    balances_data[str(dealer_id)] = dealer_bal
    save_data(BALANCES_FILE, balances_data)
    globals()["balances"] = balances_data
    _clear_balance_cache()

    cmid = int(game.get("conversation_message_id", 0) or 0)
    if cmid > 0:
        try:
            await bot.api.messages.delete(
                group_id=int(game.get("group_id", 0) or 0),
                peer_id=int(game["peer_id"]),
                cmids=cmid,
                delete_for_all=True,
            )
        except Exception:
            try:
                await _dice_edit_lobby(game, enabled=False)
            except Exception:
                pass

    sorted_players = sorted(players, key=lambda uid: scores[uid], reverse=True)
    participant_lines = []
    for uid in sorted_players:
        if uid == winner:
            continue
        participant_lines.append(f"• {await _dice_mention(uid)} — {scores[uid]} очков")
    participants_text = "\n".join(participant_lines) if participant_lines else "• Отсутствуют"
    result_text = (
        "🎲 Игра в кости завершена!\n\n"
        f"Победитель: {await _dice_mention(winner)} — {scores[winner]} очков\n"
        f"Выигрыш: {_dice_money(prize)}\n\n"
        f"Участники:\n{participants_text}\n\n"
        f"Крупье: {await _dice_mention(dealer_id)}\n"
        f"Комиссия крупье: {_dice_money(commission)}\n"
        f"Банк: {_dice_money(bank)}"
    )
    send_result = await bot.api.messages.send(
        peer_id=int(game["peer_id"]),
        random_id=0,
        message=result_text,
        disable_mentions=1,
    )

    result_cmid = await _resolve_sent_message_cmid(int(game["peer_id"]), send_result)
    chat_id = int(game.get("chat_id", 0) or 0)
    if result_cmid:
        game_link = f"https://vk.com/im?sel=c{chat_id}&msgid={int(result_cmid)}"
    else:
        # Даже без msgid ссылка откроет нужную беседу.
        game_link = f"https://vk.com/im?sel=c{chat_id}"

    # Рассылаем результат каждому игроку. Ошибка одного ЛС не мешает остальным
    # и не откатывает уже завершённую игру.
    dm_tasks = []
    for uid in players:
        if uid == winner:
            dm_text = (
                "🎉 Вы победили в игре «Кости»!\n\n"
                f"Ваш результат: {scores[uid]} очков\n"
                f"Вы получили: {_dice_money(prize)}\n"
                f"Общий банк: {_dice_money(bank)}"
            )
        else:
            dm_text = (
                "😔 Вы проиграли в игре «Кости».\n\n"
                f"Ваш результат: {scores[uid]} очков\n"
                f"Победный результат: {scores[winner]} очков\n"
                "В следующий раз обязательно повезёт!"
            )
        dm_tasks.append(_dice_send_result_dm(uid, dm_text, game_link))

    dealer_text = (
        "💰 Игра «Кости» завершена.\n\n"
        f"Вы получили комиссию крупье: {_dice_money(commission)}\n"
        f"Общий банк: {_dice_money(bank)}\n"
        f"Победитель получил: {_dice_money(prize)}"
    )
    dm_tasks.append(_dice_send_result_dm(dealer_id, dealer_text, game_link))
    if dm_tasks:
        await asyncio.gather(*dm_tasks, return_exceptions=True)

    return {
        "winner": winner,
        "prize": prize,
        "commission": commission,
        "bank": bank,
        "scores": scores,
        "result_cmid": result_cmid,
        "game_link": game_link,
    }


async def _dice_handle_join(message, chat_id: int, game_id: str) -> bool:
    user_id = int(message.object.user_id)
    async with _dice_lock(chat_id):
        games = _dice_load_games()
        game = games.get(str(chat_id))
        if not game or game.get("status") != "waiting" or str(game.get("game_id")) != str(game_id):
            await answer_callback_event(message, "Эта игра уже завершена")
            return True
        if time.time() >= float(game.get("expires_at", 0)):
            await answer_callback_event(message, "Время игры истекло")
            asyncio.create_task(_dice_refund_game(chat_id, game_id))
            return True
        if user_id == int(game["dealer_id"]):
            await answer_callback_event(message, "Крупье не может участвовать в своей игре")
            return True
        players = [int(x) for x in game.get("players", [])]
        if user_id in players:
            await answer_callback_event(message, "Вы уже участвуете в этой игре")
            return True
        if len(players) >= int(game["max_players"]):
            await answer_callback_event(message, "Все места уже заняты")
            return True
        bet = int(game["bet"])
        balances_data = load_data(BALANCES_FILE)
        bal = balances_data.get(str(user_id)) or get_balance(user_id)
        if int(bal.get("wallet", 0) or 0) < bet:
            await answer_callback_event(message, "Недостаточно средств.")
            return True
        bal["wallet"] = int(bal.get("wallet", 0) or 0) - bet
        balances_data[str(user_id)] = bal
        save_data(BALANCES_FILE, balances_data)
        globals()["balances"] = balances_data
        _clear_balance_cache()
        players.append(user_id)
        game["players"] = players
        games[str(chat_id)] = game
        _dice_save_games(games)
        await answer_callback_event(message, f"Вы потратили {_dice_money(bet)}")
        await _dice_edit_lobby(game, enabled=True)
        return True


async def _dice_handle_start(message, chat_id: int, game_id: str) -> bool:
    user_id = int(message.object.user_id)
    async with _dice_lock(chat_id):
        games = _dice_load_games()
        game = games.get(str(chat_id))
        if not game or game.get("status") != "waiting" or str(game.get("game_id")) != str(game_id):
            await answer_callback_event(message, "Эта игра уже завершена")
            return True
        if user_id != int(game["dealer_id"]):
            await answer_callback_event(message, "Бросить кости может только крупье")
            return True
        if time.time() >= float(game.get("expires_at", 0)):
            await answer_callback_event(message, "Время игры истекло")
            asyncio.create_task(_dice_refund_game(chat_id, game_id))
            return True
        players = [int(x) for x in game.get("players", [])]
        if len(players) < DICE_MIN_PLAYERS:
            await answer_callback_event(message, f"Для начала нужно минимум {DICE_MIN_PLAYERS} игрока")
            return True
        game["status"] = "running"
        games.pop(str(chat_id), None)
        _dice_save_games(games)
        task = DICE_TIMEOUT_TASKS.pop(int(chat_id), None)
        if task and not task.done():
            task.cancel()
        await _dice_finish_game(game)
        await answer_callback_event(message, "Игра завершена — результаты отправлены в ЛС")
        return True

@bot.on.raw_event(GroupEventType.MESSAGE_EVENT, dataclass=GroupTypes.MessageEvent)
async def handlers(message: GroupTypes.MessageEvent):
    global balances
    payload = message.object.payload or {}
    command = str(payload.get("command", "")).lower()
    user_id = message.object.user_id
    chat_id = payload.get("chatId")
    if not chat_id:
        peer_id = int(message.object.peer_id)
        chat_id = peer_id - 2000000000 if peer_id >= 2000000000 else 0

    if await handle_shop_callback(bot, message, answer_callback_event):
        return True

    # Лог для каждой кнопки
    log_cmd = payload.get("log")
    if log_cmd:
        print(f"{user_id} использовал кнопку {command}. ВК выдало: {log_cmd}")
    else:
        print(f"{user_id} использовал кнопку {command}.")
    if command and not await has_required_bot_subscription(user_id):
        await answer_callback_event(message, get_subscription_required_text())
        return True
    refresh_dynamic_economy_prices()
    if chat_id and get_block_game(chat_id) and command in GAME_CALLBACK_COMMANDS:
        await answer_callback_event(message, "Игровые команды отключены в этой беседе")
        return True
    if command == "country_commands_page":
        if not _callback_owner_allowed(payload, user_id):
            await answer_callback_event(message, "Эта кнопка доступна только автору меню")
            return True
        try:
            requested_page = int(payload.get("page", 1) or 1)
        except (TypeError, ValueError):
            requested_page = 1
        page_text, keyboard, current_page, total_pages = _build_country_commands_page(
            page=requested_page,
            owner_id=int(user_id),
        )
        # VK требует подтвердить callback почти сразу. Сначала отвечаем на
        # нажатие, затем редактируем сообщение с меню.
        await answer_callback_event(message, f"Страница {current_page}/{total_pages}")
        try:
            await bot.api.messages.edit(
                peer_id=int(message.object.peer_id),
                conversation_message_id=int(message.object.conversation_message_id),
                message=page_text,
                keyboard=keyboard,
                disable_mentions=1,
            )
        except Exception as exc:
            print(f"[COUNTRY COMMANDS PAGE ERROR] {exc}")
        return True

    if command == "country_citizens_page":
        if not _callback_owner_allowed(payload, user_id):
            await answer_callback_event(message, "Эта кнопка доступна только автору списка")
            return True
        try:
            country_id = int(payload.get("country_id", 0) or 0)
            requested_page = int(payload.get("page", 1) or 1)
        except (TypeError, ValueError):
            country_id = 0
            requested_page = 1
        if country_id <= 0:
            await answer_callback_event(message, "Не удалось определить государство")
            return True
        text_page, keyboard, current_page, total_pages = await _build_country_citizens_page(
            country_id=country_id,
            page=requested_page,
            chat_id=int(chat_id or 0),
            owner_id=int(user_id),
        )
        try:
            await bot.api.messages.edit(
                peer_id=int(message.object.peer_id),
                conversation_message_id=int(message.object.conversation_message_id),
                message=text_page,
                keyboard=keyboard if keyboard.buttons else None,
                disable_mentions=1,
            )
            await answer_callback_event(message, f"Страница {current_page}/{total_pages}")
        except Exception as exc:
            print(f"[COUNTRY CITIZENS PAGE ERROR] {exc}")
            await answer_callback_event(message, "Не удалось открыть страницу")
        return True

    if command == "country_strike_city":
        if not _callback_owner_allowed(payload, user_id):
            await answer_callback_event(message, "Эта кнопка доступна только инициатору запуска")
            return True
        try:
            attacker_country_id = int(payload.get("attacker_country_id", 0) or 0)
            target_country_id = int(payload.get("target_country_id", 0) or 0)
            quantity = int(payload.get("quantity", 1) or 1)
            city_name = str(payload.get("city_name", "") or "")
            strike_type = str(payload.get("strike_type", "missile") or "missile")
        except Exception:
            await answer_callback_event(message, "Некорректные данные запуска")
            return True
        ok, result = await _country_launch_conventional_strike(
            int(user_id), attacker_country_id, target_country_id, city_name, strike_type, quantity
        )
        await answer_callback_event(message, "Запуск выполнен" if ok else result[:80])
        try:
            await bot.api.messages.send(
                peer_id=int(message.object.peer_id), random_id=0,
                message=("✅ " if ok else "❌ ") + result,
                disable_mentions=1,
            )
        except Exception as exc:
            print(f"[COUNTRY STRIKE CALLBACK] {exc}")
        return True

    if command in {"dice_join", "dice_start"}:
        # Нажатие кнопки содержит cmid исходного сообщения — сохраняем его для старых лобби.
        callback_cmid = int(getattr(message.object, "conversation_message_id", 0) or 0)
        if callback_cmid > 0:
            games = _dice_load_games()
            callback_game = games.get(str(int(chat_id or 0)))
            if callback_game and str(callback_game.get("game_id", "")) == str(payload.get("game_id", "")):
                _dice_store_message_reference(callback_game, cmid=callback_cmid)

    if command == "dice_dealers_page":
        try:
            requested_page = int(payload.get("page", 1) or 1)
        except Exception:
            requested_page = 1
        dealers_text, dealers_keyboard, current_page, total_pages = await _dice_dealers_page(requested_page)
        try:
            await bot.api.messages.edit(
                peer_id=int(message.object.peer_id),
                conversation_message_id=int(message.object.conversation_message_id),
                message=dealers_text,
                keyboard=dealers_keyboard,
                disable_mentions=1,
            )
            await answer_callback_event(message, f"Страница {current_page}/{total_pages}")
        except Exception as exc:
            print(f"[DICE DEALERS PAGE ERROR] {exc}")
            await answer_callback_event(message, "Не удалось открыть страницу")
        return True

    if command == "dice_join":
        return await _dice_handle_join(message, int(chat_id or 0), str(payload.get("game_id", "")))
    if command == "dice_start":
        return await _dice_handle_start(message, int(chat_id or 0), str(payload.get("game_id", "")))
    if command == "gzov_disable":
        target_chat_id = int(chat_id or 0)
        if target_chat_id <= 0:
            await answer_callback_event(message, "Не удалось определить беседу")
            return True
        if not await _can_use_command(user_id, target_chat_id, 7):
            await answer_callback_event(message, "Кнопка доступна только владельцу беседы")
            return True
        if await get_gzov_disabled(target_chat_id):
            await answer_callback_event(message, "Глобальная рассылка уже отключена")
            return True
        await set_gzov_disabled(target_chat_id, 1)
        await answer_callback_event(message, "Глобальная рассылка отключена")
        await bot.api.messages.send(
            peer_id=message.object.peer_id,
            random_id=0,
            message="Владелец отключил глобальную рассылку в данный чат.",
            disable_mentions=1,
        )
        return True
    if command in {"exchange_invite_accept", "exchange_invite_decline", "exchange_mode", "exchange_choose_category", "exchange_asset_page", "exchange_pick_asset", "exchange_bonus_set", "exchange_bonus_custom", "exchange_builder_cancel", "exchange_side_bonus_choice"}:
        owner_id = int(payload.get("owner_id", 0) or 0)
        draft_for_owner = _get_exchange_draft(owner_id) if owner_id else None
        if command in {"exchange_invite_accept", "exchange_invite_decline"}:
            if not draft_for_owner:
                await answer_callback_event(message, "Приглашение на обмен уже неактуально")
                return True
            if int(draft_for_owner.get("to_user_id", 0)) != user_id:
                await answer_callback_event(message, "Ответить на приглашение может только второй пользователь")
                return True
            if command == "exchange_invite_decline":
                property_exchange_drafts.pop(int(owner_id), None)
                await exchange_log(
                    user_id=user_id,
                    target_id=int(owner_id),
                    status="declined",
                    log="отклонил(-а) приглашение на обмен",
                )
                await answer_callback_event(message, "Приглашение отклонено")
                try:
                    await delete_message(groupid, message.object.peer_id, message.object.conversation_message_id)
                except Exception:
                    pass
                await bot.api.messages.send(
                    peer_id=message.object.peer_id,
                    random_id=0,
                    message="❌ Приглашение на обмен отклонено.",
                    disable_mentions=1,
                )
                try:
                    await bot.api.messages.send(
                        peer_id=int(owner_id),
                        random_id=0,
                        message=f"❌ [id{user_id}|{draft_for_owner['to_name']}] отклонил(а) ваше приглашение на обмен.",
                        disable_mentions=1,
                    )
                except Exception:
                    pass
                return True
            draft_for_owner["invite_accepted"] = True
            property_exchange_drafts[int(owner_id)] = draft_for_owner
            await exchange_log(
                user_id=user_id,
                target_id=int(owner_id),
                status="invite_accepted",
                log="принял(-а) приглашение на обмен",
            )
            await answer_callback_event(message, "Приглашение принято")
            try:
                await delete_message(groupid, message.object.peer_id, message.object.conversation_message_id)
            except Exception:
                pass
            await bot.api.messages.send(
                peer_id=message.object.peer_id,
                random_id=0,
                message=f"✅ Вы приняли приглашение на обмен от [id{owner_id}|{draft_for_owner['from_name']}].\nТеперь он выбирает условия сделки.",
                disable_mentions=1,
            )
            await bot.api.messages.send(
                peer_id=message.object.peer_id,
                random_id=0,
                keyboard=None,
                message=f"📨 [id{owner_id}|{draft_for_owner['from_name']}], приглашение на обмен принято.\nТеперь выберите тип сделки кнопками ниже.",
                disable_mentions=1,
            )
            try:
                await bot.api.messages.send(
                    peer_id=int(owner_id),
                    random_id=0,
                    message=f"✅ [id{user_id}|{draft_for_owner['to_name']}] принял(а) ваше приглашение на обмен.",
                    disable_mentions=1,
                )
            except Exception:
                pass
            await bot.api.messages.send(
                peer_id=message.object.peer_id,
                random_id=0,
                keyboard=await _build_exchange_side_start_keyboard(int(owner_id), "from"),
                message="🤝 Настройка обмена доступна автору приглашения.",
                disable_mentions=1,
            )
            return True
        if owner_id and owner_id != user_id:
            await answer_callback_event(message, "Эта кнопка доступна только автору обмена")
            return True
        draft = _get_exchange_draft(user_id)
        if command == "exchange_builder_cancel":
            await exchange_log(
                user_id=int(draft["from_user_id"]),
                target_id=int(draft["to_user_id"]),
                status="cancelled",
                log="отменил(-а) создание обмена",
            )
            property_exchange_drafts.pop(int(user_id), None)
            await answer_callback_event(message, "Создание обмена отменено")
            try:
                await delete_message(groupid, message.object.peer_id, message.object.conversation_message_id)
            except Exception:
                pass
            await bot.api.messages.send(peer_id=message.object.peer_id, random_id=0, message="❌ Создание обмена отменено.", disable_mentions=1)
            return True
        if not draft:
            await answer_callback_event(message, "Черновик обмена уже неактуален")
            return True
        if not draft.get("invite_accepted"):
            await answer_callback_event(message, "Обмен начнётся только после принятия приглашения вторым пользователем")
            return True
        if command == "exchange_mode":
            mode = str(payload.get("mode", "") or "")
            side = str(payload.get("side", "") or "")
            if side not in {"from", "to"} or mode not in {"asset", "money"}:
                await answer_callback_event(message, "Неизвестный тип обмена")
                return True
            draft[f"{side}_entry_type"] = mode
            draft[f"{side}_category"] = None
            draft[f"{side}_asset_id"] = None
            draft[f"{side}_needs_bonus"] = mode == "money"
            draft["awaiting_bonus_side"] = side if mode == "money" else None
            draft["awaiting_bonus_prompt_side"] = None
            draft["awaiting_custom_bonus"] = False
            if mode == "money":
                draft[f"{side}_money_bonus"] = 0
            property_exchange_drafts[int(user_id)] = draft
            await answer_callback_event(message, "Тип обмена выбран")
            if mode == "money":
                kb = _build_exchange_side_amount_keyboard(user_id, side)
                text = "💰 Теперь укажите сумму доплаты для этой стороны."
            else:
                kb = await _build_exchange_category_keyboard(user_id, side)
                text = "📦 Теперь выберите категорию имущества."
            try:
                await delete_message(groupid, message.object.peer_id, message.object.conversation_message_id)
            except Exception:
                pass
            await bot.api.messages.send(peer_id=message.object.peer_id, random_id=0, keyboard=kb, message=text, disable_mentions=1)
            return True
        if command == "exchange_choose_category":
            side = str(payload.get("side", "") or "")
            category = str(payload.get("category", "") or "")
            if side not in {"from", "to"} or category not in {"business", "item", "case", "money"}:
                await answer_callback_event(message, "Ошибка выбора категории")
                return True
            draft[f"{side}_category"] = category
            draft[f"{side}_asset_id"] = None
            draft["awaiting_bonus_side"] = None
            draft["awaiting_bonus_prompt_side"] = None
            draft["awaiting_custom_bonus"] = False
            property_exchange_drafts[int(user_id)] = draft
            kb, text = await _build_exchange_asset_picker(user_id, side, 1)
            await answer_callback_event(message, "Открываю список объектов")
            if not kb.buttons:
                await bot.api.messages.send(
                    peer_id=message.object.peer_id,
                    random_id=0,
                    keyboard=await _build_exchange_category_keyboard(user_id, side),
                    message=f"{text}\n\nВыберите другую категорию.",
                    disable_mentions=1,
                )
                return True
            try:
                await delete_message(groupid, message.object.peer_id, message.object.conversation_message_id)
            except Exception:
                pass
            await bot.api.messages.send(peer_id=message.object.peer_id, random_id=0, keyboard=kb if kb.buttons else None, message=text, disable_mentions=1)
            return True
        if command == "exchange_asset_page":
            side = str(payload.get("side", "") or "")
            page = int(payload.get("page", 1) or 1)
            kb, text = await _build_exchange_asset_picker(user_id, side, page)
            await answer_callback_event(message, "Листаю список")
            try:
                await delete_message(groupid, message.object.peer_id, message.object.conversation_message_id)
            except Exception:
                pass
            await bot.api.messages.send(peer_id=message.object.peer_id, random_id=0, keyboard=kb if kb.buttons else None, message=text, disable_mentions=1)
            return True
        if command == "exchange_pick_asset":
            side = str(payload.get("side", "") or "")
            asset_id = int(payload.get("asset_id", 0) or 0)
