                sql.execute(f"INSERT OR IGNORE INTO custom_roles_{chat_id} (level, name) VALUES (100, 'Владелец беседы')")
                sql.execute(f"CREATE TABLE IF NOT EXISTS permissions_{chat_id} (user_id BIGINT, level BIGINT)")
